export default [{"id":79,"question":"سائلٌ يقول: كيف يكون التَّعامل مع الرافضة الذين خالطونا في البلاد في مثل هذه الحالات، إذا كانوا طلابًا أو مُدرسين، وإذا كانوا أطباء أو مرضى، وإذا كانوا زُملاء في العمل؟","title":"ما كيفية معاملة الزملاء من الرافضة؟","answer":"الجواب: مَن أعلن بدعته وجب هجرُه، فمَن أعلن بدعته من الغلو في أهل البيت: في عليٍّ وفاطمة وأهل البيت، وبُغض الصَّحابة، هذا يُهجر؛ لأنَّ عبادة أهل البيت وبُغض الصَّحابة كفرٌ وردَّةٌ عن الإسلام، فمَن أظهر بدعته يُهْجَر ولا يُوالى، ولا يُسلَّم عليه، ولا يستحقُّ أن يكون مُعلِّمًا ولا غيره، لا يُؤمن في وظائف.\nومَن لم يُظهر بدعته، ولم يُبين شيئًا، وأظهر الإسلامَ مع المسلمين؛ يُعامل معاملة المسلمين، كما قال ﷺ في الحديث الصَّحيح لما سُئل: أي الإسلام أفضل؟ قال: أن تُطعم الطعام وتقرأ السلام على مَن عرفتَ ومَن لم تعرف.\nفمَن أظهر الإسلام فهو أخونا، نُسلِّم عليه، ونرد عليه السلام، ومَن أظهر الشرك والبدعة فليس أخانا: إن كان شركًا فقد كفر، وإن كان بدعةً فيستحق الهجر عليها حتى يدعها وينقاد إلى الحقِّ، وهكذا مَن أظهر المعاصي: كالزنا، وشرب الخمر؛ يستحق أن يُهْجَر وإن كان مسلمًا حتى يتوب إلى الله من شرب الخمر ومن إظهار ما أظهر من المنكرات.","link":"https://binbaz.org.sa/fatwas/3057/ما-كيفية-معاملة-الزملاء-من-الرافضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0056.mp3","categories":["الفرق والمذاهب"]},{"id":416,"question":"هل يجوز تكفير الشِّيعة؟","title":"ما حكم تكفير الشِّيعة؟","answer":"الجواب: الشيعة أقسام وأنواع، ذكرها بعضُهم اثنتين وعشرين نوعًا –يعني: فرقة- لكن الباطنية منهم: كالجعفرية، والإمامية أتباع الخميني الاثنا عشرية، هؤلاء لا شكَّ في كفرهم؛ لأنهم رافضة، خصوصاً قادتهم وأئمتهم الذين يدعون إلى الشرك بالله وعبادة أهل البيت، ويغلون في عليٍّ، ويعبدونه من دون الله، وفي الحسن والحسين، ويرون أنهم يعلمون الغيب، وأنهم معصومون، ويدَّعون أنَّ عليًّا هو الإله، هكذا النُّصيرية، وهكذا الإسماعيلية، هؤلاء من أكفر الناس، القادة والأئمَّة منهم والكبار. أما عامَّتهم فهم جهلة ضالون، لكن أئمَّتهم الكبار وعلماءهم يعرفون هذه الأمور، ويعتقدون هذه الأمور -نعوذ بالله- ومن أضلّ الناس وأبعدهم عن الهدى -نسأل الله العافية.\nوفيهم شيعة جهله، لا يغلون في أهل البيت، ولا يعبدونهم من دون الله، ولا يعتقدون أنهم يعلمون الغيب، ولكن يُفضلون عليًّا ويقولون: علي أفضل من الصديق، وأفضل من عمر، هذا غلطٌ وجهلٌ ومعصيةٌ، لكن ما يكونون كفَّارًا، يكونون عصاةً، ويكونون مبتدعةً، ولا يكونون كفَّارًا، إلا إذا غلوا في أهل البيت وعبدوهم من دون الله، وقالوا في عليٍّ وأهل البيت أنهم يعلمون الغيب، أو أنه تجوز عبادتهم من دون الله، أو قالوا أنهم أفضل من الأنبياء، وأنهم فوق محمدٍ والأنبياء، كما يقول الخميني في رسالته \"الحكومة الإسلامية\"، يقول: \"إن أئمتنا بلغوا منزلةً ما بلغها ملك مُقرَّب ولا نبي مرسل\" -نسأل الله العافية.\nوحُكَّام إيران اليوم من أضلّ الناس وأكفرهم، وإن تظاهروا بالإسلام -نعوذ بالله-؛ لأنهم دعاة للشرك، دعاة لعبادة غير الله، دعاة للرفض، دعاة لسبِّ الصحابة، ولعن الصحابة، والغلو في عليٍّ وأهل البيت، وأنهم معصومون يعلمون الغيب، وأنهم يُعْبَدون ويُدْعَون من دون الله: يُستغاث بهم، ويُنذر لهم، إلى غير ذلك -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/4834/ما-حكم-تكفير-الشيعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0474.mp3","categories":["الفرق والمذاهب"]},{"id":435,"question":"سمعنا يا سماحة الشيخ أنك تقول بأنه ليس هناك فرقٌ بين أهل السنة والشيعة إلا ببعض الفروع، فهل هذا صحيح أم لا؟ وهل هناك فعلًا فرقٌ بين أهل السنة والشِّيعة؟","title":"ما الفرق بين أهل السنة والشيعة؟","answer":"الجواب: هذا من العجائب، هذا كذبٌ وافتراءٌ -نسأل الله العافية- هذا كذبٌ، ولم يصدر مني هذا الكلام، ولا قريب من هذا الكلام، بل بيننا وبينهم مثل ما بين السماء والأرض، ولا سيما بينهم وبين الرافضة، الرافضة والنُّصيرية وأشباههم طوائف باطنية.\nوالشيعة أقسام، هم ليسوا قسمًا واحدًا، أقسام كثيرة، وفِرَقٌ كثيرة، حتى ذكرهم شيخُ الإسلام اثنتين وعشرين فرقة، هم أقسام، بعضهم ضالٌّ، وبعضهم يُفضّل عليًّا فقط على عثمان، وبعضهم يُفضله على الصديق وعمر، لكن لا يسبُّون، ولا يعبدون عليًّا، ولا يغلون فيه، هؤلاء شيعة، لكن أمرهم سهل، لا يضرُّهم ذلك من جهة الدين، وإن كانوا قد أخطأوا في مخالفة أهل السنة في التفضيل، لكن لا يضرُّهم مثل ضرر الطوائف الأخرى.\nومنهم مَن يسبُّ معاوية، وهؤلاء أيضًا قد أخطأوا وغلطوا، وعليهم إثم ذلك، ومنهم مَن يسبُّ عائشة كذلك، لكن فيهم طوائف باطنية، يعبدون عليًّا، ويعبدون أهل البيت، ويستغيثون بهم، وينذرون لهم، ويعتقدون أنهم يعلمون الغيب، ويَسُبُّون أصحاب النبي صلى الله عليه وسلم، ويُكفِّرونهم، ويقولون: إنهم ظلموا عليًّا وأخذوا عنه الولاية، إلا النفر القليل من أصحاب النبي لا يسبُّونهم: كعمار وسلمان والمقداد بن الأسود ونفر قليل.\nفالحاصل أن الشيعة أقسام، وبينهم وبين أهل السنة فرقٌ بعيدٌ، خصوصًا الباطنية منهم: فأهل السنة يُوالون الصحابة، ويُحبُّونهم، ويترضون عنهم، ويعتقدون أنهم أفضل الأمة، وخير الأمة، والرافضة والنُّصيرية وأشباههم بضدِّ ذلك. وأهل السنة يعبدون الله وحده، ويقولون: الغيب لله، لا يعلمه إلا الله، والرافضة والباطنية بخلاف ذلك. فالفرق عظيمٌ جدًّا، ومَن أراد ذلك فليُراجع ما كتبه الناسُ في هذا، مثل: \"منهاج السنة\" لشيخ الإسلام ابن تيمية، ومثل: \"وجاء دور المجوس\" لعبدالله محمد غريب، ومثل الكتب الأخرى: كتب الشيخ حافظ إحسان، وغيره ممن كتب في هذا الباب، وفي هذا كتابات كثيرة.","link":"https://binbaz.org.sa/fatwas/4859/ما-الفرق-بين-اهل-السنة-والشيعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0493.mp3","categories":["الفرق والمذاهب"]},{"id":810,"question":"الحداثة منهجٌ فكريٌّ إلحاديٌّ يُنكره الإسلام، فما هو واجب المسلمين تجاه هذا المنهج؟ وهل هذه الدَّعوة الهدَّامة منهجٌ فكريٌّ أدبيٌّ كما يدَّعي الحداثيون أم هو منهجٌ فكريٌّ شاملٌ للحياة؟ أفيدونا جزاكم الله خير الجزاء.","title":"ما واجب المسلمين تجاه الحداثيين؟","answer":"الجواب: حكم هذا المذهب الجديد الحداثي حكم غيره من المنكرات، الحداثيون حسبما علمنا منهم لهم أساليب جديدة غريبة مُعقَّدة، قصدوا بها الخداع -خداع الناس- والدعوة إلى الباطل بصفةٍ مُقنَّعةٍ ملفوفةٍ لا ينتبه لها كلُّ أحدٍ.\nفالحداثيون يجب الإنكار عليهم، وبيان زيفهم وباطلهم، ولا يجوز السماح لهم بالنشر؛ لأنهم مُضلون يدعون إلى محاربة الشريعة، وإنكار كل قديم، وأن يكون الإنسان حرًّا يفعل ما يشاء ولا يتقيد بقرآنٍ ولا سنةٍ، بل كالبهيمة ليس لها ما يحجزها من عقلها وعلمها، فهؤلاء هم أشباه أولئك: أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ إِنْ هُمْ إِلَّا كَالْأَنْعَامِ بَلْ هُمْ أَضَلُّ سَبِيلًا [الفرقان:44].\nوليس مذهبًا أدبيًّا، ولكنه مذهبٌ إلحاديٌّ، مذهب كفرٍ، مذهب ضالٌّ مُضلٌّ يجب القضاء عليه.","link":"https://binbaz.org.sa/fatwas/20840/ما-واجب-المسلمين-تجاه-الحداثيين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0637ما واجب المسلمين تجاه الحداثيون؟ ابن باز فتاوى المحاضرات.mp3","categories":["الفرق والمذاهب"]},{"id":821,"question":"يقول بعضُ طلبة العلم: إن الأشاعرة من أهل السنة والجماعة، فهل ذلك حقٌّ؟ وما الضَّابط في ذلك؟","title":"هل الأشاعرة من أهل السنة والجماعة؟","answer":"الجواب: الأشاعرة من أهل السنة في أشياء، وليسوا من أهل السنة في أشياء، هم من أهل السنة فيما وافقوا أهلَ السنة فيه، وهم ليسوا منهم فيما خالفوا أهلَ السنة: من تأويل الكثير من الصِّفات، ومن أشياء أخرى يعرفها مَن قرأ عقيدتهم، فلا يجوز أن يقال أنهم ليسوا من أهل السنة مطلقًا، ولا من أهل السنة مطلقًا، ولكنَّهم من أهل السنة فيما وافقوا فيه أهلَ السنة، ولهم جهودٌ عظيمةٌ في العلم: كابن حجر، والنووي، والمازري، وجماعة كثيرين، ابن الطيب الباقلاني، وغيرهم، وهم مُتفاوتون في تأويل الصِّفات، وفيما يُنتقد عليهم في العقيدة متفاوتون، وهم لهم جهودٌ عظيمةٌ، وعلمٌ جمٌّ، وآثارٌ مشكورةٌ لا يجوز إنكارها، ولكن مع هذا كلهم لا يجوز تقليدهم فيما أخطأوا فيه.","link":"https://binbaz.org.sa/fatwas/20849/هل-الاشاعرة-من-اهل-السنة-والجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0645يقول بعض العلماء أن الأشاعرة من أهل السنة والجماعة فهل هذا حق ؟.mp3","categories":["الفرق والمذاهب"]},{"id":823,"question":"كثر الكلامُ في الآونة المُتأخرة عن الحَدَاثة، نرجو من سماحتكم بيان حقيقتها، وحكم الإسلام فيها، وما حكم مَن يُرَوِّج لها مع علمه بحقيقتها؟","title":"ما حقيقة \"الحَدَاثة\" وما حكم الإسلام فيها؟","answer":"الجواب: الحَدَاثة أدبٌ جديدٌ مكشوفٌ لمن تأمَّله، خفيٌّ على مَن لم يتأمله، فالذي علمنا من حالهم وقرأنا عنهم أنهم طائفة يخفون إلحادهم وباطنهم في عبارات وفي أشعار مُعقَّدة غير واضحةٍ، ويستعملون ألفاظًا جديدةً ليست على الطريقة العربية والأسلوب العربي، ويقصدون بها معاني غامضة، وهدفهم مما ظهر منهم: نَبْذُ الإسلام والشريعة الإسلامية، ونبذ كل قديمٍ، ومُعاداة كل قديمٍ، وأنهم يُريدون ترويج الأشياء الجديدة من الغرب والشرق، وأن تكون الأمةُ في غايةٍ من الحرية؛ لتعمل ما تُريد من كل فسادٍ وشرٍّ، وليس لها قائدٌ ولا قيودٌ، بل تعمل ما تشاء، وترفض ما تشاء.\nفهم فيما ظهر من كلامهم يرفضون كلَّ ما يُسمَّى: قديمًا، ومعلومٌ أن الشريعة قديمةٌ، وأنه مرَّ عليها الآن أربعة عشر قرنًا، فهم يُحاربونها، ولكن يتسترون بعبارات غير واضحةٍ، وربما صرَّحوا وبيَّنوا في بعض الأحيان، ومَن تأمَّل كتاباتهم وقرأ مقالاتهم اتَّضح له ذلك.\nوقد ألَّف أخونا الشيخ عوض بن محمد القرني رسالةً في ذلك، ذكر فيها شيئًا كثيرًا من كلماتهم، وقد اطلعتُ على أكثرها -أكثر الكتاب- وكتبتُ عليه ما تيسر.\nفنصيحتي لأصحاب الحداثة أن يتَّقوا الله، وأن يرجعوا إلى دين الله، وأن يتكلَّموا باللغة العربية الواضحة إن كانوا يُريدون الخير، وأن يُظهروا الحقَّ والهدى والصواب، وأن يبتعدوا عن مُعاداة الإسلام وأهله، وأن يكونوا صُرحاء: إمَّا بإلحادهم حتى يُقتلوا، أو يُنفوا من الأرض، وإما بتوبتهم إلى الله، حتى يُحبَّهم المسلمون، وحتى يُساعدوهم على الخير.\nونصيحتي لأهل العلم أن يُتابعوا مقالاتهم وكتاباتهم، وأن يفضحوهم في ذلك، حتى يرجعوا إلى الصواب، وحتى يؤبوا إلى رشدهم، ونسأل الله أن يمُنَّ عليهم بالهداية.","link":"https://binbaz.org.sa/fatwas/20847/ما-حقيقة-الحداثة-وما-حكم-الاسلام-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0643بيان حقيقة الحداثة وحكم الإسلام فيها؟ ابن باز فتاوى الممحاضرات.mp3","categories":["الفرق والمذاهب"]},{"id":854,"question":"ما دور العقل تجاه العقيدة الإسلامية؟ وما موقفنا من أهل البدع والأهواء؟ وهل يجوز هجرهم؟","title":"دور العقل تجاه العقيدة وكيفية مواجهة الأهواء","answer":"الجواب: دور العقل في هذا التَّفهم والتَّعقل، ومعرفة المعنى، والنظر في الأسانيد -فيما يتعلق بالسنة- وصحّتها، وليس له أن يُقدّم ما يرى على الكتاب والسنة، بل..... يجب أن تخضع للكتاب والسنة، وليس لأهل الإسلام أن يُقدِّموا عقولهم أو آراءهم على ما قاله الكتاب والسنة، لا، فالعقل تابعٌ، وإنما وظيفته أن يتأمّل ويتفقه ويعمل، وليس له أن يشرع، فالذين شرعوا من الجهمية والمعتزلة وغيرهم هلكوا ووقعوا في أنواعٍ من الباطل؛ لتقديمهم العقول على النصوص، والواجب إخضاع العقول وإخضاع القلوب وإخضاع النفوس للنصوص، وأن يكون المؤمن تابعًا لكتاب الله، ولما صحَّت به السنةُ عن رسول الله صلى الله عليه وسلم، ولكن يستعمل عقله في معرفة المعنى، في صحَّة الحديث وعدم صحَّته، يسأل أهل العلم، ينظر في الطرق المؤدية إلى ذلك، هذه هي وظيفة العقل، أما أن يُقدّم رأيه على ما ثبت أنه من شرع الله فلا.","link":"https://binbaz.org.sa/fatwas/20888/دور-العقل-تجاه-العقيدة-وكيفية-مواجهة-الاهواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0683ما هو دور العقل تجاه العقيدة الإسلامية وما هو موقفنا من أهل البدع والأهواء؟ ابن باز.mp3","categories":["الفرق والمذاهب"]},{"id":858,"question":"لقد ظهرت في ساحة العمل الإسلامي جماعات شتَّى، فهذه تبليغية، وتلك إخوانية، وأخرى صوفية طرقية، إلى غير ذلك من الفِرَق، وقد التبس بذلك الحقُّ بالباطل على كثيرٍ من المسلمين، فنرجو منكم بيان السبيل الذي يجب أن تسلكه الجماعات المسلمة التي ينبغي الالتزام بها.","title":"ما موقف المسلم تجاه الجماعات الإسلامية؟","answer":"الجواب: الجماعات -مثلما أشار السائل- كثيرون، ولكن ينبغي للمؤمن أن يسلك المسلك الصالح، ويساعد كل جماعةٍ بما عندها من الحقِّ، وينصحها بترك ما عندها من الباطل إذا استطاع ذلك، فإن لم يستطع فليكن مع أقربها إلى الحقِّ: يُعينها، ويُكثّر سوادها، ويُرشدها حتى لا تموت هذه الجماعة، وقد قال النبيُّ ﷺ في الحديث الصحيح -حديث حذيفة- لما سأله حذيفةُ في آخر حديثه، لما قال: يا رسول الله، كنا في جاهليةٍ وشرٍّ، فجاءنا الله بهذا الخير –يعني: على يديك- فهل بعد هذا الخير من شرٍّ؟ قال: نعم، فقال حذيفةُ: وهل بعد ذلك الشرّ من خيرٍ؟ قال: نعم، وفيه دَخَنٌ، قلت: وما دخنه؟ قال: قومٌ يهدون بغير هدي، ويستنون بغير سُنتي، تعرف منهم وتُنْكِر، فقال حذيفةُ: وهل بعد ذلك الخير من شرٍّ؟ قال: نعم، دُعاةٌ على أبواب جهنم، مَن أجابهم إليها قذفوه فيها، قلت: صِفْهُم لنا يا رسول الله، قال: هم من جلدتنا، ويتكلَّمون بألسنتنا، قال: فما تأمرني يا رسول الله إن أدركني ذلك؟ قال: تلزم جماعة المسلمين وإمامهم، قلت: وإن لم يكن لهم جماعة؟ قال: فاعتزل تلك الفرق كلها، ولو أن تعضَّ على أصل شجرةٍ حتى يُدركك الموت وأنت على ذلك متفقٌ على صحته.\nهذا أمره ﷺ عند تغير الأحوال: أن يلزم جماعة المسلمين، فالجماعة التي ترى أنها أقرب إلى الحقِّ وأقرب إلى الهدى تلزمها وتُعينها، ولو كان فيها نقصٌ، ولو كان فيها أخطاء، تُعينها على الصواب، وتُرشدها إلى الخطأ؛ لأنها جماعة مسلمين، جماعة من المسلمين.\nأما إن كانت جماعةً كافرةً: تدعو إلى الباطل، وتدعو إلى خلاف القرآن والسنة، وتدعو إلى غير الدين، لا، حاربها، لا تكن معها، لكن ما دام أنها تدعو إلى الإسلام: كجماعة الإخوان المسلمين، وجماعة أنصار السنة، والجماعات التبليغية، أو غيرهم من الجماعات التي تدعو إلى الإسلام وتقيم الدعوة إلى الإسلام، وتقول: إنها مسلمة، فالواجب أن تُساعدها على الخير، وأن تُرشدها إلى ما عندها من الباطل، وأن تكون أنت وإخوانك عونًا لها على الخير، وعونًا لها على ترك الباطل، حتى لا تهدموها في حقِّها وباطلها، بل تهدم الباطل وترفع الحقَّ، ولا تكونوا إرْبًا على إخوانكم، تُعادونهم، وتُشنعون عليهم لأجل بعض الباطل، وأنت عندك من الباطل أيضًا شيءٌ، ولكن تُعينهم على ما عندهم من الحقِّ، وتجتهد في صفاء القلوب والتأليف بين الجماعات المسلمة، وبما عندها من الحقِّ حتى تثبت عليه، وبيان ما عندها من الباطل حتى تتركه بالدليل، بالأدلة، والتفاهم، والأسلوب الحسن، والنفس الطيبة، لا بالعنف والشدة، هكذا ينبغي.\nفالإخوان المسلمون عندهم نقصٌ، وجماعة التبليغ عندها نقصٌ، وجماعة أنصار السنة عندهم نقصٌ، وهكذا، ما أحد عنده الكمال من كل الوجوه، فلا بد من التعاون على الخير، ولا بدّ من الصبر، ولا بدّ من الحكمة، والأسلوب الحسن، وسعة البال، وانشراح الصدر، لا يكون الإنسانُ ضيق العطن عنيفًا في كلامه مع إخوانه؛ فيعود الجميع إلى الشَّحناء والعداوة، لا، بل يكون عنده اللُّطف ورحابة الصدر، والتأمل والتحمّل، وإرشاد الناس إلى الخير، وتثبيتهم عليه، وإرشادهم إلى ما عندهم من الباطل وتحذيرهم منه بالأسلوب الحسن، هكذا ينبغي لك أيها المؤمن، وأيها الطالب، أينما كنت: في مصر، في الشام، في الهند، في باكستان، في أي مكانٍ تكن هكذا، في أي مكانٍ يمكن، مثلًا: في بلادك أو غيرها.","link":"https://binbaz.org.sa/fatwas/20892/ما-موقف-المسلم-تجاه-الجماعات-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0687بيان السبيل الصحيح الذي يجب أن يسلكه الجماعات المسلمة والتي ينبغي الالتزام بها؟ ابن باز.mp3","categories":["الفرق والمذاهب"]},{"id":861,"question":"يقول هذا السائل بأن التَّصوف ظاهرةٌ خطيرةٌ انتشرت في ديار الإسلام، ولأعداء الإسلام دور كبيرٌ في نشرها والدَّعوة إليها، فما توجيه سماحتكم للحذر من التَّصوف؟ وماذا يجب على المسلم في أعماله التَّعبدية والاعتقادية؟","title":"كيف يحذر المسلم من البدع والتصوف؟","answer":"الجواب: يجب على المسلم أن يحذر كلَّ ما أُحدث من البدع: من التصوف، وغير التصوف، وأن يلزم الطريق السَّوي الذي سلكه الصحابةُ على عهد النبي ﷺ وبعده، وسلكه أتباعُهم بإحسانٍ، وليحذر ما ابتدعه الناسُ: التصوف، وغير التصوف، وهو إحداث طرقٍ خاصَّةٍ يتبع فيها فرقةً أو شيخَ شيخه، أو فلانًا، أو فلانًا في الأذكار، أو في الصَّلوات، كل ذلك بدعة.\nالواجب اتِّباع النبي ﷺ في ذلك سلوك مسلك النبي ﷺ والسير على منهاجه وأصحابه رضي الله عنهم وأرضاهم. أما ما أحدثه الناسُ من البدع فالواجب تركها، والحذر منها، كما قال عليه الصلاة والسلام: وشرُّ الأمور مُحدثاتها، وكل بدعةٍ ضلالة، وقال: إياكم ومحدثات الأمور، وقال عليه الصلاة والسلام: مَن عمل عملًا ليس عليه أمرُنا فهو ردٌّ.\nفالمؤمن يتوقَّف في الدين، ويتبصَّر، ويأخذ بطريق السلف الصالح، ويسير على نهجهم، ويُحذِّر إخوانَه مما يُخالف ذلك بالكلام الطيب والحكمة والرفق.","link":"https://binbaz.org.sa/fatwas/20910/كيف-يحذر-المسلم-من-البدع-والتصوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0705ماهو رأي  سماحتكم في التصوف؟ ابن باز فتاوى المحاضرات.mp3","categories":["الفرق والمذاهب"]},{"id":873,"question":"هل الأشاعرة أهل سنة وجماعة؟ ما حكم الشرع فيمَن يُلزم الناسَ اتِّباع منهج الأشاعرة، وخاصَّةً في الجامعات؟","title":"هل الأشاعرة من أهل السنة والجماعة؟","answer":"الجواب: الأشاعرة عندهم شيءٌ من مذهب أهل السنة، وعندهم شيءٌ من مخالفة السنة، فهم مع أهل السنة فيما وافقوا فيه أهل السنة، وهم مخالفون له فيما خالفوه فيه من تأويل بعض الصِّفات، وجميع ما يُؤخذ عليهم مما يُخالف أهل السنة لا يكونون من أهل السنة فيه، فكل كلمةٍ أو قاعدةٍ تخرج من الأشاعرة أو غير الأشاعرة بما يُخالف أهل السنة يُعتبر ذلك حَدَثًا منهم، وغلطًا منهم، لا يُتابَعون عليه، ومن ذلك التأويل -تأويل بعض الصفات- فأهل السنة لا يؤولون الصِّفات، بل يُمرونها كما جاءت، كما قال مالك رحمه الله والنسائي، وربيعة، وغيرهم: \"أمرُّوها كما جاءت، بلا كيفٍ\"، وهكذا أهل السنة يُمرونها كما جاءت، لا يُحرِّفون، ولا يُعطِّلون، ولا يُمَثِّلون، بل يؤمنون بما دلَّت عليه الآيات والأحاديث، مع عدم التأويل، مع اعتقاد قوله سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِير [الشورى:11].\nفالرضا والغضب والنزول والاستواء والرحمة والسمع والبصر والكلام كله بابٌ واحدٌ، يمرونها كما جاءت، فسمعه ليس كالأسماع، وبصره ليس كالأبصار، وكلامه ليس كالكلام، وغضبه ليس كذلك، وهكذا بقية الصفات: ضحكه، رضاه، كراهته، إلى غير ذلك، كلها بابها واحد: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِير، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4].\nفعلينا أن نُمرها كما جاءت، وأن نُؤمن بها، ولا نُحرف، ولا نُغير، ولا نُبدل، ولا نُؤول، بل نقول: هي حقٌّ وثابتةٌ لله، ومعانيها حقٌّ ثابتة لله، ولكنها ليست من جنس صفات المخلوقين، الله جلَّ وعلا له الكمال من كل الوجوه، والعبد له النَّقص، ولهذا قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِير، هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:19]، فَلَا تَضْرِبُوا لِلَّهِ الْأَمْثَالَ [النحل:74]، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ، فهو يغضب حقيقةً، لكن ليس كغضبنا، يضحك حقيقةً ليس كضحكنا، يرضى حقيقةً ليس كرضانا، يسمع لا كسمعنا، يرى لا كرُؤيتنا، إلى غير ذلك، له الكمال في كل شيءٍ .","link":"https://binbaz.org.sa/fatwas/20897/هل-الاشاعرة-من-اهل-السنة-والجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0692هل الأشاعرة من أهل السنة والجماعة؟ ابن باز فتاوى المحاضرات.mp3","categories":["الفرق والمذاهب"]},{"id":881,"question":"ما عقيدة المُرجئة؟ وما أثرها على المُجتمع؟","title":"ما عقيدة المُرجئة؟ وما حكمها؟","answer":"الجواب: تقدَّم لنا أنَّ المرجئة أقسامٌ: منهم مَن يرى أن الإيمان قولٌ فقط: كالكراميَّة. ومنهم مَن يرى أنه مجرد معرفةٍ: كالجهمية. ومنهم مَن يرى أنه قولٌ وتصديقٌ: كمُرجئة الفقهاء -كما ذكر الطَّحاوي في العقيدة- وكلها خطأ، وكلها غلط.\nوالصواب الذي عليه أهلُ السنة والجماعة أنَّ الإيمان قولٌ وعملٌ: قول القلب واللسان، وعمل القلب والجوارح -كما تقدَّم- يزيد بالطاعات، وينقص بالمعاصي، هذا قول أهل السنة، وهو الذي دلَّ عليه كتابُ الله وسنةُ رسوله عليه الصلاة والسلام، كما قال جلَّ وعلا في كتابه المبين: لَيْسَ الْبِرَّ أَنْ تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ وَلَكِنَّ الْبِرَّ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَالْمَلَائِكَةِ وَالْكِتَابِ وَالنَّبِيِّينَ وَآتَى الْمَالَ عَلَى حُبِّهِ ذَوِي الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينَ وَابْنَ السَّبِيلِ وَالسَّائِلِينَ وَفِي الرِّقَابِ وَأَقَامَ الصَّلَاةَ وَآتَى الزَّكَاةَ وَالْمُوفُونَ بِعَهْدِهِمْ إِذَا عَاهَدُوا وَالصَّابِرِينَ فِي الْبَأْسَاءِ وَالضَّرَّاءِ وَحِينَ الْبَأْسِ أُولَئِكَ الَّذِينَ صَدَقُوا وَأُولَئِكَ هُمُ الْمُتَّقُونَ [البقرة:177]، فجعل هذا كله صدق، كله أعمال، كله إيمان، كله تقوى، والآيات في هذا كثيرة.\nومنها قول النبي ﷺ لوفد عبد القيس: آمركم بالإيمان بالله، ثم فسَّر ذلك بشهادة أن لا إله إلا الله، وأنَّ محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وأداء الخمس، وقال عليه الصلاة والسلام: الإيمان بضعٌ وستون شعبة -أو قال: بضعٌ وسبعون شعبة- فأفضلها قول: لا إله إلا الله، وأدناها إماطة الأذى عن الطريق، والحياء شعبةٌ من الإيمان، فجعل قول \"لا إله إلا الله\" -وهي قولٌ- جعلها أفضل الإيمان، وأفضل الشُّعَب، وجعل الحياء من شعب الإيمان، وجعل إماطة الأذى من الطريق من شعب الإيمان، وهكذا الصلاة والصوم والجهاد وغير ذلك، كله من شعب الإيمان.\nفهو قولٌ وعملٌ كما تقدَّم: قول القلب واللسان، وعمل القلب والجوارح، يزيد بالطاعات، وينقص بالمعاصي، كما تقدَّم.","link":"https://binbaz.org.sa/fatwas/20919/ما-عقيدة-المرجىة-وما-حكمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0714ما هي عقيدة المرجئة؟ ابن باز فتاوى المحاضرات.mp3","categories":["الفرق والمذاهب"]},{"id":971,"question":"كيف ردُّ سماحتكم على مَن يقول: إن أهل السعودية وهَّابيون؟ وهل نحن نعترف بهذا الاسم؟ وهل الوهابية مذهبٌ يُخالف مذهب أهل السنة والجماعة؟","title":"ما الرد على القول بأن أهل السعودية وهَّابيون","answer":"الجواب: هذا الوصف أطلقه عليهم خصومُهم الذين لم يعرفوا حقيقةَ ما هم عليه، أو عرفوها ولكن تجاهلوها لأسبابٍ أخرى، لأسبابٍ دنيوية، وأسباب أخرى سياسية، وهم أتباع الشيخ محمد بن عبدالوهاب رحمه الله؛ لأنَّ الشيخ محمد رحمه الله قام بالدعوة في وسط القرن الثاني عشر، الدعوة إلى توحيد الله، لما رأى أهل نجدٍ قد وقعوا في الشرك، وعبادة القبور، والاستغاثة بأهلها، والأشجار، والأحجار، وقد هداه الله وفتح قلبه فدعاهم إلى الله، وأرشدهم، وألَّف المؤلفات الجيدة، وساعده على ذلك علماء من علماء نجد وغيرهم من العلماء في الخارج الذين عرفوا ما دعا إليه، فقد دعا إلى توحيد الله، والإخلاص له، وترك عبادة الأوثان، والأصنام، والقبور، ونحو ذلك، فلُقِّب أتباعه بالوهابيين، لقَّبهم خصومُهم وأعداؤهم، أو الجُهَّال الذين لم يعرفوا ما هم عليه.\nوحقيقة دعوة الشيخ محمد دعوة سلفية، الدعوة إلى توحيد الله، واتِّباع الرسول ﷺ، هي الدعوة إلى ما عليه أهلُ السنة والجماعة، هي الدعوة إلى عقيدة السلف الصالح، وهي توحيد الله، والإخلاص له، واتباع رسوله محمد عليه الصلاة والسلام، والسير على منهاج السلف الصالح، هذه دعوة الشيخ محمد، ليس له مذهبٌ خاصٌّ، دعوته هي دعوة أئمة السلف فيما كان عليه أصحابُ الرسول ﷺ.\nليس له دينٌ زائفٌ، وليس له دعوةٌ تُخالف ما عليه خلاف الأمة، ولكن خصومه وأعداءه الذين جهلوا دعوته، أو تجاهلوها، أو لبَّس عليهم بها وخبرهم عنها الجهّال بها؛ سمُّوهم بهذا اللقب: الوهابيين؛ للتَّنفير عنهم، والتَّحذير من اتباع ما هم عليه من الحقِّ والهدى.\nفينبغي لمن عرف هذا أن يتبصَّر، وأن يُبصر الناس، وأن يُخبرهم أن الوهابية ليست مذهبًا خامسًا، ولا  دينًا جديدًا، بل هي دعوة إلى توحيد الله، وإلى ما عليه السلف الصالح من أصحاب النبي ﷺ وأتباعهم بإحسانٍ، وهي الدعوة إلى توحيد الله، والإخلاص له، ومُتابعة رسوله محمد عليه الصلاة والسلام، ليس إلا هذه، هي الحقيقة، ولكن بعض الناس قد جهلها، أو قلَّد مَن جهلها، والله المستعان.","link":"https://binbaz.org.sa/fatwas/21011/ما-الرد-على-القول-بان-اهل-السعودية-وهابيون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0808كيف رد سماحتكم على من يقول أن أهل السعودية وهيابيُّون؟ ابن باز فتاوى المحاضرات.mp3","categories":["الفرق والمذاهب"]},{"id":1038,"question":"تكلمتَ عن وجوب الأخذ بالكتاب والسنة، ووجد جماعةٌ يُقال لهم: القرآنيون، فما موقفنا منهم؟","title":"ما حكم من ينكر السنة بزعم الاكتفاء بالقرآن؟","answer":"الجواب: مثلما تقدَّم، ليسوا قرآنيين، ولكنَّهم كذَّابون، أعداء للقرآن؛ لأنَّ القرآن أمر بالسنة، وأمر بطاعة الرسول ﷺ، ومَن أنكر السنة فقد أنكر القرآن، ومَن عصى الرسول فقد عصى القرآن، فليسوا قرآنيين، ولكنَّهم ضد القرآن، وملاحدة، وضالُّون، بل كفَّار بإجماع أهل العلم. مَن أنكر السنة ولم يعمل بها وزعم أنَّه لا يعمل إلا بالقرآن؛ فهو كاذبٌ، لم يعمل بالقرآن، وضالٌّ مُضِلٌّ، كافرٌ بإجماع أهل العلم، وقد كتبتُ في هذا رسالةً مطبوعةً سميتُها \"وجوب العمل بالسنة\".","link":"https://binbaz.org.sa/fatwas/21087/ما-حكم-من-ينكر-السنة-بزعم-الاكتفاء-بالقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0883وجد جماعة يقال لهم القرآنيون فما رأي سماحتكم؟ ابن باز فتاوى المحاضرات.mp3","categories":["الفرق والمذاهب","نواقض الإسلام"]},{"id":1427,"question":"المُتَصوِّفة هل يدخلون في جملة الكفار؟","title":"حكم المُتَصوِّفة وحكم وصفهم بالكفر؟","answer":"الجواب:\nلا، المُتَصوِّفة أقسام، هناك صوفية عندهم بعض البدع، وهم مشركون يعبدون غير الله، يعبدون أصحاب القبور، وهم أقسام وأنواع.\nس: الذين يعبدون أصحابَ القبور؟\nج: الذين يعبدون أصحابَ القبور هؤلاء كفار.\nس: هؤلاء من جملة الكفار؟\nج: يعبدون البدوي، والحسين، والحسن، وابن علوان، وأشباههم، فلهذا هم كفار، أو يعبدون النبي ﷺ، أو يعبدون غيره من الأموات، أو يعبدون الجن، يستعيذون به، ويلجؤون إليه، هذا من الشرك الأكبر.\nس:  هؤلاء يُبْدَؤُون بالتوحيد؟\nج: هؤلاء يُبْدَؤُون بالتوحيد، يُعلَّمون التوحيد.","link":"https://binbaz.org.sa/fatwas/21522/حكم-المتصوفة-وحكم-وصفهم-بالكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المتصوفة.mp3","categories":["الفرق والمذاهب"]},{"id":1556,"question":"حكم \"المُفَوِّضَة\" (في الأسماء والصفات)؟","title":"حكم \"المُفَوِّضَة\" في الأسماء والصفات","answer":"الجواب:\nيقال لهم: مُفَوِّضَة، ويقال لهم: مُفَوَّضَة.\nس: أقصد: في باب الأسماء والصِّفات؟\nج: على خلاف بين أهل السنة والجماعة: بعض أهل العلم يرى أنهم شرٌّ من الجهمية.","link":"https://binbaz.org.sa/fatwas/21658/حكم-المفوضة-في-الاسماء-والصفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المُفَوِّضَة.mp3","categories":["الفرق والمذاهب"]},{"id":4086,"question":"س: الخوارج يكفِّرون بالذنوب؟","title":"هل الخوارج يكفِّرون بالذنوب؟","answer":"الجواب: الله أعلم، المعروف عنهم التكفير بالذنوب، وبعضهم يحكي عنهم الكبائر، ويحتاج إلى تدقيق في كتبهم، كتبهم موجودة، ولهم بقايا الآن في عُمان، وفي الجزائر، وفي ليبيا، لهم بقايا، وهم الإباضية، لكن المتأخِّرون منهم كأنهم خفّفوا بعض الشيء، اجتمعنا ببعضهم يقولون: ما نقول: كافر، لكن مُخلَّد في النار، كأنهم مالوا إلى رأي المعتزلة، والمعنى واحد؛ إذا قالوا: مُخلَّد في النار، فهو معناه كفره.\n... المشهور عن العلماء أنهم يقولون إنهم يكفّرون بالذنوب مطلقًا، لكن لعلهم يُريدون الذنوب التي فيها وعيد مثل الكبائر.","link":"https://binbaz.org.sa/fatwas/24326/هل-الخوارج-يكفرون-بالذنوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في مذهب الخوارج.mp3","categories":["الفرق والمذاهب"]},{"id":4238,"question":"العلمانيون هل كفرهم أكبر ؟","title":"ما معنى العلمانية وحكم المنتسبين إليها؟","answer":"الجواب: العلمانيون ما يؤمنون بالدين، يدعون الدنيا، ما يؤمنون بالله ولا باليوم الآخر، هذا العلماني يدعو إلى متابعة العالمين، وأن يكون على رأي العالمين في شركهم وضلالهم وخرافاتهم.\nس: هم يقولون بفصل الدين عن الدولة؟\nج: هذا معناه، ما عندهم دين، يدعون إلى العالمية.\nس: إذًا كفار؟\nج: نعم.\nس: يقولون الدين في المسجد أما برا المسجد لا؟\nج: ولو، بعضهم ما يرى الدين بالكلية، يرى الدعوة إلى ما عليه الناس وبس.","link":"https://binbaz.org.sa/fatwas/24505/ما-معنى-العلمانية-وحكم-المنتسبين-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على العلمانيين.mp3","categories":["الفرق والمذاهب","نواقض الإسلام"]},{"id":4739,"question":"القدرية مجوس هذه الأمة؟","title":"لماذا كانت القدرية مجوس هذه الأمة؟","answer":"جاء في عدة أحاديث، ذكر شيخُ الإسلام ابن تيمية وغيره أنها بمجموعها يشدّ بعضها بعضًا؛ لأنهم أنكروا بعضَ أفعال الله، والمجوس قالوا بالإلهين؛ ولهذا شابهوا المجوس.","link":"https://binbaz.org.sa/fatwas/25067/لماذا-كانت-القدرية-مجوس-هذه-الامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا كانت القدرية مجوس هذه الأمة.mp3","categories":["شروح الحديث","الفرق والمذاهب"]},{"id":4758,"question":"والزَّيدية منسوبون إلى زيدٍ هذا؟","title":"إلى من تنتسب الزَّيدية في اليمن","answer":"إلى زيد بن علي بن الحسين، وكان أصل مذهبهم تفضيل عليٍّ على الصدّيق وعمر فقط، وهم المعروفون الآن في اليمن، وفيهم طوائف رديئة يُقال لهم: الجارودية، أشبه بالرافضة، يزيدون فيلعنون ويسبُّون.","link":"https://binbaz.org.sa/fatwas/25113/الى-من-تنتسب-الزيدية-في-اليمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إلى من تنتسب الزَّيدية في اليمن.mp3","categories":["الفرق والمذاهب"]},{"id":5122,"question":"سائلٌ يقول: كيف يكون التَّعامل مع الرافضة الذين خالطونا في البلاد في مثل هذه الحالات، إذا كانوا طلابًا أو مُدرسين، وإذا كانوا أطباء أو مرضى، وإذا كانوا زُملاء في العمل؟","title":"كيف يعامل أهلُ السنة من يخالطونهم من الرافضة؟","answer":"الجواب: مَن أعلن بدعته وجب هجرُه، فمَن أعلن بدعته من الغلو في أهل البيت: في عليٍّ وفاطمة وأهل البيت، وبُغض الصَّحابة، هذا يُهجر؛ لأنَّ عبادة أهل البيت وبُغض الصَّحابة كفرٌ وردَّةٌ عن الإسلام، فمَن أظهر بدعته يُهْجَر ولا يُوالى، ولا يُسلَّم عليه، ولا يستحقُّ أن يكون مُعلِّمًا ولا غيره، فلا يُؤمن في وظائف. ومَن لم يُظهر بدعته، ولم يُبِنْ شيئًا، وأظهر الإسلامَ مع المسلمين؛ يُعامل معاملة المسلمين، كما قال ﷺ في الحديث الصَّحيح لما سُئل: أي الإسلام أفضل؟ قال: أن تُطعم الطعام، وتقرأ السلام على مَن عرفتَ ومَن لم تعرف. فمَن أظهر الإسلام فهو أخونا، نُسلِّم عليه، ونرد عليه السلام، ومَن أظهر الشرك والبدعة فليس أخانا: إن كان شركًا فقد كفر، وإن كان بدعةً فيستحق الهجر عليها حتى يدعها وينقاد إلى الحقِّ، وهكذا مَن أظهر المعاصي: كالزنا، وشرب الخمر؛ يستحق أن يُهْجَر وإن كان مسلمًا حتى يتوب إلى الله من شرب الخمر ومن إظهار ما أظهر من المنكرات.","link":"https://binbaz.org.sa/fatwas/30035/كيف-يعامل-اهل-السنة-من-يخالطونهم-من-الرافضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 56.mp3","categories":["الفرق والمذاهب"]},{"id":5241,"question":"سائل يقول: سمعنا عن فتوى لكم في «الحداثة»، فنرجو منكم أن تُقدِّموا لنا موقفكم من الحداثة، وما موقفنا من أصحاب الحداثة؟ وجزاكم الله خيرًا.","title":"ما حكم ظاهرة «الحداثة» والمنتسبين إليها؟","answer":"الجواب: قرأنا عنها كتابات قبيحة شنيعة، صنَّف في ذلك أخونا عوض بن محمد القرني رسالةً جمع فيها جماعات منهم، ونقل شيئًا من كلامهم، والصحف التي ذكرت ذلك، وعلى ما ظهر لي من حالهم حسب ما قرأتُ من كلماتهم: أنهم ملاحدة، يدعون إلى الفساد، ويدعون إلى نبذ الشريعة، ويتوصلون إلى هذا بعبارات غامضة خفيَّة لا يعقلها الناس، ومبتغاها وغايتها نبذ القديم، وعدم الخضوع للقديم، وهذا معناه ما جاء به الرسولُ ﷺ، يعني: محاربة كل قديم، وموالاة الجديد، هذا معناه أنهم يُحاربون الصلاة، ويحاربون الإسلام، ويحاربون كل شيءٍ قديم، ولهم تصريحات قبيحة قرأتها عنهم. فمَن كان بهذه المثابة فلا شكَّ أنه يجب هجره والبراءة منه، والتحذير منه، ودعوته إلى التوبة إلى الله، أما إذا كانت لها أشياء غير هذا قليلة ما نعرفها، هذا شيء آخر. المقصود الذي قرأته عنهم، وذكرهم أخونا الشيخ عوض في كتابه، هؤلاء شرُّهم عظيم، يجب الحذر منهم، وهم حدث يجب إزالته، سموا أنفسهم: حداثة، وهم حدث يجب أن يُزالوا، يجب أن يُقضى عليهم، مَن عُرف منهم يُستتاب، فإن تاب وإلا قُتِلَ، كيف يقول هذا الكلام؟! .....  يقول: نحارب البدع، نحارب ما حرَّمه الله، ما يُخالف، أما أن نُحارب كل قديم: فالصلاة قديمة، والحج قديم، والصيام قديم، والزكاة قديمة: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، الأمر بالمعروف والنهي عن المنكر، كل هذه قديمة جاء بها الرسولُ ﷺ، نحارب هذا؟! مَن قال: إنَّ هذا يُحارب؛ فهو كافرٌ ومرتدٌّ عند جميع العلماء، أو قال: إنَّ بعضه يُحارب، حتى لو قال: الحج وحده يُحارب، فقط الحج وحده، أو الصيام وحده؛ كفر، ما هو بجميع ما جاء به الرسولُ، لو قال: واحد من هذه يُحارب ولا يُشرع له؛ كفر ..... التوحيد والصلاة والصيام والحج والجهاد كلها تُحارب؟! يعني: ما يخضع إلا لما أحدثه هم، ما أحدثه اليهود والنَّصارى أو ..... أو الشيوعيون. المقصود أن الحداثية حسبما علمتُ عنهم خُبثاء ملاحدة، يجب أن يُحاربوا، وأن يُستتابوا، فإن تابوا وإلا قُتلوا، إلا مَن أظهر توبته فالحمد لله.","link":"https://binbaz.org.sa/fatwas/30652/ما-حكم-ظاهرة-الحداثة-والمنتسبين-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 511.mp3","categories":["الفرق والمذاهب"]},{"id":5350,"question":"إذا قالوا: مُرجئة الفقهاء؟","title":"ما المقصود بمُرجئة الفقهاء؟","answer":"الجواب: مُرجئة الفقهاء الذين يقولون: العمل ليس من الإيمان، يقولون: الإيمان قولٌ وإقرارٌ وتصديقٌ. يعني كما يُذكر عن أبي حنيفة وغيره. وأهل السنة والجماعة يقولون: الإيمان قول وعمل: قول القلب واللسان، وعمل القلب والجوارح. الصلاة من الإيمان، والصوم من الإيمان، والزكاة من الإيمان، وهي عمل، والجهاد من الإيمان، وهو عمل؛ ولهذا قال جلَّ وعلا: إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ إِذَا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ آيَاتُهُ زَادَتْهُمْ إِيمَانًا وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ ۝ الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ [الأنفال:3]، وقال جلَّ وعلا: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ [التوبة:71]، جعل هذا كله إيمانًا، هذا هو قول أهل الحقِّ، فإذا ترك بعضَ الإيمان: تارةً يَكْفُر؛ كترك الصلاة على الصحيح، وتارة يكون ناقص الإيمان: كترك الصوم، أو الحج مع الاستطاعة، أو الزكاة، يكون ناقصَ الإيمان، ضعيف الإيمان، مُعرَّضًا للوعيد، نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/31045/ما-المقصود-بمرجىة-الفقهاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fat7_majed 005.mp3","categories":["الفرق والمذاهب"]},{"id":5353,"question":"هل الخوارج كفَّار؟","title":"هل الخوارج والإباضية كفَّار؟","answer":"الجواب: المشهور عند العلماء أنهم عُصاة، والقول بتكفيرهم هو أظهر في الأدلة؛ لأنَّ الرسول قال فيهم: يمرقون من الإسلام ثم لا يعودون إليه، فظاهر السنة أنهم كفَّار، وهم الذين يُكفرون الصحابة ويُفسقونهم، ويُكفرون أهل الكبائر ويعتقدون خلودهم في النار، وهذه عقائد خبيثة باطلة، وقول مَن قال بتكفيرهم أظهر. س: الإباضية يا شيخ على نفس شاكلة الخوارج القدامى؟ ج: هم من بقية الخوارج، لكنَّهم لا يتظاهرون بتكفير العُصاة، لكن يقولون: إنهم مخلدون في النار، العاصي مُخلد في النار، على طريقة الخوارج والمعتزلة. على كل حالٍ هم على مذهب الخوارج والمعتزلة في تخليد العُصاة في النار، ولكنَّهم قد لا يُصرحون بتكفير العاصي، ويُنكرون الرؤية -رؤية الله يوم القيامة وفي الجنة- قولهم خبيث.[1]","link":"https://binbaz.org.sa/fatwas/31050/هل-الخوارج-والاباضية-كفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fat7_majed 007.mp3","categories":["الفرق والمذاهب"]},{"id":5515,"question":"من قال أن الاختلاف بين أهل السنة والجماعة وبين الرافضة اختلاف في الفروع فقط؟","title":"ما نوع الخلاف بين أهل السنة والرافضة؟","answer":"الجواب: الاختلاف في العقيدة؛ يعتقدون في أهل البيت: يدعونهم مع الله، يستغيثون بهم، ينذرون لهم، مثلما يفعل المشركون الآخرون مع اللات والعزى والملائكة والأنبياء والصالحين. س: ما حكم هذا الشخص الذي يقول هذا الكلام؟ ج: يُبين له أنه جاهل بعقيدتهم، يُوضح له ما هي عقيدتهم، عقيدتهم الغلو في آل البيت، الغلو في عليٍّ على الأخص، والحسن والحسين وفاطمة وبنات النبي ﷺ، لا سيما الحسن والحسين وعلي، يزعمون أنهم ينفعون مَن استغاث بهم، يُخلصونه وينجونه من عذاب الله، وأنَّ الله جعل لهم كرامةً. وبعضهم يعتقد أنَّ عليًّا هو النبي، وأن جبريل خان الرسالةَ، يُسمونهم: المخونة، وبعضهم يغلون فيه: إذا دعوه نفعهم، وإذا استغاثوا كشف كُربتهم؛ ولهذا كثير منهم يقول: يا علي، يا علي، إذا قام، وإذا قعد: يا حسين، يا حسين، يا فاطمة، مثلما نقول: يا الله، يا الله.[1]","link":"https://binbaz.org.sa/fatwas/31448/ما-نوع-الخلاف-بين-اهل-السنة-والرافضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 030.mp3","categories":["الفرق والمذاهب"]},{"id":5525,"question":"الجهمية هل هم مُرجئة من كل وجهٍ؟","title":"ما وجه الشبه بين الجهمية والمرجئة؟","answer":"الجواب: الجهمية يرون أنَّ العبد مجبور على أفعاله، يُسمون: مُجبرة، يرون العبدَ مجبورًا، ما له اختيار، ما عندهم نفي الأسماء والصِّفات، نعوذ بالله، وهم كفار كفرًا أكبر. س: يُشبهون المرجئة في شيءٍ؟ ج: قد يُقال: إنهم يُشبهون؛ لأنهم يقولون: مجبور، ما عليه حساب، ويلزم على قولهم أنَّ الله ظالم لهم. س: يُشبهون المرجئة بقولهم أنَّ الإيمان تصديق بالقلب؟ ج: عندهم الإيمان معرفة.[1]","link":"https://binbaz.org.sa/fatwas/31458/ما-وجه-الشبه-بين-الجهمية-والمرجىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 040.mp3","categories":["الفرق والمذاهب"]},{"id":6063,"question":"نرجو إعطاءنا فكرة عن النصيرية، وهل هم شيعة يعدون خارجين عن العقيدة الإسلامية الصحيحة؟","title":"حقيقة النصيرية","answer":"الجواب: النصيرية طائفة من الباطنية، طائفة من الرافضة الباطنية الذين يؤلهون عليًّا في الباطن، ويجعلونه إلهًا، هذا هو المعروف عنهم، وكتب عنهم شيخ الإسلام ابن تيمية رسالة صغيرة فضحهم فيها، وبين عقائدهم الباطلة، وأنهم من جملة الرافضة الباطنية الذين يغلون في علي، فليسوا على الإسلام، وإن تظاهروا بالإسلام، بل هم ناس من جملة الرافضة الباطنية الذين يؤلهون عليًا، ويرون أنه إله -نسأل الله العافية والسلامة- ولا يرضون بالإسلام، ولا يدينون بالإسلام الذي عليه المسلمون.  وهكذا الرافضة الاثنا عشرية الجعفرية المعروفة الآن في إيران يقال لهم: الرافضة، ويقال لهم: الاثنا عشرية، ويقال لهم: الإمامية، وهم أصولهم خبيثة، يرون أن أئمتهم يعلمون الغيب، وأنهم معصومون، ويدعون من دون الله، ويستغاث بهم، وينذر لهم، إلى غير ذلك، فأصول الرافضة الباطنية، وجماعتهم، وفرقهم كلها أصول خبيثة، كلها أصول مخالفة لشرع الله  نسأل الله العافية والسلامة.","link":"https://binbaz.org.sa/fatwas/1500/حقيقة-النصيرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_430.mp3","categories":["الفرق والمذاهب"]},{"id":6242,"question":"أيهما أخطر الشيوعية على المسلمين، أو النصيرية العلمانية، ومتى نشأت؟ ومن كان زعيمها؟","title":"خطورة الفرق الضالة على الإسلام","answer":"الجواب:\nكلها شر على المسلمين، النصيرية من الباطنية عباد غير الله، ويزعمون أن إلههم علي، ويعبدون أهل البيت، والنصيرية، وسائر الباطنية من الشيعة كلهم أعداء الإسلام، وكلهم متجمعون ضد الإسلام، وإن تظاهروا، ونافقوا في بعض الأشياء.  ولكن الشيوعية أصرح منهم في الباطل، وأظهر في الباطل، هم يتسترون، وينافقون، أما الشيوعية فقد لا تنافق، قد تظهر شرها إذا أمنت، وقدرت، وإذا لم تقدر؛ نافقت مثلهم. الشيوعية إن لم تقدر على إظهار باطلها؛ نافقت مثلهم، وأظهرت الإسلام، وصلوا مع الناس وهم شيوعيون، يصلون مع الناس، يسمعون الخطب، ويحضرون مع الناس، ويسمعون ويرون، وهم على عقيدة فاسدة، كالرافضة، وأشباه الرافضة، عندهم التقية عند الحاجة، وعندهم الستر عند الحاجة، فإذا أمنوا؛ أظهروا شرهم، وفسادهم الباطنية مثل: النصيرية، وغيرهم، والرافضة وغيرهم من أنواع الفرق الباطنية. وهكذا الشيوعيون أينما كانوا، متى كانت لهم السيطرة؛ أظهروا شرهم، وفسادهم، وخبثهم، ومتى غلبوا؛ كتموا أمورهم، وتظاهروا بالنفاق، والإسلام، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1754/خطورة-الفرق-الضالة-على-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_593.mp3","categories":["الفرق والمذاهب"]},{"id":6245,"question":"وسؤال آخر ما هو الفرق بين الشيوعية، والماسونية؟","title":"الفرق بين الشيوعية والماسونية","answer":"الشيخ: الشيوعية لهم شأن، والماسونية لهم شأن، الشيوعية: معروف أمرهم يتظاهرون بأنه لا دين، ولا رب، ولا إله، ولا جنة، ولا نار، ولا غير ذلك، وأن المال مشاع بين الناس، والنساء مشاعة بين الناس. وأما الماسونية فيما ذكروا: يتظاهرون بالإخاء والمساواة، وأنه ينبغي أن يكون الإنسان كالإنسان في الإخاء، والتسوية، فلا دين، ولا شريعة، ولا غير ذلك، ولكن إخوة إنسانية، هذه الماسونية فيما ذكر، وفيما كتب عنها كثيرًا يتظاهر بالإخاء، والمساواة، والمعنى إنكار الأديان، وإنكار كل شيء، وأن يكون الإنسان مع الإنسان بلا دين، ولا اتباع شريعة، ولا إيمان برب، ولا غير ذلك، بل كبهيمة الإنعام، نسأل الله العافية. وهم يتلاقون مع الشيوعيين في إنكار الآخرة، وإنكار الأنبياء، وإن كان خالفهم الشيوعيون في طلب السيطرة، والفضل بين الناس، وظلم الناس، والاستبداد بالأموال، وإشاعة الفحشاء بين الناس، هؤلاء يميلون إلى السيطرة، والحكم، وظلم الناس، والماسونيون يميلون إلى تهدئة الأوضاع بين الناس، وينكرون الأديان، ويدعون الأديان بسهولة، وطريقة لينة، ليس فيها شدة؛ حتى يكون الإنسان مع الإنسان على غير شيء، بل على مجرد الإنسانية فقط كالبهيمة.","link":"https://binbaz.org.sa/fatwas/1755/الفرق-بين-الشيوعية-والماسونية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_594.mp3","categories":["الفرق والمذاهب"]},{"id":6258,"question":"أحد الإخوة يقول: بالرغم من كمال الشريعة إلا أنه ما زال هناك ممن ينتسب للإسلام من يعبد الله عن طريق المنامات، ويأمر بها أتباعه، خاصة في الطرق الصوفية التي أصبحت هي أصل الدين في كثير من البلاد المسلمة بالرغم من تفرقها، نرجو توضيح خطورة هذا الأمر!","title":"خرافات وشركيات صوفية","answer":"الجواب:  الدين هو التمسك بشرع الله الذي جاء به كتاب الله، وسنة رسوله -عليه الصلاة والسلام- وليس هناك شرع بعد محمد -عليه الصلاة والسلام- فالمنامات ليست تشريعية، المنامات والحكايات عن الماضين، وما أشبه ذلك، أو عن المشايخ، كل هذه الخرافات لا وجه لها، ولا يجوز الاعتماد عليها في بيان حلال، أو حرام، وإنما الحلال، والحرام ما أحله الله، ورسوله، وما حرمه الله، ورسوله. أما ما يفعله الصوفية من: عبادة الشيوخ، وتعظيم الشيوخ، وتحليل ما أحلوا، وتحريم ما حرموا من غير دليل، ولا برهان؛ فهذا ضلال، وكفر -والعياذ بالله- وخروجًا عن الإسلام، نسأل الله العافية، هذا ما يفعله بعضهم، وما عند بعضهم من البدع، والخرافات، وتشريع شيء ما شرعه الله، كذلك بدعة، ومنكر، وهكذا ما يفعله بعضهم من عبادة شيخه، والتوجه إليه بقلبه، يدعوه، ويستغيث به، وينذر له، ويسأله قضاء الحاجات، وتفريج الكروب، والمدد عند الكروب، هذا كله كفر، وضلال، سواء كان حيًا، أو ميتًا، نسأل الله العافية. فالصوفية: عندهم عجائب، وغرائب من أنواع الشرك، والضلالات، والبدع، والمعاصي، فينبغي الحذر من شرهم، والحذر مما هم عليه من الباطل.  والواجب على أهل العلم: أن يوضحوا للناس حالهم، وأن كل طائفة في أي بلد يجب أن يوضح حالها من علماء الحق، وأن يوضحوا له أيضًا ما هم فيه من الباطل، وأن يناظروهم، ويجتهدوا حتى يوضحوا لهم الحق، وحتى يخرجوهم مما هم فيه من الباطل.  وهذه طوائف كثيرة في الشام، وفي العراق، وفي إفريقيا، وفي مصر، وفي بلاد كثيرة، يجب على أهل العلم هناك، وعلى كل من استطاع السبيل إلى معرفة ما هم فيه من الباطل بالتفصيل أن يبين باطلهم بالتفصيل، وهذا يحتاج إلى دراسة أحوالهم، والوقوف على ما هم عليه من الباطل تفصيلًا، ثم بيان ذلك بالكتابات، وفي الصحف، وفي المجلات حتى يبين الباطل، وحتى يوضح الحق.","link":"https://binbaz.org.sa/fatwas/1760/خرافات-وشركيات-صوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_599.mp3","categories":["الفرق والمذاهب"]},{"id":6267,"question":"أحد الإخوة يقول: بالرغم من كمال الشريعة إلا أنه ما زال هناك ممن ينتسب للإسلام من يعبد الله عن طريق المنامات، ويأمر بها أتباعه، خاصة في الطرق الصوفية التي أصبحت هي أصل الدين في كثير من البلاد المسلمة بالرغم من تفرقها، نرجو توضيح خطورة هذا الأمر!","title":"خرافات وشركيات صوفية","answer":"الجواب:  الدين هو التمسك بشرع الله الذي جاء به كتاب الله، وسنة رسوله -عليه الصلاة والسلام- وليس هناك شرع بعد محمد -عليه الصلاة والسلام- فالمنامات ليست تشريعية، المنامات والحكايات عن الماضين، وما أشبه ذلك، أو عن المشايخ، كل هذه الخرافات لا وجه لها، ولا يجوز الاعتماد عليها في بيان حلال، أو حرام، وإنما الحلال، والحرام ما أحله الله، ورسوله، وما حرمه الله، ورسوله. أما ما يفعله الصوفية من: عبادة الشيوخ، وتعظيم الشيوخ، وتحليل ما أحلوا، وتحريم ما حرموا من غير دليل، ولا برهان؛ فهذا ضلال، وكفر -والعياذ بالله- وخروجًا عن الإسلام، نسأل الله العافية، هذا ما يفعله بعضهم، وما عند بعضهم من البدع، والخرافات، وتشريع شيء ما شرعه الله، كذلك بدعة، ومنكر، وهكذا ما يفعله بعضهم من عبادة شيخه، والتوجه إليه بقلبه، يدعوه، ويستغيث به، وينذر له، ويسأله قضاء الحاجات، وتفريج الكروب، والمدد عند الكروب، هذا كله كفر، وضلال، سواء كان حيًا، أو ميتًا، نسأل الله العافية. فالصوفية: عندهم عجائب، وغرائب من أنواع الشرك، والضلالات، والبدع، والمعاصي، فينبغي الحذر من شرهم، والحذر مما هم عليه من الباطل.  والواجب على أهل العلم: أن يوضحوا للناس حالهم، وأن كل طائفة في أي بلد يجب أن يوضح حالها من علماء الحق، وأن يوضحوا له أيضًا ما هم فيه من الباطل، وأن يناظروهم، ويجتهدوا حتى يوضحوا لهم الحق، وحتى يخرجوهم مما هم فيه من الباطل.  وهذه طوائف كثيرة في الشام، وفي العراق، وفي إفريقيا، وفي مصر، وفي بلاد كثيرة، يجب على أهل العلم هناك، وعلى كل من استطاع السبيل إلى معرفة ما هم فيه من الباطل بالتفصيل أن يبين باطلهم بالتفصيل، وهذا يحتاج إلى دراسة أحوالهم، والوقوف على ما هم عليه من الباطل تفصيلًا، ثم بيان ذلك بالكتابات، وفي الصحف، وفي المجلات حتى يبين الباطل، وحتى يوضح الحق.","link":"https://binbaz.org.sa/fatwas/1760/خرافات-وشركيات-صوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_599.mp3","categories":["الفرق والمذاهب"]},{"id":6579,"question":"ما عليه الرافضة هل يخرجهم من الملة؟","title":"حكم تكفير الرافضة","answer":"الجواب: أكثرهم يخرجون من الملة، أكثرهم يعبدون عليًّا، ويستغيثون به، ويدعونه من دون الله، هذا كفر أكبر، والذين يبغضون المسلمين، ويقولون: الصحابة ارتدوا كلهم إلا ثلاثة، أو اثنين، كبلال، هؤلاء كفار كالإمامية، وأشباههم، والنصيرية وأشباههم، أما جنس الزيدية لا، لأن الزيدية أخف المفضلة، والذين يفضلون عليّا على عثمان ما يكونون كفارا، يكون غلط، هذا غلط منهم، والذين يفضلون عليّا على أبي بكر، وعمر ولكن لا يسبونهما هؤلاء ليسوا بخارجين من الملة، فالشيعة أقسام كثيرة. قال بعضهم: إنهم اثنان وعشرون قسمًا، بعضهم يكفر بعمله، كالذي يعبدون أهل البيت، ويستغيثون بهم، وينذرون، أو يسبون الصحابة، أو يكفرونهم، أو يقولون: إن جبريل خان، وإن الرسالة لعلي دون محمد، هؤلاء كلهم كفرة نعوذ بالله. أما الأنواع الآخرون من الشيعة فهم دون ذلك، ليسوا كذلك، مسلمون لكن ناقصون، مسلمون لكن عندهم بعض البدع.","link":"https://binbaz.org.sa/fatwas/2392/حكم-تكفير-الرافضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_923.mp3","categories":["الفرق والمذاهب"]},{"id":6737,"question":"لقد سمعت في الآونة الأخيرة: أن هناك مذهب خامس يسمى المذهب الصوفي، وتوجد كتب تأليف محمد علوي مالكي عن هذا المذهب الصوفي، ما رأي فضيلتكم بهذا المذهب؟ وهل تنصحون بقراءة هذه الكتب؟ جزاكم الله ألف خير.","title":"حقيقة الصوفية وأخطاء محمد علوي المالكي","answer":"الجواب: لا، الصوفية ما هي مذهب واحد، مذاهب كثيرة، مذاهب كثيرة، والذي فعله محمد مالكي هذا ما هو يتعلق بالصوفية فقط، يتعلق بالصوفية، وغيرها، له أخطاء كبيرة، منها شيء يتعلق بالصوفية، وفي أي مذهب للصوفية، في بعض المسائل، ومنها شيء يتعلق بالشرك الأكبر، وقع فيه في بعض الكتب .. تبيح الشرك الأكبر -والعياذ بالله- وعبادة غير الله، ودعوة غير الله -نسأل الله العافية- فله أخطاء كبيرة، في بعضها بدع، وفي بعضها قريب لبعض لمذاهب الصوفية، وبعضها شرك أكبر، يرون الاستغاثة بالنبي ﷺ والاستجارة بالنبي ﷺ ودعوته، وهذا شرك أكبر، نعوذ بالله، نسأل الله أن يرده للصواب، والهداية.","link":"https://binbaz.org.sa/fatwas/2602/حقيقة-الصوفية-واخطاء-محمد-علوي-المالكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1098.mp3","categories":["الفرق والمذاهب"]},{"id":6769,"question":"أفتونا مأجورين عن الماسونية جزاكم الله خيرًا؟ وما حكم من انتمى إلى هذه الجماعة؟","title":"حقيقة الماسونية","answer":"الجواب: الماسونية معروفة عند الناس، وهي جماعة سرية، يتظاهرون بالمواساة وكرم الأخلاق، وأن الإسلام جاء بالمعتاد، والإحسان إلى الفقير، والمسكين، وهم في الباطن يدعون إلى نبذ الأديان، ونبذ الأوامر، والنواهي، وأن الناس يبقون على حالهم الأولى، لا إله، ولا رب، ولا نبي، ولا شريعة، ولا شيء، يعني في الباطن هم يحاربون الشرائع، والأوامر، والنواهي، ويبقى الإنسان أخو الإنسان بأنه ابن آدم وبس، مثل البهيمة يأكل، ويشرب معه، ويتعاون معه في هواه بلا شريعة، ولا أوامر، ولا نواهي، هذا في السر، وأما في الظاهر فهم يدعون إلى الأخوة، والتعاون فقط.  السؤال: أين يقيمون ؟ الجواب: في كل مكان لهم أوكار كثيرة. السؤال: ...  الجواب: ... في مصر، وفي الأردن، وفي كل مكان. الطالب: ثلاثة أرباع رؤساء دول العالم .. الجواب: يمكن عندنا .. ونحن ما نعرفهم.","link":"https://binbaz.org.sa/fatwas/2646/حقيقة-الماسونية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1142.mp3","categories":["الفرق والمذاهب"]},{"id":6808,"question":"من التحديات في العصر الحديث: وجود الباطنية، والصوفية المعادية للعقيدة السلفية الصافية، وإظهارهم النفاق مع أصحاب العقيدة الصحيحة، وإضمارهم الحقد، والعمل على نشر باطلهم، نرجو إيضاح ذلك؟","title":"التحذير من الصوفية وما هم عليه من الباطل","answer":"الجواب: هذا من عمل المنافقين، وجود الصوفية، وغير الصوفية ممن يتظاهر بالإسلام، وهو ليس على الإسلام، ولكنه يكيد للإسلام، فهذا من جنس عمل المنافقين في عهد النبي ﷺ كعبدالله بن أبيـ وأصحابه، فهم يتظاهرون بالإسلام للكيد للإسلام، وانتقاما من الإسلام، أو ... على أموالهم، ونفوسهم، ودمائهم؛ حتى يجدوا الفرصة، فإن وجدوا الفرصة؛ أظهروا باطلهم، وشرهم، وعداءهم للإسلام.  فالتصوف له طرق محدثة جديدة، ما أنزل الله بها من سلطان، والصوفية أنواع، وطرائق مختلفة، وصنوف في اتباعهم، وسلوكهم .... لا ما جاء به الرسول ﷺ بل على ما يوضح لهم الشيخ، ويدعوهم له الشيخ، ويبايعهم عليه، أنهم يأخذون بقوله، ويتبعونه بعمله، وأنهم يكونون معه كالميت مع الغاسل، لا يخالفونه، ولا يشذون عن قوله، بل ينفذون ما قال كما ينفذ الغاسل أعماله مع الميت، ليس للميت حراك، ولا تصرف، ولهم أعمال سيئة، ولهم أخبار خبيثة، وهم طبقات وأقسام. فالواجب الحذر مما يسمى بالتصوف، والصوفية، وأن يكون منهم المؤمن على بصيرة، في مصر، والشام، والعراق، وفي كل مكان، وحيث ما كانوا؛ ليحذر ما يدعون إليه، وليكن على بينة، وليعلم ما يقولون.","link":"https://binbaz.org.sa/fatwas/2683/التحذير-من-الصوفية-وما-هم-عليه-من-الباطل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1181.mp3","categories":["الفرق والمذاهب"]},{"id":6827,"question":"من التحديات في العصر الحديث: وجود الباطنية، والصوفية المعادية للعقيدة السلفية الصافية، وإظهارهم النفاق مع أصحاب العقيدة الصحيحة، وإضمارهم الحقد، والعمل على نشر باطلهم، نرجو إيضاح ذلك؟","title":"التحذير من الصوفية وما هم عليه من الباطل","answer":"الجواب: هذا من عمل المنافقين، وجود الصوفية، وغير الصوفية ممن يتظاهر بالإسلام، وهو ليس على الإسلام، ولكنه يكيد للإسلام، فهذا من جنس عمل المنافقين في عهد النبي ﷺ كعبدالله بن أبيـ وأصحابه، فهم يتظاهرون بالإسلام للكيد للإسلام، وانتقاما من الإسلام، أو ... على أموالهم، ونفوسهم، ودمائهم؛ حتى يجدوا الفرصة، فإن وجدوا الفرصة؛ أظهروا باطلهم، وشرهم، وعداءهم للإسلام.  فالتصوف له طرق محدثة جديدة، ما أنزل الله بها من سلطان، والصوفية أنواع، وطرائق مختلفة، وصنوف في اتباعهم، وسلوكهم .... لا ما جاء به الرسول ﷺ بل على ما يوضح لهم الشيخ، ويدعوهم له الشيخ، ويبايعهم عليه، أنهم يأخذون بقوله، ويتبعونه بعمله، وأنهم يكونون معه كالميت مع الغاسل، لا يخالفونه، ولا يشذون عن قوله، بل ينفذون ما قال كما ينفذ الغاسل أعماله مع الميت، ليس للميت حراك، ولا تصرف، ولهم أعمال سيئة، ولهم أخبار خبيثة، وهم طبقات وأقسام. فالواجب الحذر مما يسمى بالتصوف، والصوفية، وأن يكون منهم المؤمن على بصيرة، في مصر، والشام، والعراق، وفي كل مكان، وحيث ما كانوا؛ ليحذر ما يدعون إليه، وليكن على بينة، وليعلم ما يقولون.","link":"https://binbaz.org.sa/fatwas/2683/التحذير-من-الصوفية-وما-هم-عليه-من-الباطل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1181.mp3","categories":["الفرق والمذاهب"]},{"id":6906,"question":"نرجو من سماحتكم أن تعرف لنا فرق الأشعرية، والأباضية والظاهرية؟ وهل هذه الفرق من أهل السنة والجماعة، أم هي من الفرق الداخلة في الحديث القائل: إن بني إسرائيل قد تفرقت إلى اثنين وسبعين فرقة، وتفرقت أمتي إلى ثلاث وسبعين فرقة، كلهم في النار إلا واحدة؟","title":"حقيقة الأشاعرة والإباضية والظاهرية","answer":"الجواب:  نوصيك بلزوم طريقة السنة والجماعة، وهو طريق النبي ﷺ وطريق أصحابه، هذا طريق أهل السنة، وهو لزوم ما كان عليه النبي وأصحابه في الأقوال، والأعمال، والسيرة -عليه الصلاة والسلام- تلزم هذا، وتستقيم عليه، وهو ما جاء في الكتاب العظيم، والسنة المطهرة، وما درج عليه سلف الأمة، هذا هو الطريق السوي، طاعة الله ورسوله، والقيام بأمر الله، وترك ما نهى الله عنه، والتعاون على البر، والتقوى، والتواصي بالحق، والصبر عليه، أما هذه الفرق فهي فرق خاطئة ضالة من جهات كثيرة: فرقة الإباضية هي فرقة من الخوارج، تركوا الدعوة إلى ما عليه الخوارج، لكنهم عندهم ضلال، وعندهم أخطاء، وأغلاط. هكذا الأشاعرة عندهم أخطاء، وأغلاط، وهكذا الظاهرية، والظاهرية أحسنهم، الظاهرية فرقة طيبة، وهم دعاة للإسلام، ودعاة للأخذ بظاهر القرآن والسنة، لكن عندهم أخطاء، الظاهرية عندهم أغلاط بسبب عدم عنايتهم بالمعاني، والقياس الشرعي، فلهذا وقع لهم أخطاء، وعلى رأسهم داود الظاهري -رحمه الله- وابن حزم، فهم ليسوا من جنس الإباضية، وليسوا من جنس الخوارج، وليسوا من جنس الأشعرية في العقيدة، خصوصًا داود الظاهري، أما ابن حزم فعنده انحراف في العقيدة -نسأل الله أن يعفو عنا وعن كل مسلم-. المقصود: أن المؤمن طالب العلم يعتني بما عليه أهل السنة والجماعة، ويحرص على السلامة من العقائد الأخرى الزائغة، لا طريقة الأشاعرة، ولا طريقة الجاهلية، ولا المعتزلة، ولا الإباضية، ولا الرافضة، ولا غيرهم من الفرق التي دخلت تحت قول النبي ﷺ: وستفترق أمتي على ثلاث وسبعين فرقة، كلها في النار إلا واحدة فالخوارج، والمعتزلةن والجهمية، والرافضة، وأشباههم، كلهم داخلون تحت هذه. أما الأشاعرة فلهم أغلاط في العقيدة، في تأويل الصفات، ولهم أغلاط في غيرها، لكنهم أسهل من الخوارج، وأسهل من المعتزلة، وأسهل من الخوارج وأحسن منهم، إنما عندهم أخطاء يجب التنبيه عليها لأحيائهم، ونسأل الله أن يعفو عن أمواتهم.","link":"https://binbaz.org.sa/fatwas/2834/حقيقة-الاشاعرة-والاباضية-والظاهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1282.mp3","categories":["الفرق والمذاهب"]},{"id":6939,"question":"ما حكم الصلاة في مسجد به قبر؟ وما حكمه إذا كان القبر خلف المسجد؟ كما نسألكم عن حكم إهداء الحلوى بمناسبة مولد الرسول ﷺ؟","title":"ما حكم الصلاة في مسجد به قبر لكنه خلف المسجد؟","answer":"الجواب: الصلاة في المساجد التي فيها قبور ما تجوز، الرسول ﷺ قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد قالت عائشة -رضي الله عنها-: يحذر ما صنعوا، قالت: ولولا ذلك؛ لأبرز قبره، يعني في البقيع، غير أنه خشي أن يتخذ مسجدًا.  وقال -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم، وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك أخرجه مسلم في الصحيحين عن جندب بن عبدالله البجلي. الرسول ﷺ حذر من هذا، وبين أن من قبلنا فعلوا هذا المنكر اتخذوا قبور أنبيائهم، وصالحيهم مساجد ثم نهانها، وحذرنا عن ذلك.  فالصلاة في المساجد التي بنيت على القبور لا تصح، سواء كان القبر في مقدمها، أو عن يمينه، أو شماله، أو خلفه، أما إذا كان خارج المسجد، والمسجد خارج عنه؛ تصح الصلاة. أما ما دام المسجد بني على القبر، سواء جعل أمام المصلين، أو عن يمينهم، أو عن شمالهم، أو خلفهم، فلا يصلى فيه، وإذا كان القبر هو الجديد؛ ينبش، ويخرج رفات القبر إلى المقبرة العامة، ويسوى أرضه، أما إذا كان المسجد هو الجديد، بني على القبر؛ يهدم، ويزال، وتبقى القبور ضاحية للشمس، كما هي ضاحية في عهد النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/2869/ما-حكم-الصلاة-في-مسجد-به-قبر-لكنه-خلف-المسجد ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1317.mp3","categories":["البدع والمحدثات","الفرق والمذاهب","المساجد ومواضع السجود"]},{"id":7035,"question":"ما الفرق والاختلاف بين فرقة المعتزلة، وأهل السنة، وهل من المعتزلة أناس مثلما كان عليه الرسول ﷺ؟","title":"مظاهر الاختلاف بين أهل السنة والمعتزلة","answer":"الجواب:\n\nالمعتزلة طائفة مبتدعة منحرفة، نفت صفات الله، قالوا: ليس بعليم، ولا حكيم، ولا سميع، ولا بصير، نعوذ بالله، نفوا صفات الله  وقالوا: من مات على المعصية؛ فهو مخلد في النار، الزاني قالوا: مخلد في النار، وشارب الخمر قالوا: مخلد في النار، وهكذا من جنس بقية المجرمين، الخوارج وأشباههم. \n\nفالحاصل: المعتزلة طائفة مبتدعة، لها ضلالات كثيرة، أعظمها وأشنعها أنهم يقولون: ليس لله صفات، فليس بعليم، ولا سميع، ولا بصير، ولا حي، ولا قيوم، ولا غير ذلك، هذا كفر وضلال -نعوذ بالله- ويقولون -نعوذ بالله أيضًا-: إن العاصي، مخلد في النار.\n\nأما أهل السنة يقولون: لا، العاصي ما هو مخلد في النار، إذا كان موحدًا مسلمًا تحت مشيئة الله، إذا مات على المعصية، تحت مشيئة الله؛ لأن الله قال سبحانه: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ [النساء:48] ثم قال بعدها: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] يعني ما دون الشرك تحت مشيئة الله، إن شاء الله عفا عنه إذا مات عليه من أجل إسلامه وصلاته وصومه، وإن شاء الله عذبه على قدر ما عنده من زنا وغيره من معاصٍ، من بعد ما يطهر ويمحص؛ يخرجه الله من النار إلى الجنة، هذا قول أهل السنة والجماعة من أصحاب النبي ﷺ وأتباعهم بإحسان، أما المعتزلة؛ فعلى خلاف ذلك -نسأل الله العافية- وهكذا الخوارج على خلاف ذلك.","link":"https://binbaz.org.sa/fatwas/3014/مظاهر-الاختلاف-بين-اهل-السنة-والمعتزلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1421.mp3","categories":["الفرق والمذاهب"]},{"id":7038,"question":"ما رد سماحتكم على جماعة التكفير والهجرة التي تسمي نفسها بجماعة المسلمين، وهم يعتبرون كل ما سواهم كافر، ويكفرون بالمعصية؟","title":"الرد على جماعة التكفير والهجرة","answer":"الجواب:\n\nهذه جماعة نسمع عنها، جماعة التكفير والهجرة نسمع عنها، ويقولون عنها كذا، والله أعلم بحقيقتها، ليس عندنا بصيرة بأحوالهم، والناس قد يكذبون عليهم، وقد يزيدون عليهم، وقد ينقصون عليهم، لكن توزن أقوالهم، وتوزن أعمالهم بالكتاب والسنة، وينظر فيما يقولون، فإن كانوا على طريقة الخوارج، وطريقة المعتزلة، قد غلطوا وضلوا عن السبيل، فيعلمون ويوجهون إلى الخير، وإن كان مكذوبًا عليهم؛ وجب التصحيح.\n\nفإذا كانوا يقولون مثل قول المعتزلة: أن من زنا فهو كافر، أو من شرب الخمر فهو كافر، أو من عق والديه فهو كافر، هؤلاء يقال لهم: معتزلة، أو خوارج، إذا كفروا؛ صاروا خوارج، ووجب أن يستتابوا، فإن تابوا وإلا يقتلون، كما أمر النبي بقتل الخوارج -عليه الصلاة والسلام- قال: أينما لقيتموهم فاقتلوهم.\n\nأما إذا كان يكذب عليهم، وينقل عنهم خلاف الحقيقة؛ فالواجب على المؤمن ألا يكذب، وألا يتهم الناس بغير حق، والواجب على من عرف عنهم شيئًا؛ غلطوا فيه، فينصحهم، ويوجههم إلى الخير، أما أخذ الكلام من الناس على عناته، على عواهنه من دون بصيرة، فقد يكذب الناس على بعض الناس. \n\nالسؤال: الاستقرار عندهم واللقاء بهم، قال أحدهم: لو قابلت الشافعي؛ لفقأت عينه، وقال واحد منهم ... قال: لو قابلت ابن عمر؛ لفقأت عينه ويكفرون بالمعصية؟\n\nالجواب: هؤلاء خوارج، مثل الخوارج، معروف الخوارج، يجب على الدولة أن تستتيبهم، فإن تابوا؛ وإلا قتلوا مثل ما فعل عليٌّ بالخوارج قتلهم  لما استتابهم، من تاب منهم قبله، ومن لم يتب قاتله، حتى قتلهم -رضي الله عنه وأرضاه-.\n\nالسؤال: قتلوا المسلمين... بالهداية، ودعا على كل علماء المسلمين..؟\n\nالجواب: أقول يا شيخ محمد، هذه قاعدة: من ظهر منه دين الخوارج، وطريقة الخوارج؛ وجب أن يستتاب من ولي الأمر في بلده، فإن تابوا وإلا قتلوا، وإن أصروا على ما هم عليه؛ قتلوا، وإذا ظهر منهم طريقة المعتزلة؛ كذلك يستتابون، فإن تابوا؛ وإلا فلولي الأمر قتلهم، ولولي الأمر سجنهم، وهكذا أهل البدع على اختلافهم، يعني ينظر في أمرهم بطريقة الكتاب والسنة.","link":"https://binbaz.org.sa/fatwas/3015/الرد-على-جماعة-التكفير-والهجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1422.mp3","categories":["الفرق والمذاهب"]},{"id":7094,"question":"ما تقولون في رجل قال: ليس هناك فرق بين سني وشيعي، بل كلهم مسلمون، وهو مفت في إحدى ديار المسلمين، حيث أنه أجريت معه مقابلة في إحدى المجلات منذ شهر، ويقول: حرام علينا أن نقول: هذا سني، وهذا شيعي، فهل هذا الكلام لا بأس به، أو ما ترون فيه؟","title":"أصناف الشيعة والحكم عليهم","answer":"الجواب:\n\nهذا الكلام فيه إجمال خطأ، فإن الشيعة أقسام، وليسوا قسمًا واحدًا، الشيعة أقسام، ذكر الشهرستاني أنهم اثنتان وعشرون فرقة، وهم يختلفون فيهم من بدعته تكفره، وفيهم من بدعته لا تكفره، مع أنهم في الجملة مبتدعون، الشيعة في الجملة مبتدعون، وأدناهم من فضل عليًّا على الصديق وعمر قد أخطأ وخالف الصحابة.\n\nولكن أخطرهم الرافضة أصحاب الخميني، هؤلاء أخطرهم، وهكذا النصيرية أصحاب حافظ الأسد وجماعته في سوريا، فالباطنية الذين في سوريا، والباطنية الذين في إيران، والباطنية في الهند وهم الإسماعيلية هذه الطواف الثلاثة هم أشدهم وأخطرهم، وهم كفرة، هؤلاء كفرة؛ لأنهم -والعياذ بالله- يضمرون الشر للمسلمين، ويرون المسلمين أخطر عليهم من الكفرة، ويبغضون المسلمين أكثر من بغضهم الكفرة، ويرون أهل السنة حل لهم دماءهم وأموالهم، وإن جاملوا في بعض المواضع التي يجاملون فيها، ويرون أن أئمتهم يعلمون الغيب، وأنهم معصومون، ويعبدون من دون الله بالاستغاثة، والذبح لهم، والنذر لهم، هذه حالهم مع أئمتهم.\n\nفالرافضة الذين هم الطائفة الاثنا عشرية، ويقال لهم: الجعفرية، ويقال لهم الآن: الخمينية الذين يدعون إلى الباطل، وهم من شر الطوائف، وهكذا طائفة النصيرية من شر الطوائف، وهكذا طائفة الإسماعيلية، هؤلاء باطنية .. يرون إمامة الصديق وعمر وعثمان، يرونها باطلة، ويرون الصحابة كفارًا ارتدوا عن الإسلام إلا نفرًا قليلًا منهم كعلي والحسن والحسين وعمار بن ياسر، واثنين أو ثلاثة أو أربعة من بقية الذين يرون أنهم يوالون عليًّا فقط، وأما بقية الصحابة فعندهم أنهم مرتدون، قد خرجوا عن الإسلام، وظلموا عليًّا إلى غير هذا مما يقولون، -نسأل الله العافية-.\n\nمع ما عندهم من غلو في أهل البيت، ودعواهم أنهم يعلمون الغيب، وأن الواجب إمامتهم، وأن هذه الإمامات التي بعد علي وقبل علي كلها باطلة، وأن ما عندهم ولاية حق إلا ولاية علي والحسين فقط، أما الولايات التي من عهد النبي ﷺ إلى يومنا كلها باطلة عند الرافضة -نسأل الله السلامة-.\n\nالمقصود: أن الشيعة أقسام، ليسوا قسمًا واحدًا، ومنهم الزيدية المعروفون في اليمن، هؤلاء عندهم التفضيل ليسوا بكفار إلا من عبد الأوثان منهم وغلا في أهل البيت، ودعاهم من دون الله، أما مجرد تفضيل عليّ على الصديق وعلى عمر لا يكون كفرًا، ولكنه بدعة وغلط، الواجب تفضيل الصديق، ثم عمر، ثم عثمان على علي، علي هو الرابع -رضي الله عنه وأرضاه- هذا هو الحق الذي أجمع عليه الصحابة -رضي الله عنهم وأرضاهم-. \n\nفالذي يفضل عليًّا عليهم يكون أخطأ، ولا يكون كافرًا، وإنما الكفار منهم الرافضة والنصيرية والإسماعيلية الذين يغلون في أهل البيت، ويعبدونهم من دون الله، ويرون أن عبادتهم جائزة، وأن أئمتهم يعلمون الغيب إلى غير هذا مما يقولون -نسأل الله السلامة-.\n\nفالحاصل: أنهم ينظر في عقائدهم بالتفصيل، ولا يقال الشيعة كلهم كفار، لا، بل فيهم تفصيل، وهم أقسام كثيرة.\n\nالسؤال: وحجهم إلى بيت الله الحرام كيف يتم بناء على هذه العقيدة؟\n\nالجواب: لا بد ينظر في أمرهم في المستقبل، وأن يوفق الدولة لكل خير ويعينهم.\n\nالسؤال: لماذا يغضبون من تسمية أبي بكر وعثمان وعائشة وحفصة وأم حبيبة..؟\n\nالجواب: معروف، يعني يرون الصديق كافراً، ويرون عمر كافرًا، ويرون عثمان كافرًا، يرون أنهم ظلموا عليًّا، ويتهمون عائشة إلى غير هذا من عقائدهم الباطلة -نسأل الله العافية-. \n\nالمقصود: قول من قال: إنه لا فرق بين الشيعة وبين السنة، هذا قول باطل خطأ، الشيعة فيهم تفصيل، ولا يجوز أن يقال: إنهم كالمسلمين، وأنهم سواء، هذا غلط، بل فيهم تفصيل، وهكذا الصوفية أقسام، فيهم تفصيل ما هم على حد سواء.","link":"https://binbaz.org.sa/fatwas/3129/اصناف-الشيعة-والحكم-عليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1488.mp3","categories":["الفرق والمذاهب"]},{"id":7143,"question":"لقد علمنا أن أمة المسلمين ستفترق من حديث رسول الله كما افترقت اليهود على إحدى وسبعين فرقة، والنصارى اثنين وسبعين فرقة، وستفترق أمتي على ثلاث وسبعين فرقة، كلهم في النار إلى آخر الحديث، فما نوع الفرق التي تسمي نفسها بالتيجانية، والشاذلية، والرفاعية إلى آخره؟ هل تعتبر هذه من ضمن الفرق المنصوص عليها في الحديث؟","title":"مفهوم حديث الافتراق","answer":"الجواب:\n\nالنبي ﷺ لم يبين الفرق، لكن يجمعها أنها على خلاف طريقه ﷺ وما شرع، ثنتان وسبعون على خلاف طريقه -عليه الصلاة والسلام- فيدخل فيها كل الفرق من تيجانية، ومن قادرية، ومن شاذلية، ومن معتزلة، وجهمية، ورافضة، وغيرهم، كل من خالف سبيله -عليه الصلاة والسلام- وسلك غير طريقه؛ دخل في هذه الفرق. \n\nوهذه الفرق ليس كلها كافرة هي متوعدة بالنار كلها، لكن فيها الكافر، وفيها غير الكافر، فيها من بدعته تجعله كافرًا، وفيها من بدعته لا ترقيه، ولا توصله إلى أنه كافر، لكن يكون عاصيًا قد أثم في عمله.\n\nالسؤال: الصوفية؟\n\nالجواب: الصوفية أنواع مثل ما تقدم.","link":"https://binbaz.org.sa/fatwas/3162/مفهوم-حديث-الافتراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1520.mp3","categories":["مسائل متفرقة في العقيدة","شروح الحديث","الفرق والمذاهب"]},{"id":7193,"question":"نرجو من سماحتكم توضيح معنى الصوفية، وإذا كان الصوفيون مخالفين لكتاب الله وسنة رسوله ﷺ فلماذا لا يسمون بالعصاة، أو المخالفين لشرع الله، فذلك أوضح لمن لم يعرف معنى الصوفية؟ وما هي العلاقة بين توحيد الألوهية والصوفية، وهل بينهما علاقة عبودية، أم شركية؟","title":"حقيقة منهج الصوفية","answer":"الجواب:\n\nالتصوف وأهل التصوف أنواع كثيرة، ولهم طرق كثيرة، واختلف في أسباب تسميتهم الصوفية، فقال الكثير من أهل العلم: إنهم سموا بهذا؛ لأنهم اعتادوا لبس الصوف، والتميز بالصوف عن غيرهم؛ فقيل لهم: الصوفية. \n\nوقيل لأنهم من أهل الصفاء، لكن على غير نسبة مستقيمة في ذلك، وأنهم سموا بهذا؛ لأنهم يعتنون بصفاء القلوب، والنظر في الأعمال القلبية، والعناية بالزهد، والرغبة في الآخرة، ونحو ذلك، فقيل لهم: الصوفية؛ من أجل هذا على غير نسبة صحيحة.\n\nفالحاصل: أن الصوفية طوائف في الأغلب اعتنت بأعمال القلوب، وحركات القلوب، وتوجه القلوب والأذكار، توجه القلوب إلى الله، والعناية بالأذكار، وابتلوا بطرق أحدثوها، أحدثها لهم مشايخهم تخالف شرع الله؛ فصاروا بذلك على أقسام، وعلى فرق كثيرة، كل فرقة تدعي أن شيخها، وإمامها، وصاحب طريقها أولى من الآخر، كما بين الشاذلية والنقشبندية، والقادرية، والتيجانية والخلوتية، إلى غير هذا فرق لا تحصى، فرق كثيرة لا تحصى، وفي بعضها كفر عظيم، وشر عظيم، حتى يرى بعضهم أن الواجب اتباع هذا الشيخ، وأن من خالف هذا الشيخ؛ فهو باطل، وإن كان في القرآن والسنة، فالواجب اتباع هذا الشيخ ضل أو اهتدى، وهذا كفر، وضلال -نعوذ بالله-.\n\nوهناك من يقول منهم وهو كثير مما ينقل عنهم: أن الواجب على هذا التلميذ أمام هذا الشيخ أن يكون كالميت بين يدي الغاسل، لا يحرك ساكنًا، ولا ينكر على شيخه شيئًا، ولو رآه يفعل معاصي الله، لا ينكر؛ لأن الشيخ أعلم منه، ولا يغير شيئًا إلا بمشورة الشيخ ورأيه، كالميت بين يدي الغاسل ليس له حركة، ولا رأي، ولا إرادة، ولا شيء إلا ما قاله الشيخ، وكل هذه أمور باطلة. \n\nوأكثر ما يؤخذ على الصوفية أنهم ليسوا بمستنين بالكتاب والسنة، بل لهم طرق وعوائد وقوانين ونظم اتبعوا فيها مشايخهم، وقلدوا فيها أشياخهم، ولو خالف شرع الله، ولو كانت مخالفة للقرآن والسنة، فلهذا أنكر عليهم أئمة العلم، وشنعوا عليهم بهذه الطرق المخالفة للشرع، ولكنهم أقسام في ذلك، وأنواع منوعة، منهم من هو بعيد من شرع الله، ومنهم من هو قريب، ومنهم من هو بين ذلك. \n\nفالواجب على أهل العلم: أن يعرضوا أقوالهم، وطرائقهم، وما كانوا عليه على كتاب الله وسنة رسوله -عليه الصلاة والسلام- فما وافق ذلك؛ قُبِل؛ لأنه وافق الشرع، لا لأنه طريق فلان، أو طريق فلان، أو رأي الشيخ فلان، لا، ما وافق الشرع؛ قُبِل لأنه وافق الشرع، وما خالفه؛ رد؛ لأنه خالف الشرع. \n\nوالواجب نقض هذه الطرق، والقضاء عليها، وإلغاؤها، وأن يكون الجميع تحت شريعة الله، واتباع محمد ﷺ هو شيخهم وإمامهم، لا يكون لهم شيخ آخر سواه يحكمونه، بل هو محكم، فما وافق شرعه؛ قُبِل، وما خالفه؛ رد، لا من الصوفية، ولا من الحنفية، ولا من المالكية، ولا من الشافعية، ولا من الحنبلية ولا من الظاهرية، ولا من غير ذلك.\n\nالواجب أن يكون الجميع خلف محمد ﷺ خلف شريعته معها، متبعين لها، منقادين لها، معظمين لها، فما قاله الرسول ﷺ محمد، وثبت عنه؛ وجب اتباعه، والأخذ به، والسير عليه، وإن خالف التيجاني، وخالف النقشبندي، وخالف فلانًا وفلانًا، وما خالف شرع الله؛ وجب تركه، وإن قال به التيجاني، أو النقشبندي، أو الشاذلي، أو فلان، أو فلان، أو الشيخ عبدالقادر، أو غير ذلك.\n\nفالمحكم هو كتاب الله وسنة رسوله -عليه الصلاة والسلام- كما قال : يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59].\n\nوقال : وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10] ما قال حكمه إلى فلان أو فلان، قال حكمه إلى الله، يعني حكمه إلى شريعة الله، إلى القرآن والسنة، هذا هو الدواء، وهو العلاج للصوفية، وغيرها من الفرق كلهم، يجب عليهم أن يخضعوا لحكم الله وألا يجعلوا الشيخ فلان هو المحكم، لا عبدالقادر ولا التيجاني ولا الشاذلي ولا فلان ولا فلان ولا فلان بل المحكم هو كتاب الله العظيم وسنة رسوله الأمين عليه الصلاة والسلام.\n\nوالذي يقوم بذلك هم العلماء الناصحون المتبعون لشرع الله، لا الذين يدعون إلى أنفسهم، وإلى تعظيمهم، وإلى أن يكونوا معبودين مع الله، أو متبعين على غير شريعة الله، هؤلاء يرفضون، إنما العالم في الحقيقة هو الذي يدعو إلى الله، وإلى كتاب الله، هذا هو العالم، هو الذي يدعو إلى كتاب الله، وإلى سنة رسوله ﷺ وإذا خالف رأيه ما دل عليه الكتاب والسنة؛ رفضه، وهكذا رأي غيره، مع الكلام الطيب والأدب الصالح، مع العلماء، وعدم سوء الأدب، بل يحترم العلماء، ويعرف لهم فضلهم، وينتفع بكلامهم، وكتبهم، ولكن لا يجعلهم آلهة يعبدهم مع الله، ولا يجعلهم مشرعين يعطلون شرع الله لأجلهم، ويخالف ما قاله الرسول لأجلهم، لا، ولكن يعتبرهم علماء -إذا كانوا علماء- يعتبرهم علماء يؤخذ من قولهم ما وافق الحق، ويترك من قولهم ما خالف الحق، هكذا قال العلماء.\n\nقال مالك -رحمه الله- الإمام المشهور، إمام دار الهجرة في زمانه، في القرن الثاني: ما منا إلا رادٌّ ومردود عليه، إلا صاحب هذا القبر، يعني الرسول ﷺ.\n\nوقال الشافعي -رحمه الله-: أجمع العلماء على أن من استبانت له سنة رسول الله ﷺ لم يكن له أن يدعها لقول أحد من الناس كائنًا من كان.\n\nوهكذا قال أبو حنيفة، وهكذا قال أحمد، وهكذا قال الأوزاعي، والثوري وغيرهم من أهل العلم والإيمان، كلهم يقولون هذا الأمر، يجب طاعة الله ورسوله، وتحكيم كتاب الله وسنة رسوله -عليه الصلاة والسلام- ورد ما خالف ذلك إلى الكتاب والسنة، وعرض الآراء -عرض آراء الناس آراء العلماء- عرضها على كتاب الله وسنة رسوله -عليه الصلاة والسلام- فما وافقها؛ قُبِل، وما خالفها؛ رُدّ، مع احترام العالم المشهور، والترضي عنه، والدعاء له بالمغفرة والرحمة، لكن لا يقدم قوله ولا رأيه على ما قاله الله ورسوله.\n\nكل عالم له أخطاء يصيب ويخطئ؛ لأنه ليس كل واحد يحصي العلم، يفوته بعض العلم؛ فلهذا يخطئ في بعض المسائل التي فاته فيها العلم، فما أخطأ فيها؛ رُدَّ إلى الحق والصواب.","link":"https://binbaz.org.sa/fatwas/3237/حقيقة-منهج-الصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1579.mp3","categories":["الفرق والمذاهب"]},{"id":7305,"question":"أنا وأهلي نسكن في عمارة، ويسكن في هذه العمارة في الدور الثاني درزي من لبنان، فأمرت ابنه بالصلاة في المسجد، وذلك أكثر من مرة، ولم أجد منهم استجابة، فكلمت الأب، فقال: إننا دروز، ونحن نؤمن بالله وملائكته وكتبه ورسله، ونشهد أن محمدًا خاتم الأنبياء، وعدد علي جميع فرائض الإسلام، ويقول: أحيانًا أصلي مع زملائي في العمل، وهم سعوديون، ولكن نحن لنا خلوة، وطال الكلام معه، والآن لا أدري ماذا أعمل، هل لنا إخراجه من العمارة؟! وإن رفض الخروج هل لنا البقاء معه في العمارة؟ علمًا أني أعلم أنهم غير مسلمين، آمل من سماحتكم توجيهي جزاكم الله خيرًا.","title":"بيان ما عليه الدورز من العقيدة.. وواجبنا نحوهم","answer":"الجواب: الدروز من أكثر الناس إخفاء لما هم عليه، وتسترًا على دينهم، وعدم إفشائه للناس، وليسوا مع المسلمين، وهم يتظاهرون بأنهم غير مسلمين، والمشهور عنهم أنهم وثنيون، وأنهم عباد للحاكم العبيدي، فليسوا مع المسلمين، وليس ظاهرهم مع المسلمين، والمعروف عن معرفهم أنهم ليسوا مسلمين، ولا يدينون بالإسلام، ولهم عبادات خارجة عما عليه المسلمون، ولهم تعلق بالحاكم العبيدي المعروف، هكذا ذكر من يعرفهم. لكن نصيحتهم مهمة، نصيحتهم، ودعوتهم إلى الله، وتوجيههم إلى الخير، وتعليمهم ما ينفعهم؛ لعل الله يهديهم مثل ما يدعى المشركون وغيرهم واليهود والنصارى، من ظاهره الشر يدعى، وهكذا من عرف بالشر، وهكذا من عرف بالعقيدة السيئة المنحرفة، ومن لم يسر مع المسلمين في أعمالهم ويصلِ معهم؛ ينصح ويوجه إلى الخير، ويعلم؛ لعل الله يهديه بأسبابك. أما كونك تنتقل عن العمارة لأجله لا، ما دام في دور وأنت في دور ما يضر، إنما النصيحة مطلوبة.","link":"https://binbaz.org.sa/fatwas/3363/بيان-ما-عليه-الدورز-من-العقيدة-وواجبنا-نحوهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1682.mp3","categories":["الفرق والمذاهب"]},{"id":8302,"question":"وهذه رسالة من المرسل علي سيد منصور جمهورية مصر العربية الوادي الجديد الداخلة، يقول في رسالته: هل يوجد أصل للطرق الصوفية في الإسلام، مثل: الطريقة الرفاعية، الخلوتية، والبيومية، والشاذلية، وماذا يجب علينا أن نفعل تجاه هذه الطرق، خاصة أن بعض الجهلاء يقولون: بأنه لا يصح التعبد إلا إذا كان للإنسان شيخ؟","title":"الطرق الصوفية في ميزان الشرع","answer":"الجواب: ليس للطرق الصوفية أصل في الشرع فيما نعلم، بل هي محدثة وبدع منكرة، وما كان فيها من ذكر شرعي أو عمل شرعي فما جاء به الكتاب والسنة يغني عنه، فالواجب على أهل الإسلام أن يتلقوا علومهم وأعمالهم عن كتاب الله، وعن سنة رسوله ﷺ لا عن الطرق الصوفية ، وما قد يوجد في بعضها من أعمال طيبة أو أقوال طيبة فإنما كانت كذلك لكونها متلقاة عن الله وعن رسوله، لا عن الشيخ فلان أو صاحب الطريقة فلان، لا، فالحق الذي في أي طريقة من طرق الصوفية إنما يقبل؛ لأنه جاء عن الله وعن رسوله لا لأنه مأخوذ عن الصوفية أو عن شيخ الصوفية فلان أو فلان.\nوالواجب على المؤمن أن يتعبد بما قاله الله ورسوله وبما شرعه الله ورسوله، ولا يتعبد بما رآه الشيخ فلان أو صاحب الطريقة فلان؛ لأن هذه الطرق محدثة، وقد قال عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد يعني: فهو مردود، وقال جل وعلا: وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ [الأنعام:153] وصراط الله هو ما جاء به نبيه عليه الصلاة والسلام من القول والعمل والعقيدة، فليس لأحد أن يحدث شيئاً ويسميه طريق الشيخ فلان أو طريق الشيخ فلان، سواء كان نقشبندياً، أو خلوتياً، أو قادرياً، أو غير ذلك، الواجب على المسلمين جميعاً ومنهم الصوفية أن يتلقوا أعمال الشريعة وعبادات الشريعة عن ربهم وعن نبيهم محمد عليه الصلاة والسلام لا عن آراء الناس.\nوقد وضح النبي ﷺ العبادات بأفعاله وأقواله، ثم بينها أصحابه رضي الله عنهم، فعلينا أن نتبع ولا نبتدع، وعلينا أن ندعو إلى كتاب الله وإلى سنة الرسول عليه الصلاة والسلام، وأن نستغني بهما عما أحدثه الناس من الصوفية وغيرهم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6128/الطرق-الصوفية-في-ميزان-الشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/20110.mp3","categories":["الفرق والمذاهب"]},{"id":8451,"question":"أيضاً نفس الإخوة سماحة الشيخ لهم رسالة أخرى حول هذا المسجد الذي يصلوا فيه وهو مسجد العجيلاب حي دار النعيم بور سودان، إخواننا يقولون: أيضاً وقف أمامهم أحد الخطباء، ونصحهم بعدم الاستماع إلى تفسير القرآن، وشرح الأحاديث النبوية، وطلب إليهم الاقتصار إلى كتب الفقه وبالأخص كتاب: الأخضري والعشماوي والعزية أو كذا لما في تلك الكتب من أحكام الطهارة والعبادات؛ ولأنها هي الأصل حسب زعمه، وما سواها فروع، وحضهم على بعض البدع مثل: اللهم صل أفضل صلاة وبالمصطفى والمرتضى أو والمرتضي وابنيهما وفاطمة وبر الصلوات المكتوبة، فهل محق هذا المرشد الديني فيما قال؟ وفي هذا المسجد تمارس كثير من البدع والتوسلات بالرسول صلى الله عليه وسلم وبعض الصالحين، ولا يقدم القائم على هذا المسجد إلا من يعتنق الطريقة الختمية ، علماً بأن اتباع هذه الطريقة وغيرها من الطرق الصوفية لا يتعلمون القرآن، ولا يحسنون حتى قراءة سورة الفاتحة، ويستمر على هذا المنوال سماحة الشيخ، ويرجو النصح والإرشاد لو تكرمتم؟","title":"التحذير من الطريقة الختمية","answer":"الجواب: لا ريب أن هذا العمل عمل منكر، ولا ينبغي اتباع الطريقة الختمية ؛ لأنه بلغنا عنها أنها تقر دعوة غير الله والشرك بالله سبحانه وتعالى.\nفالواجب اجتنابها والحذر منها ونصيحة المعتنقين لها، بأن يتقوا الله ويعبدوه وحده ويسألوه وحده سبحانه وتعالى، ولا يسألوا سواه، فالله سبحانه هو الذي يدعى ويرجى جل وعلا، وهو القائل سبحانه: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، وهو القائل : وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106].\nوالذي ينبغي للواعظ أن يذكر الناس بالقرآن، والسنة عن النبي صلى الله عليه وسلم وأن يعلمهم إياها، وأن ينصحهم، ويتعلم القرآن وتفسيره، ويتعلم السنة وشروحها المعتمدة؛ حتى يستفيد الناس من كلام ربهم وسنة نبيهم عليه الصلاة والسلام.\nأما كتب الفقه الخالية من السنة والأدلة هذا غلط؛ لأنها لا تفيدهم علم، الكتب التي ليس فيها الأدلة عن الله وعن رسوله لا تفيد الناس علماً بل هي كتب تقليد. فالعالم يعلم الناس الكتب التي تنفعهم، يعلم الناس قراءة الكتب التي فيها الفائدة، وأعظم ذلك أن يعلمهم القرآن، وأن يدعوهم إلى العناية بالقرآن الكريم حفظاً وتلاوة وتدبراً وتعقلاً وعملاً، فهو أعظم كتاب وأشرف كتاب.\nفعلى المسلمين أن يتعلقوا به ويتعلموه ويدرسوه ويتلوه حق التلاوة، ويتدبروه ويتعقلوه، كما قال الله سبحانه وتعالى: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، ويقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]، ويقول سبحانه: أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا [محمد:24]، ويقول سبحانه: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْْ تُرْحَمُونَ [الأنعام:155].\nفكتاب الله فيه الهدى والنور، جعله الله هدى للناس قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44].\nوهكذا سنة الرسول صلى الله عليه وسلم تفسر القرآن، وتبين معانيه.\nفعلى أهل العلم أن يذكروا الناس بذلك، وأن يحثوهم على التمسك بالقرآن والسنة وبيان معانيهما، والعناية بتفسير القرآن وشروح الحديث المعتمدة التي تفيد الناس وتنفعهم، كفتح الباري وشرح النووي وأشباهها من الكتب وسبل السلام، نيل الأوطار، الكتب المفيدة النافعة للناس، وما في بعضها من أخطاء فطالب العلم ينبه عليه ما في بعض الشروح وبعض التفاسير من الأخطاء، يجب على أهل العلم من أهل السنة وأهل العقائد الطيبة أن ينبهوا عليه عند تلاوة التفسير، وعند تلاوة شروح الحديث ينبهون، الواجب التنبيه على ما قد يقع من أخطاء في التفسير، أو في الأحاديث وشرحها، أو فيما يتعلق بالعقيدة والصفات، العالم ينبه عند تفسير الآية وعند ذكر الحديث الشريف أو شرحه، يبين ما قد يقع فيه الناس من الخطأ.\nأما حث الناس على الكتب الفقهية التي ليس فيها الأدلة من كتاب الله وسنة رسوله ﷺ، فهذا ليس من النصح، بل هذا في الحقيقة من الغش ليس من النصح، وعلى طالب العلم أن ينصح الناس بما ينفعهم على الطريقة التي سلكها أهل السنة والجماعة في بيان معاني كلام الله، ومعاني كلام الرسول ﷺ، والنصيحة في ذلك، ويعلمون العامة ما يحتاجون إليه في أمور دينهم. نعم.","link":"https://binbaz.org.sa/fatwas/6335/التحذير-من-الطريقة-الختمية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_121/12104.mp3","categories":["الفرق والمذاهب"]},{"id":8473,"question":"أخونا من تشاد محمد أحمد شوي -فيما يبدو- وهو مقيم في جدة، عرضنا سؤالاً له في أول الحلقة وهو يسأل الآن ويقول: عندنا أناس كثيرون متمسكون بطريقة التيجانية وأنا سمعت في برنامجكم أن الطريقة التيجانية مبتدعة لا يجوز اتباعها، لكن أهلي عندهم ورد الشيخ أحمد التيجاني وهي صلاة الفاتح، ويقولون: إن صلاة الفاتح هي الصلاة على النبي محمد صلى الله عليه وسلم، وأسأل الآن: هل صلاة الفاتح هي الصلاة على النبي ﷺ أم لا؟ أرجو توضيح ذلك حيث يقولون: إن من كان يقرأ صلاة الفاتح وتركها يعتبر كافر، ويقولون: إذا ما كنت تتحمل هذا وتركتها ما عليك شيء، وإذا تحملتها وتركتها تعتبر كافراً، وقد قلت لوالدي: إن هذا لا يجوز، فقالوا: أنت وهابي وشتموني ويستمر على هذا المنوال سماحة الشيخ ويرجو منكم التوجيه والإرشاد؟","title":"حكم اتباع الطريقة التيجانية","answer":"الجواب: الطريقة التيجانية لا شك أنها طريقة مبتدعة ولا ينبغي لأهل الإيمان أن يتبعوا الطرق المبتدعة لا التيجانية ولا غيرها، بل الواجب اتباع ما جاء به الرسول عليه الصلاة والسلام؛ لأن الله يقول: قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ[آل عمران:31]، يعني: قل يا محمد! للناس: إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ويقول سبحانه: اتَّبِعُوا مَا أُنْزِلََ إِلَيْكُمْ مِنْ رَبِّكُمْ وَلا تَتَّبِعُوا مِنْ دُونِهِ أَوْلِيَاءَ قَلِيلًا مَا تَذَكَّرُونَ [الأعراف:3] ويقول سبحانه: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْْ عَنْهُ فَانْتَهُوا [الحشر:7] ويقول : وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِه[الأنعام:153]والسبل: هي الطرق المحدثة من البدع والأهواء والشبهات والشهوات المحرمة، فالله أوجب علينا أن نتبع صراطه المستقيم وهو ما دل عليه كتابه العظيم القرآن، وما دلت عليه سنة رسول الله عليه الصلاة والسلام الصحيحة الثابتة.\nهذا هو الطريق الذي يجب اتباعه أما طريق التيجاني أو الشاذلي أو فلان أو فلان أو فلان فهذا لا يجب اتباعه ولا يجوز اتباعه إلا ما وافق شرع الله منه، ما وافق شرع الله من هذه الطرق قبل؛ لأنه موافق لشرع الله لا لأنه طريق التيجاني أو الشيخ عبد القادر أو الشاذلي أو فلان أو فلان لا، نأخذه ما في الطريقة من خير نأخذه لأنه وافق الشرع المطهر، وما في هذه الطرق من أشياء تخالف شرع الله يجب تركه.\nوصلاة الفاتح هي الصلاة على النبي ﷺ مثل ما ذكروا، لكنها صيغة لم ترد عن الشارع، حيث قالوا فيها: اللهم صل وسلم على سيدنا ونبينا محمد الفاتح لما أغلق والخاتم لما سبق، والناصر للحق بالحق، هذا لفظ اخترعوه من أنفسهم ليس له أصل في.. ومعناه صحيح، المعنى صحيح لكن الشيء الذي أرشد إليه النبي ﷺ وعلمه الأمة يكون أفضل، والنبي ﷺ لما سألوه: كيف يصلون عليه، قال: قولوا: اللهم صل على محمد وعلى آل محمد، كما صليت على إبراهيم على آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد، كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد وبصيغة أخرى قال لهم ﷺ: قولوا: اللهم صل على محمد وعلى أزواجه وذريته، كما صليت على آل إبراهيم ، وبارك على محمد وعلى أزواجه وذريته، كما باركت على آل إبراهيم إنك حميد مجيد وفي لفظ ثالث قال: قولوا: اللهم صل على محمد وعلى آل محمد كما صليت على آل إبراهيم ، وبارك علىى محمد وعلى آل محمد، كما باركت على آل إبراهيم في العالمين إنك حميد مجيد فهذه الألفاظ التي جاءت عن النبي ﷺ وما جاء في معناها هي الصلاة التي ينبغي الأخذ بها واستعمالها.\nأما صلاة الفاتح وإن صح معناها في الظاهر لكن العدول عما بينه النبي ﷺ وأرشد إليه الأمة، فيه نظر وفيه نوع من الإعراض عما أرشد إليه النبي عليه الصلاة والسلام، فكأن التيجاني أعلم بما شرع الله وأولى بما ذكر هو مما بينه الرسول ﷺوأعلمه الأمة وأرشدهم إليه.\nولا ينبغي لعاقل أن يقول هذا الكلام، ولا ينبغي لمسلم أن يقول هذا الكلام، فالرسول ﷺ أعلم بما ينفع أمته، وأعلم بما هو أقرب إلى رضا الله، وأعلم بالشرائع؛ لأنه المعلم المبلغ الذي يأتيه الوحي من السماء عليه الصلاة والسلام، فهو أعلم بما شرع الله وهو أعلم بما يرضي الله، وهو أعلم بالألفاظ المناسبة من غيره عليه الصلاة والسلام.\nثم في قوله: الفاتح لما أغلق فيه شيء من الإجمال، قد يقال: إنهم أرادوا بذلك يعني: من النبوة لما انقطعت برفع عيسى عليه الصلاة والسلام انفتحت ببعثه صلى الله عليه وسلم فيكون حقاً، وقد يكون أرادوا شيئاً ما بينوه ولا أوضحوه، فإن الفاتح لما أغلق فيه إبهام فإن كانوا أرادوا بذلك أنه فتح النبوة يعني: أن الله فتح به النبوة بعدما أغلقت برفع عيسى عليه الصلاة والسلام، وأنه ليس بعد عيسى نبي إلا محمد ﷺ، فهذا معنى صحيح، هو النبي بعد عيسى مثلما قال ﷺ: ليس بيني وبينه نبي يقول ﷺ، يقول ﷺ: أنا أولى الناس بـابن مريم لأنه ليس بيني وبينه نبي عليه الصلاة والسلام فهذا معنىً صحيح، وإن كانوا أرادوا بقولهم الفاتح لما أغلق معنىً آخر فلم يبين حتى ينظر فيه.\nأما الخاتم لما سبق فهذا صحيح هو الخاتم للنبوة، خاتم الأنبياء، كما قال جل وعلا في كتابه العظيم: مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ [الأحزاب:40].\nوهو أيضاً نصر الحق بالحق عليه الصلاة والسلام وهدى إلى الصراط المستقيم كل هذا حق.\nإنما الإجمال في قولهم: الفاتح لما أغلق، هذه فيها بعض الإجمال.\nوبكل حال: لو كانت في غاية من السلامة وليس فيها شيء من الإجمال، فاستعمال اللفظ الذي جاء به النبي ﷺ وأرشد إليه ودل عليه الأمة أولى وأولى، فلا ينبغي للأمة أن يعدلوا عن شيء قاله الرسول صلى الله عليه وسلم، وأرشد إليه وهو المعصوم فيما يبلغه عن الله عز وجل، وهو أنصح الأمة وأنصح الناس وأعلم الناس بشرع الله، ما ينبغي للعاقل من المسلمين أن يعدل عما أرشد إليه النبي صلى الله عليه وسلم إلى شيء قاله غيره، سواء كان القائل أحمد التيجاني أو الشيخ عبد القادر الجيلاني أو فلان أو فلان أو حتى من الصحابة، ولو كان من الصحابة ولو كان أبو بكر الصديق ، وهو أفضل الخلق بعد الأنبياء عليهم الصلاة والسلام ، فلو قال الصديق كلمة وقال النبي ﷺ كلمة وأرشد إليها لكان قول النبي ﷺ مقدماً على أبي بكر وعلى عمر وعلى عثمان فكيف لا يقدم على من كان في القرن الثاني عشر وهو أحمد التيجاني .\nرزق الله الجميع التوفيق والهداية. نعم.","link":"https://binbaz.org.sa/fatwas/6507/حكم-اتباع-الطريقة-التيجانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_124/12407.mp3","categories":["الفرق والمذاهب"]},{"id":8486,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من السودان قرية أم دم، باعثها أحد الإخوة يقول: (س. س. س) أخونا يقول: نرجو إفادتنا عن شيخ عندنا في البلاد، له أتباع كثيرون يتفانون في خدمته وطاعته والسفر إليه، معتقدين أنه من أولياء الله فيأخذون منه الطريقة السمانية الصوفية ، وتوجد قبة كبيرة لوالده يتبرك بها هؤلاء الأتباع، ويضعون فيها ما تجود به أنفسهم من النذور ويقيمون الذكر بضرب الدفوف والطبول والأشعار، وفي هذا العام أمرهم شيخهم بزيارة قبر شيخ آخر، فسافروا رجالاً ونساء في مائة سيارة كيف توجهونهم؟","title":"بطلان ما تفعله السمانية الصوفية","answer":"الجواب: هذا منكر عظيم وشر كبير فإن السفر إلى زيارة القبور منكر، يقول النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام ومسجدي هذا والمسجد الأقصى فالرحال لا تشد لزيارة القبور وإنما تشد للمساجد الثلاثة لقصد القربة والطاعة.\nثم التقرب لأصحاب القبور بالنذور أو بالذبائح أو بالصلوات أو بالدعاء والاستغاثة كله شرك بالله ، فلا يجوز للمسلم أن يدعو صاحب القبر ولو كان عظيماً كالرسل عليهم الصلوات والسلام، ولا يجوز أن يستغيث به كما لا يجوز أن يستغيث بالأصنام ولا بالأشجار ولا بالكواكب فهكذا أصحاب القبور ليس لأحد أن يستغيث بهم، أو ينذر لهم أو يتقرب إليهم بالذبائح أو النذور كل هذا من المحرمات الشركية.\nكذلك لعبهم بالدفوف وتقربهم بالدفوف التي يفعلها كثير من الصوفية كل هذا بدعة ومنكر وليس فيه عبادة الله التقرب بالدفوف لا في القبور ولا في المساجد ولا في غير ذلك، وإنما يشرع الدف للنساء في العرس إظهاراً للنكاح أنه نكاح وليس بسفاح.\nكذلك البناء على القبور منكر، النبي ﷺ نهى عن تجصيص القبور والبناء عليها والقعود عليها، كما رواه مسلم في الصحيح عن جابر  قال: نهى رسول الله ﷺ أن يجصص القبر وأن يقعد عليه وأن يبنى عليه وقال عليه الصلاة والسلام: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد.\nفلا يجوز البناء على القبور لا مساجد ولا غيرها، يجب أن تكون ضاحية مكشوفة ليس عليها بناء ولا يجوز التبرك بها بالقبور وأهلها والتمسح بهم، كما لا يجوز دعاؤهم والاستغاثة بهم والنذر لهم والذبح لهم كل هذا من عمل الجاهلية.\nفالواجب على أهل الإسلام الحذر من ذلك، والواجب على أهل العلم أن ينصحوا هذا الشيخ، وأن يعلموه أنه في عمل باطل وأنه منكر وأن حثه للناس وترغيبه للناس في دعوة الأموات والاستغاثة بالأموات أن هذا هو الشرك الأكبر نعوذ بالله.\nويجب على المسلمين أن لا يقلدوه وأن لا يتبعوه وأن لا يغتروا به، فالعبادة حق الله وحده هو الذي يدعى ويرجى، كما قال سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُُ الْكَافِرُونَ[المؤمنون:117] سماهم كفرة بدعوتهم غير الله، من الجن والملائكة والأنبياء وأصحاب القبور أو الكواكب أو الأصنام كل هذه دعوتها مع الله شرك أكبر.\nهكذا يقول سبحانه وتعالى: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين.\nوعلى جميع من يستطيع إنكار هذا المنكر أن يساهم في ذلك، وعلى الدولة إذا كانت مسلمة أن تمنع ذلك، وأن تعلم الناس ما شرع الله لهم وما أوجب عليهم من أمر الدين، حتى يزول هذا المنكر وحتى يزول هذا الشرك، نسأل الله الهداية للجميع.","link":"https://binbaz.org.sa/fatwas/6545/بطلان-ما-تفعله-السمانية-الصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12513.mp3","categories":["الفرق والمذاهب"]},{"id":8506,"question":"من جمهورية اليمن الديمقراطية الشعبية حضرموت منطقة ترس رسالة بعث بها أخونا سعيد خميس الصويل ضمنها خمسة أسئلة.في سؤاله الأول يقول: يوجد عندنا الكثير من علماء الدين -كما يصفهم- يقومون بدق الطبول داخل المساجد مع استعمال المدروف الناي، وهو نوع من الموسيقى، وينشدون معه الأناشيد المعبرة عن أشخاص مقبورين، يسألونهم ويطلبون منهم العون، فبماذا ترشدون هؤلاء أبقاكم الله؟","title":"ضلالات الصوفية وبدعهم","answer":"الجواب: هؤلاء يسمون الصوفية، والتصوف الذي أحدثه هؤلاء بدعة في الدين، وكان أصل ذلك أنه وجد في المسلمين زهاد وأهل ورع وزهد يتعبدون ويحرصون على العبادات والقراءة والذكر في المساجد والبيوت حرصاً منهم على الخير، ثم تطورت الأحوال حتى حدث هؤلاء الذين أحدثوا بدعاً ومنكرات في الدين، منها هؤلاء الذين ذكرهم السائل، الذين يتعبدون بالطبول والدفوف والأناشيد والأغاني وآلات اللهو، هذا منكر من القول وبدعة.\nوقد أنكر ذلك العلماء، وأطال في ذلك العلامة ابن القيم رحمه الله وغيره من أهل العلم في كتابه إغاثة اللهفان، وأطال غيره فيها من أهل العلم وبينوا بطلان ذلك وأن هذا منكر عظيم يجب تركه، ولا يجب أن يسمى هؤلاء علماء ليسوا بعلماء هؤلاء، بل هؤلاء جهال في الحقيقة، وليسوا بعلماء بل أضلوا الناس ولبسوا على الناس، فلا يجوز اتباعهم في هذا الأمر، ولا تقليدهم في هذا الأمر بل يجب أن ينصحوا وأن يوجهوا إلى الخير، وأن يحذروا من هذه البدعة المنكرة.\nوأشنع من هذا وأكبر دعاؤهم الأموات والاستغاثة بالأموات، هذا شرك أكبر، هذا شرك الجاهلية شرك أبي جهل وأشباهه، دعاء الأموات كـالعيدروس أو الشيخ عبد القادر الجيلاني أو البدوي أو الحسين أو غيرهم من الناس هذا شرك أكبر، هذا مثل فعل المشركين الأولين مع اللات ومع العزى، ومثل فعل النصارى مع عيسى وغيرهم فهذا شرك أكبر.\nفإذا قال: يا سيدي فلان! اشف مريضي، أو رد علي غائبي، أو اقض حاجتي، أو أنا في حسبك، أو المدد المدد يا سيدي! سواء كان هذا مع النبي عليه الصلاة والسلام أو مع الحسين بن علي بن أبي طالب رضي الله عنه، أو مع الشيخ عبد القادر الجيلاني، أو مع العيدروس أو مع البدوي، أو مع الست نفيسة أو الست زينب أو غيرهم ممن اشتهروا في مصر وغيرها، وفي الجنوب العيدروس وناسا آخرين، وفي العراق الجيلاني وأناساً آخرين.\nكل هذا من الشر العظيم، وكل هذا مما أحدثه الجهال وأشباه الجهال، فدعوة الأموات والاستغاثة بالأموات والنذر لهم والذبح لهم هذا من الشرك الأكبر بإجماع أهل العلم، يقول الله سبحانه: قُلْ إِنَّ صَلاتِي [الأنعام:162] يعني: قل يا محمد! للناس: إِنَّ صَلاتِي وَنُسُكِي(يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ [الأنعام:162-163] فجعل الصلاة لله والذبح لله (لا شريك له) وقال سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ [الكوثر:1] فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:2] فالصلاة لله والذبح لله، فمن صلى لغير الله كفر وهكذا من ذبح لغير الله، وقال جل وعلا: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] فنهى أن يدعى مع الله أحد، وقوله: (أحداً) يعم الأنبياء والأولياء وغيرهم، نكرة في سياق النهي تعم الناس كلهم وتعم الخلائق.\nوقال : وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ[يونس:106] يعني: المشركين، وكل مخلوق دون الله لا ينفع ولا يضر هذا وصف عام جميع المخلوقات لا تنفع ولا تضر، إلا بالله هو الذي جعل فيها النفع والضر سبحانه وتعالى، فلا يجوز دعاء أي مخلوق بعد الله لا صنم ولا شجر ولا حجر ولا نبي ولا ولي ولا صاحب قبر ولا غير ذلك، وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ[المؤمنون:117] فسمى هذا كفراً، وسماهم كافرين نعوذ بالله، بدعائهم الأموات وبدعائهم الأصنام والأشجار والأحجار.\nوقال سبحانه في كتابه العظيم: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ [فاطر:13] هذا يعم الأصنام والأولياء والأنبياء وغيرهم وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ [فاطر:13] والقطمير: اللفافة التي على النواة، كلها ملك لله سبحانه وتعالى.\nإِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ ما يقدرون وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] فسمى عملهم شركاً، سمى دعاءهم إياهم شركاً، قال: وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] ثم قال سبحانه: وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:14] وهو الله سبحانه، هو الذي أخبر عن هذا وهو العالم بأحوالهم سبحانه وتعالى، فسماه بهذا شركاً، وفي آية المؤمنون سماه كفراً فقال: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ [المؤمنون:117] كل كافر ما له برهان، كل كافر ما له برهان فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117].\nوقال : وَمَنْ أَضَلُّ مِمَّنْ يَدْعُو مِنْ دُونِ اللَّهِ مَنْ لا يَسْتَجِيبُ لَهُ إِلَى يَوْمِ الْقِيَامَةِ وَهُمْ عَنْ دُعَائِهِمْ غَافِلُونَ ۝ وَإِذَا حُشِرَ النَّاسُ كَانُوا لَهُمْ أَعْدَاءً وَكَانُوا بِعِبَادَتِهِمْ كَافِرِينَ [الأحقاف:5-6] ويقول النبي ﷺ: الدعاء هو العبادة فجعل الدعاء هو العبادة نفسها، فهذا يدل على عظم شأن الدعاء، فإذا قال: يا سيدي! اشف مريضي، رد حاجتي، رد غائبي، اشفع لي، المدد المدد، أو ذبح له، فقد وقع منه أنواع من الشرك.\nوفي هذا المعنى يقول النبي ﷺ: لعن الله من ذبح لغير الله رواه الإمام مسلم في صحيحه من حديث أمير المؤمنين علي بن أبي طالب ، قال: حدثني رسول الله بأربع كلمات: لعن الله من ذبح لغير الله، لعن الله من لعن والديه، لعن الله من آوى محدثاً، لعن الله من غير منار الأرض أربع مسائل لعن أصحابها، لعنهم الله جل وعلا، وأعظمها الذبح لغير الله، يتقربون بالبقر أو بالإبل أو بالغنم، أو بالعجول أو بالدجاج إلى غير الله، من الأموات والغائبين، هذا شرك أكبر.\nوروى الإمام أحمد رحمه الله بإسناد جيد عن طارق بن شهاب ، قال: مر رجلان على قوم لهم صنم لا يجوزه أحد حتى يقرب له شيئاً، فقالوا لأحدهما: قرب، قال: ليس عندي شيئاً أقرب، قالوا: قرب ولو ذباباً، فقرب ذباباً فخلوا سبيله فدخل النار -ذباب تقرب به إلى غير الله- وقالوا للآخر: قرب، قال: ما كنت لأقرب لأحد شيئاً دون الله عز وجل، فضربوا عنقه فدخل الجنة فهذا يدل على أن التقرب لغير الله في العبادات من ذبح أو دعاء أو استغاثة أو نذر أو نحو ذلك شرك أكبر بالله سبحانه وتعالى، حتى ولو كان المقرب حقيراً كعصفور أو حمامة أو ذباب أو ما أشبه ذلك، كيف بالذي يقرب الإبل والبقر والغنم والعجول يكون شركه أكبر نعوذ بالله وأشد.\nفالحاصل: أن هذا العمل من هؤلاء من دعائهم الأموات والاستغاثة بالأموات شرك أكبر، وضربهم بالدفوف وقيامهم بالأغاني والناي وأنواع الملاهي هذا من المنكرات وتعبدهم بهذا من البدع، ومن تعبد بهذا من البدع التي أحدثها الصوفية، والصوفية شرهم عظيم نسأل الله أن يهديهم، قد أحدثوا بدعاً كثيرة فنسأل الله أن يهديهم وأن يردهم إلى الصواب.\nالواجب عليهم وعلى غيرهم الرجوع إلى كتاب الله وإلى سنة رسوله ﷺ، وأن يسيروا على ما كان عليه النبي وأصحابه هذا هو الهدى، هذا هو الصراط المستقيم ما سار عليه النبي ﷺ وأصحابه هو الصراط المستقيم، لا يجوز لأهل التصوف ولا غيرهم أن يتركوا طريق النبي ﷺ وأن يحدثوا طريقاً آخر، لا، الباب موقوف باب العبادة توقيفي، ليس لأحد أن يحدث شيئاً في دين الله عز وجل؛ ولهذا يقول الله سبحانه: وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ [الأنعام:153].\nروى الإمام أحمد وغيره ومحمد بن نصر المروزي في كتاب السنة وجماعة آخرون بإسناد صحيح عن عبد الله بن مسعود  قال: خط الرسول ﷺ خطاً مستقيماً فقال: هذا سبيل الله، ثم خط خطوطاً عن يمينه وعن شماله فقال: هذه السبل، وعلى كلل سبيل منها شيطان يدعو إليه هكذا هذه السبل التي أحدثها الصوفية وأشباههم كلها من الشياطين، كلها طرق دعا إليها الشيطان، فالواجب الحذر.\nوالشياطين قسمان، صنفان: شياطين الإنس وشياطين الجن، وكل من خرج عن طريق الله وتمرد على شرع الله فهو من الشياطين، فشياطين الإنس من جنس دعاة الشرك من الصوفية وغيرهم، هم شياطين الإنس، وشياطين الجن كثيرون.\nفالواجب الحذر من شياطين الإنس والجن، وكل من دعا إلى غير الله أو دعا إلى البدع فهو من شياطين الإنس، وإن كان من الجن فهو من شياطين الجن.\nفالواجب على هؤلاء الذين ذكرهم السائل في الجنوب أو في غير الجنوب في أي مكان الواجب عليهم التوبة إلى الله، والرجوع إلى الله، والاستغفار مما فعلوا، والندم على ذلك، وأن يجددوا دينهم وأن يسلكوا ما سلكه الرسول ﷺ وأصحابه، عليهم أن يسلكوا طريق رسول الله ﷺ، وطريق أصحابه الذي سار عليه التابعون لهم بإحسان من الاستقامة على دين الله، وعبادته كما شرع الله سبحانه وتعالى وترك البدع، رزق الله الجميع الهداية والتوفيق ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: جزاكم الله خيراً، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/6579/ضلالات-الصوفية-وبدعهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_127/12706.mp3","categories":["الفرق والمذاهب"]},{"id":8919,"question":"شيخ عبدالعزيز، وصل إلى البرنامج رسالة وكاتبها منفعل غاية الانفعال ويتلفظ بعبارات أسأل الله سبحانه وتعالى أن يغفر لنا وله، ملخص ما في الرسالة: الدفاع عما يسمى بالطريقة التيجانية، أرجو أن تتفضلوا بتبصير أخينا جزاكم الله خيرًا، وحبذا لو بعثتم إليه ما توصل إليه البحث العلمي حول هذه الطريقة جزاكم الله خيرًا ونفع بكم؟","title":"بيان بطلان الطريقة التيجانية","answer":"الجواب: نعم الطريقة التيجانية بدعة لا أساس لها ومنكر لا أساس له نسأل الله أن يعافي إخواننا في أفريقيا في السنغال وفي غيرها، نسأل الله أن يعافيهم من شرها وأن يخلصهم منها وأن يوفقهم لاتباع نبيهم ورسولهم محمدًا عليه الصلاة والسلام فطريقته بحمد الله كافية، وقد بعثه الله رحمةً للعالمين وأكمل له الإسلام فالواجب على جميع الأمة التمسك بما كان عليه رسول الله ﷺ وأصحابه ففيهم الأسوة والقدوة، كما قال الله  في كتابه العظيم: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِمَنْ كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الآخِرَ وَذَكَرَ اللَّهَ كَثِيرًا [الأحزاب:21]، وقال  في سورة التوبة: وَالسَّابِقُونَ الأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالأَنصَارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسَانٍ رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ وَأَعَدَّ لَهُمْ جَنَّاتٍ تَجْرِي تَحْتَهَا الأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ [التوبة:100]، فالتابعون لهم بإحسان هم السائرون على منهجه من دون زيادة ولا اختراع بدع، وقال تعالى: قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31]، فأمر الله نبيه يقول للناس هذا الكلام، (قل) يعني: قل يا أيها الرسول للناس: إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي [آل عمران:31] يعني: محمد عليه الصلاة والسلام، يُحْبِبْكُمُ اللَّهُ [آل عمران:31] فاتباع النبي ﷺ هو طريق محبة الله، وهو طريق السعادة، مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80]، وقال تعالى: وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ [النساء:13].\nفطريق الجنة والسعادة في اتباع محمد ﷺ ليس في اتباع أحمد التيجاني، أحمد التيجاني متأخر إنما ولد في ألف ومائة وخمسين من الهجرة، يعني بعد النبي ﷺ بألف عام ومائة عام وأربعين عامًا من وفاته عليه الصلاة والسلام، فهو ولد كما في كتب القوم كتب التيجانيين، ذكروا أنه ولد في عام ألف ومائة وخمسين يعني في القرن الثاني عشر من الهجرة، ويزعم أنه طاف في بلدان كثيرة وتعلم الطرق الصوفية ثم رأى النبي ﷺ عام ألف ومائة وست وتسعين فعلمه الورد الذي يعلمه الناس وأنه يعلم الأمة هذا الورد من الدعاء والاستغفار وقال: أنت ابني وعلمه الأمة، ورأى في عام ألف ومائتين بعد أربع سنين من لقاء النبي ﷺ علمه أيضًا أن يشفع إلى الدعاء والاستغفار (قل هو الله أحد) وأن يعلم الأمة ذلك، وزعم أنه رأى النبي ﷺ مشافهةً ويقظةً لا نومًا، وكل هذا باطل فإن الرسول ﷺ لا يرى يقظةً بعد وفاته عليه الصلاة والسلام وإنما يرى في المنام، فإن الله جل وعلا لا يبعثه إلا يوم القيامة، قال الله تعالى في سورة (المؤمنون): ثُمَّ إِنَّكُمْ بَعْدَ ذَلِكَ لَمَيِّتُونَ ۝ ثُمَّ إِنَّكُمْ يَوْمَ الْقِيَامَةِ تُبْعَثُونَ [المؤمنون:15-16]، فالبعث يوم القيامة، وقال عليه الصلاة والسلام: أنا أول من ينشق عنه القبر يوم القيامة فبعثه يكون يوم القيامة، فمن قال: إنه رأى النبي ﷺ يقظةً وعلمه كذا وكذا وكذا بعد وفاته فقد كذب أو كذب عليه أو رأى شيطانًا زعم له أنه النبي ﷺ، والشيطان قد يتمثل بصور كثيرة ويزعم للجاهلين أنه النبي ﷺ، أما أن يتمثل بصورته فلا؛ لأن الرسول ﷺ قال: من رآني في المنام فقد رآني فإن الشيطان لا يتمثل في صورتي، فدل على أنه قد يتمثل في غير صورته عليه الصلاة والسلام كما أخبر به العلماء ولكن التيجاني لم يرض بهذا بل قال: إنه يراه يقظةً وأنه علمه يقظةً، فهذا كله باطل سواء كان كذبه هو أو كذب عليه وغره شيطان قال له ذلك.\nثم أيضًا قد بين النبي ﷺ طريق الجنة وطريق السعادة للأمة ودرج عليه الصحابة، فهل هناك دين جديد يأتي به أحمد بعد اثني عشر قرن يخالف ما عليه الصحابة، أصحاب النبي ﷺ هم أفضل الناس وخير الناس ثم من يليهم، فالدين الذي درج عليه الصحابة هو الدين الصحيح وهو دين الله وهو الصراط المستقيم، فمن جاء بشيء بعده جديد فهو مردود عليه، يقول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد متفق على صحته، ويقول ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد، ويقول ﷺ في خطبة الجمعة: أما بعد: فإن خير الحديث كتاب الله وخير الهدي هدي محمد صلى الله عليه وسلم، وشر الأمور محدثاتها وكل بدعة ضلالة رواه مسلم في الصحيح، زاد النسائي: وكل ضلالة في النار، فلا ينبغي لعاقل أن يغضب عندما ينبه على الباطل وعندما ينبه على البدع بل ينبغي له أن يقول: الحمد لله الذي هداني، الحمد لله الذي عرفني أن هذا بدعة، الحمد لله الذي أرشدني إلى الخير، وعليه أن يتعلم ويتبصر ولا يقلد الناس، يقول النبي ﷺ في الحديث الصحيح: من يرد الله به خيرًا يفقهه في الدين رواه الشيخان: البخاري ومسلم في الصحيحين، ويقول ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة، والعالم مهما كان فضله ليس معصومًا قد يغلط كثيرًا ويلبس عليه، فإذا كان التيجاني عالمًا فالعالم ليس معصومًا، يقول مالك رحمه الله الإمام المشهور: ما منا إلا راد ومردود عليه إلا صاحب هذا القبر.\nويقول الشافعي رحمه الله: أجمع الناس على أن من استبانت له سنة رسول الله ﷺ لم يكن له أن يدعها لقول أحد من الناس بل يلزمه اتباعها.\nويقول أبو حنيفة رحمه الله: إذا جاء الحديث عن رسول الله ﷺ فعلى العين والرأس، وإذا جاء عن الصحابة فعلى العين والرأس، وإذا جاء عن التابعين فهم رجال ونحن رجال؛ لأن أبا حنيفة كان في عصر التابعين، وروي أنه رأى بعض الصحابة فيكون من التابعين إذا ثبت ذلك.\nويقول الإمام أحمد رحمه الله أيضًا: عجبت لقوم عرفوا الإسناد وصحته -يعني: عن النبي ﷺ- يذهبون إلى رأي سفيان -يعني: الثوري - والله يقول سبحانه: فََلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63] يعني: أمر النبي عليه الصلاة والسلام. فعجب من قوم يذهبون إلى قول سفيان الثوري وأشباهه من العلماء ويدعون الحديث، وهذا لا شك أنه مستنكر، فهكذا ينبغي لكل مسلم في السنغال أو في غير السنغال ولكل مكلف أن يتبصر في دينه وأن يسأل عن طريقة الرسول ﷺ وعن دين الرسول ﷺ وعما جرى عليه الصحابة ودرجوا عليه، لا عما قاله التيجاني أو الشيخ عبدالقادر أو الشاذلي أو فلان أو فلان لا، نحن مأمورون باتباع نبينا محمد عليه الصلاة والسلام.. نحن مأمورون باتباع القرآن وباتباع الرسول ﷺ، لسنا مأمورين باتباع الشيخ عبدالقادر أو الشيخ أحمد التيجاني أو الشاذلي أو فلان أو فلان أو مالك أو الشافعي أو أحمد أو أبي حنيفة أو غيرهم، هؤلاء علماء رضي الله عنهم ورحمهم، الأئمة الأربعة علماء معروفون لكن كل واحد يصيب ويخطي وهكذا غيرهم من العلماء، فإذا كان أحمد التيجاني من العلماء وكان له فضل العلم إذا قدرنا ذلك وقلنا: إنه من العلماء، فالعالم يخطي ويصيب، فقد أخطأ في هذا في زعمه أنه رأى النبي ﷺ وقد شبه عليه حين رآه يقظةً، وبزعمه أنه يعلم الأمة وأنه أرشده إلى أن يعلم الأمة جميعًا وأنه يرشدهم إلى طريقته التي جاء بها، يعني الأمة كانت ضالة حتى جاء أحمد التيجاني يعلمهم! كانت الأمة على طريق الرسول ﷺ وأصحابه هم أهل السنة والجماعة ، فمن كان على هذا الطريق فهو على طريق الرسول ﷺ وأصحابه قبل التيجاني وبعده، فأصحاب النبي ﷺ تلقوا طريقهم عن رسول الله ثم التابعون لهم بإحسان هكذا إلى وقت الأئمة الأربعة ثم بعدهم إلى وقتنا هذا، من التزم القرآن واتبع السنة وسار على نهج الصحابة فهو المتبع حقًا وهو المهدي حقًا، ومن خرج عن ذلك إلى طريقة جديدة أحدثها التيجاني أو غير التيجاني أو الشاذلي أو الشيخ عبدالقادر الجيلاني أو المرسي أو فلان أو فلان كل ذلك لا وجه له ولا يجب اتباعه بل يجب عرض كل شيء يدعيه أحد من الناس أنه من الشرع يجب عرضه على القرآن وعلى ما صح من سنة رسول الله ﷺ، فما شهد له القرآن بالصحة أو السنة الصحيحة بالصحة وجب أخذه وقبوله وإن خالف رأي شيخك أو إمامك المعين كـالتيجاني أو غيره؛ لقول الله تعالى: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59]؛ ولقوله سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10]، والتيجاني جاء في القرن الثاني عشر كما تقدم، وولد سنة ألف ومائة وخمسين فما حال الناس قبل ذلك؟ هكذا ذكر صاحب جواهر المعاني، وهكذا صاحب الرماح ذكر ذلك: أنه ولد في عام ألف ومائة وخمسين، وذكر ما قال: أنه رأى النبي ﷺ يقظةً وعلمه الورد وهو الدعاء والصلاة على النبي ﷺ يعلمه الأمة ويرشدهم، وثم علمه زيادة أن يعلمهم: (قل هو الله أحد) أيضًا ويرشدهم إلى ذلك الورد، وكل هذا معلوم عند المسلمين يعرفون أن الدعاء مشروع والاستغفار مشروع، قراءة (قل هو الله أحد) والمعوذتين مشروعة أيضًا، و: قل هو الله أحد تعدل ثلث القرآن كما جاء في الحديث ، وقد شرع الله قراءتها بعد كل صلاة وبعد المغرب والفجر ثلاث مرات مع المعوذتين، وأخبر النبي ﷺ أنها تعدل ثلث القرآن، هذا شيء معلوم قبل أن يأتي التيجاني ، فينبغي للعاقل أن ينتبه وأن لا يغتر بتقليد الناس أو بالدعايات التي لا وجه لها بل يتأمل قوله تعالى: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6]، أن تسأل ربك أن يهديك الصراط المستقيم في كل صلاة في الفاتحة، والصراط المستقيم هو دين الله ليس بدين أحمد التيجاني ، دين الله هو ما بعث الله به نبيه عليه الصلاة والسلام وما دل عليه كتاب الله وسنة رسوله وهو الصراط المستقيم، فالواجب على جميع الناس ولاسيما المسلمون في كل مكان أن يلتزموا ما جاء به الكتاب والسنة وأن يستقيموا عليه وألا يحيدوا عنه لقول التيجاني أو الشاذلي أو فلان أو فلان أو آبائهم أو أسلافهم بل عليهم اتباع الحق، رزق الله الجميع التوفيق والهداية ولا حول ولا قوة إلا بالله.\nالمقدم: جزاكم الله خيرًا، أسمعت الرد العلمي يا أخ محمد عبدالله إسماعيل الشنقيطي؟\nنسأل الله لنا ولك الهداية، أما كلامك الذي بدأت به رسالتك فلن نذكر منه شيئًا، ولكنا نسأل الله لك الهداية ولجميع المسلمين.","link":"https://binbaz.org.sa/fatwas/7076/بيان-بطلان-الطريقة-التيجانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_171/17103.mp3","categories":["الفرق والمذاهب"]},{"id":9000,"question":"السؤال الرابع والأخير يقولون فيه: هل المحل والنحل الموجودة حالياً والطرق هي التي ينطبق فيها قول الرسول ﷺ: من أتى في ديننا هذا ما ليس عليه أمرنا فهو رد والقول الآخر: ستفترق أمتي على ثلاث وسبعين فرقة كلها في النار إلا واحدة أفيدونا بالصواب جزاكم الله خيراً.","title":"حكم الطرق والنحل والعبادات المحدثة","answer":"الجواب: كل طريقة، وكل نحلة يحدثها الناس تخالف شرع الله، هي داخلة في قوله ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد وداخلة في الحديث الصحيح، قوله ﷺ: ستفترق أمتي على ثلاث وسبعين فرقة، كلها في النار إلا واحدة، قيل: من هي يا رسول الله!!؟ قال: هي الجماعة وفي رواية أخرى: ما أنا عليه وأصحابي فكل طريقة، أو عمل أو عبادة يحدثها الناس يتقربون بها إلى الله ويرونها عبادة، ويرجون فيها الثواب وهي مخالفة لشرع الله، فإنها تكون بدعة، وتكون داخلة في هذا الذم والعيب، الذي بينه الرسول ﷺ.\nفالواجب على جميع أهل الإسلام أن يزنوا ويعرضوا أقوالهم وأعمالهم وعباداتهم بما قاله الله ورسوله، بما شرعه الله، بما ثبت عن رسوله ﷺ، فما وافق شرع الله الذي جاء في كتابه، أو فيما صح عن رسول الله ﷺ، فهذا هو الحق المقبول، وما خالف كتاب الله أو خالف السنة من عبادات الناس وطرقهم فهو المردود، وكله داخل في قوله ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد و.... كل يتعلق بما يتعبد به الناس، وبما يقصد به الناس القربة. أما ما أحدثه الناس من الصنائع والاختراعات كالسلاح أو في المركوبات أو في الملابس أو في المآكل هذا ما هو بداخل في هذا، ليس له تعلق بالعبادات، وإنما الحديث يتعلق بالعبادات والطرق التي يتعبد بها الناس ويتقربون بها إلى الله، هذا هو المراد بقوله ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد، من أحدث في أمرنا هذا ما ليس منه فهو رد وهذا يدخل في ذلك العقود المخالفة لشرع الله، تدخل في هذا أيضاً، كل عقد يخالف شرع الله فإنه يرد. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7162/حكم-الطرق-والنحل-والعبادات-المحدثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_223/22305.mp3","categories":["الفرق والمذاهب"]},{"id":9271,"question":"الرسالة التالية من الجمهورية العراقية الموصل وباعثها أحد الإخوة من هناك يقول: فؤاد محمد علي الرملة ، أخونا يسأل ويقول: سؤالي عن بعض الطرق الصوفية التي تنتشر في بلادنا، ويقول العلماء: يجب على كل مسلم أن يسلك طريقة صوفية معينة وإلا فهو على ضلالة من أمره، ويقولون: من ذاق عرف، ومن لم يذق انحرف. أي: ما ذاق الإيمان عن طريق الصوفية.وكما يوجد رجل يقال له: خليفة رسول الله ﷺ -يسميه شيخ عبدالعزيز ما أدري هل من المصلحة تسميته المهم- فلان النقشبندي وطريقته تسمى: النقشبندية ومنتشرة بشكل واسع في بلادنا، ويقول العلماء: من لم يسلك هذه الطريقة فهو خاسر. وكما ينكرون أكثر أقوال علماء السلف الصالح وخاصة في العقيدة أفيدونا مأجورين جزاكم الله خير الجزاء، وآسف لطول السؤال، هذا من كلام ...","title":"الطرق الصوفية في ميزان الكتاب والسنة","answer":"الجواب: الواجب على كل مسلم أن يسلك طريق نبينا محمد عليه الصلاة والسلام الذي درج عليه أصحابه  ثم سلف الأمة من التابعين وأتباعهم من الأئمة الأربعة وغيرهم، هذا هو الواجب، أما الطرق التي أحدثها الناس ويسمونها الطرق الصوفية هذه لا يجب سلوكها، ولا يجوز سلوكها، ولا يلزم أحدًا سلوكها، لا نقشبندية ، ولا قادرية ، ولا تيجانية ، ولا خلوتية ، ولا شاذلية ، ولا غير ذلك، جميع الطرق لا يجب سلوك شيء منها؛ لأنها محدثة.\nقد سار الصحابة قبلها على ما عليه رسول الله ﷺ، قبل أن تحدث هذه الطرق وهكذا من بعدهم من أئمة السلف أفكانوا خاسرين لأنهم ما أدركوها؟!\nكانوا ناجحين وكانوا سعداء، وكانوا هم على الحق والطريق القويم، وعلى صراط الله المستقيم، فأنت -يا عبد الله- قدر نفسك معهم، كأنك موجود قبل هذه الطريقة، فهل يضرك عدم وجود هذه الطريقة؟ هذه مما أحدثها الناس، والنبي ﷺ قال: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: مردود، وقال عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد فلا يلزمك أن تسلك الطريقة النقشبندية أو التيجانية أو القادرية أو الشاذلية أو البرهانية أو غير ذلك، عليك أن تسلك طريق محمد عليه الصلاة والسلام، طريق سلف الأمة، بأن تعبد الله وحده وتستقيم على دينه، وتحافظ على الصلوات الخمس، وتؤدي الزكاة، وتصوم رمضان، وتحج البيت الحرام مع الاستطاعة، تبر والديك، تصل أرحامك، تحفظ لسانك عما حرم الله، تحفظ جوارحك عما حرم الله، تجتهد في ذكر الله وطاعته والتقرب إليه بأنواع الطاعات من صلاة النافلة، وصوم النافلة، والصدقات، والإكثار من ذكر الله والاستغفار ولا تلتفت إلى هذه الطرق التي أحدثها الناس.\nوتنصح إخوانك أن يتجنبوها، ما كان فيها من خير وافق شرع الله يؤخذ، وما كان فيها من شيء جديد يترك، يقول مالك رحمه الله ابن أنس إمام دار الهجرة في زمانه، يقول: لن يصلح آخر هذه الأمة إلا ما أصلح أولها، وهكذا قال العلماء جميعهم مثل قوله، لا صلاح لهذه الأمة إلا بما صلح به الصحابة ومن بعدهم إلا بالسير على طريق محمد عليه الصلاة والسلام، والتمسك بصراط الله المستقيم الذي قال فيه جل وعلا: وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ ذَلِكُمْ وَصَّاكُمْ بِهِ لَعَلَّكُمْ تَتَّقُونَ [الأنعام:153] وقال  في سورة الفاتحة: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ [الفاتحة:6-7] هذا هو الصراط المستقيم، هو دين الله هو الإسلام، وما جاء به الرسول ﷺ من الأعمال والأقوال هو الصراط المستقيم، وهو صراط المنعم عليهم من النبيين والصديقين والشهداء والصالحين، وهم أهل العلم والعمل الذين عرفوا دين الله وعملوا به.\nهذا هو الصراط المستقيم، أن تعرف دين الله وأن تتفقه في دين الله من القرآن والسنة وأن تعمل بذلك على النهج والطريق الذي سلكه الرسول ﷺ وسلكه أصحابه  وأتباعهم بإحسان، وإياك أن تترك ذلك من أجل قول الشيخ فلان أو الشيخ فلان أو الشيخ فلان، ويقولون: من لا شيخ له فالشيطان إمامه أو شيخه. كل هذا باطل.\nلكن أهل العلم يستعان بكلامهم ويستفاد من كلامهم في تفسير القرآن .. تفسير السنة، بيان الأحكام لكن لا تقدم آراؤهم المخالفة لشرع الله على ما قاله الله ورسوله، كتب العلماء المعروفين بالسنة والاستقامة هؤلاء يستفاد من كلامهم، وينظر في كتبهم، سواء كانت من كتب الشافعية أو الحنفية أو المالكية أو الحنبلية أو الظاهرية، أو كتب أهل الحديث المتقدمين، كل هؤلاء يستفاد من كتبهم وينظر فيها ويستعان بها على فهم كلام الله، وفهم كلام الرسول ﷺ، ويدعى لهم ويترحم عليهم لفضلهم وعلمهم، لكن لا يجوز لأحد أن يقول: الطريقة التي أحدثها فلان أو فلان هي الطريقة المنجية وما عداها فهو خطأ، لا. الواجب عليك أن تتبع طريق الرسول ﷺ؛ ولهذا قال عليه الصلاة والسلام: ستفترق أمتي على ثلاث وسبعين فرقة كلها في النار إلا واحدة وهي الجماعة التي سارت على نهج النبي ﷺ، وفي رواية الترمذي: قيل: يا رسول الله! من؟ قال: من كان على ما أنا عليه وأصحابي فالذين ينجون عند الافتراق وعند التغير هم الذين سلكوا مسلك النبي ﷺ وساروا على نهجه واتبعوا صحابته فيما كانوا عليه، هؤلاء هم الناجون، فعليك بلزوم هذا الطريق، لزوم طريق أصحاب النبي ﷺ وأتباعهم من أئمة الإسلام كـمالك والشافعي وأحمد وغيرهم من أئمة الإسلام وكن على طريقهم الطيب، وما اختلف فيه الناس أو تنازع فيه الناس من بعض المسائل فإنه يرد إلى كتاب الله وإلى سنة رسوله محمد عليه الصلاة والسلام.\nفما وافق كتاب ربنا أو سنة نبينا وجب الأخذ به والسير عليه، وفي كلام أهل العلم ما يعينك على ذلك إذا نظرت فيه وتأملته رحمة الله عليهم. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7434/الطرق-الصوفية-في-ميزان-الكتاب-والسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_183/18302.mp3","categories":["الفرق والمذاهب"]},{"id":9681,"question":"تسأل الأخت (ب. س) من الجزائر من قرية تماسين تقول: ما حكم الطرق في الإسلام، علماً أنني سألت بعض الأساتذة فقال: هي حرام، وقال البعض الآخر: ليست فرضاً ولا حراماً أرجو الإجابة الواضحة وفقكم الله؟","title":"المقصود بالطرق الصوفية وحكمها","answer":"الجواب: هذا السؤال مجمل طرق مجمل، فإن كانت السائلة تريد طرق الصوفية فهي منكرة وبدعة وبعضها كفر وبعضها بدعة وليس بكفر؛ لأن الطريق الذي يجب سلوكه هو طريق محمد ﷺ، طريق نبينا محمد ﷺ، قال الله جل وعلا: وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ [الأنعام:153] وقال : وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ [الأنعام:155] وقال جل وعلا: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] فالواجب على أهل الإسلام أن يسيروا على نهج محمد ﷺ، وأن يستقيموا على سيرته ودينه، قال تعالى: قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31].\nفصراط الله المستقيم هو ما جاء به نبينا محمد ﷺ، وهو طريق المنعم عليهم المذكورين في قوله جل وعلا: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ [الفاتحة:6-7] وهم النبيون والصديقون والشهداء والصالحون، المذكورون في قوله تعالى: وَمَنْ يُطِعِ اللَّهَ وَالرَّسُولَ فَأُوْلَئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُوْلَئِكَ رَفِيقًا [النساء:69].\nهذا هو الطريق السوي، أما طرق الصوفية ففيها الشرك كعبادة بعض شيوخهم، والاستغاثة ببعض شيوخهم، وكهجرهم ببعض علوم السنة ويقول: حدثني قلبي عن ربي، ولا يعترف بالشرع الذي جاء به محمد عليه الصلاة والسلام، إلى غير هذا من بدعهم الكثيرة، وكفعل بعضهم مع المريدين يقول: عليك أن تسلم للشيخ حاله ومراده وأن لا تعترض عليه، وأن تكون معه كالميت بين يدي الغاسل، فهذه كلها طرق فاسدة كلها ضالة.\nأما إن أراد بالطرق الطرق يعني: الخط في الأرض أراد بذلك الخطوط الأرضية الذي يخطها المشعوذون والرمالون ويدعون بها علم الغيب فهذا منكر آخر وهو لا يجوز، وهو من الشرك الأكبر إذا فعل الخطوط في الأرض، وزعم أنه يعلم الغيب بذلك، وأنه يخبر بالغيب بهذا العمل، فهذا من الشرك الأكبر ومن دعوى علم الغيب نعوذ بالله. نعم.","link":"https://binbaz.org.sa/fatwas/7869/المقصود-بالطرق-الصوفية-وحكمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_253/25308.mp3","categories":["الفرق والمذاهب"]},{"id":9778,"question":"هذه رسالة من السائلة (ص. أ. ع) من السودان من منطقة أبو كوع، تقول السائلة في رسالتها: لنا جماعة هم أصحاب الطريقة التيجانية، يجتمعون كل يوم جمعة ويوم إثنين، ويذكرون الله بهذا الذكر: لا إله إلا الله، ويقولون في النهاية: الله الله.. بصوت عالي، لا أدري ما حكم الشرع في عملهم هذا؟","title":"الطريقة التيجانية وما فيها من البدع والضلالات","answer":"الجواب: الطريقة التيجانية طريقة مبتدعة وطريقة باطلة، وفيها أنواع من الكفر لا يجوز اتباعها بل يجب تركها، وننصح المعتنقين لها أن يدعوها وأن يلتزموا بطريقة النبي ﷺ طريقة محمد ﷺ، الطريقة التي درج عليها أصحاب النبي ﷺ وتلقوها عن نبيهم محمد ﷺ وتلقاها أئمة الإسلام كـمالك والشافعي وأبي حنيفة وأحمد والأوزاعي وإسحاق بن راهويه والثوري وغيرهم من أهل العلم، وتلقوها ودرجوا عليها، ودرج عليها أهل السنة والجماعة وهي توحيد الله وعبادته وإقام الصلاة، وأداء الزكاة، وصوم رمضان، وحج البيت، وطاعة الأوامر التي جاء بها المصطفى ﷺ، وترك النواهي، هذه الطريقة التي جاء بها الرسول ﷺ.\nأما الطرق الصوفية فالواجب تركها إلا الشيء الذي وافق الشرع، إلا ما كان فيها من أشياء توافق الشرع فإنه يؤخذ بها؛ لأنها جاء بها الشرع، وأما الشيء الذي أحدثه الصوفية يترك، ومن ذلك اجتماعهم على: الله الله..! أو: هو هو..! هذا كله بدعة، لا أصل له، وإنما المشروع أن يقال: لا إله إلا الله، أو سبحان الله والحمد لله ولا إله إلا الله والله أكبر، أما تقطيعها: هو هو.. الله الله..! هذا بدعة لا أصل له. وأنصحك أيها السائلة! أن لا تحضريهم وأن لا تكوني منهم، وأن تلتزمي الطريقة المحمدية التي جاءت عن رسول الله ﷺ وهي الذكر المعروف: سبحان الله والحمد لله ولا إله إلا الله والله أكبر، في البيت في المسجد في الطريق في المطبخ في أي مكان، يذكر الله سبحانه ... على عمله يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، سبحان الله والحمد لله ولا إله إلا الله والله أكبر، ولا حول ولا قوة إلا بالله، سبحان الله وبحمده سبحان الله العظيم وهكذا، ليس لها حد محدود، بل هكذا كما جاء عن النبي ﷺ، ولا يقول: الله الله.. أو هو هو..! أو يجتمعون على رقص وضرب الطبول، كل هذا منكر. نعم.\nالمقدم: أثابكم الله.\nللأخت السائلة بقية أسئلة نعد بعرضها إن شاء الله في حلقة قادمة.","link":"https://binbaz.org.sa/fatwas/7947/الطريقة-التيجانية-وما-فيها-من-البدع-والضلالات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_258/25808.mp3","categories":["الفرق والمذاهب"]},{"id":9860,"question":"هذا سؤال من السائل من سوريا يقول: مرسله خليفة سلطان محمد، يقول: يوجد ناس عندنا يقولون: إننا أبناء الشيخ عيسى، أو أبناء شيخ غيره من الشيوخ المعروفين عندنا، ويأتونا يسألون الناس، وقد لبسوا لباسًا أخضر على رءوسهم من حرير، وفي أيديهم أسياخ من حديد، إذا أعطيتهم أعطيتهم، وإذا لم تعطهم غضبوا وضربوا أنفسهم بهذا الحديد في بطونهم وفي رءوسهم، هل هذا نوع من السحر وهل نعطيهم وهل نصدقهم، وما الحكم؟","title":"تلبيسات الصوفية ودورنا نحوهم","answer":"الجواب: هؤلاء من الطائفة التي تسمى الصوفية، وهؤلاء يلبسون على الناس ويخدعونهم بزعمهم أنهم أولاد فلان وأولاد فلان، وبزعمهم أنهم يستحقون على الناس المساعدة، فهؤلاء ينبغي منعهم من هذا العمل، وينبغي تأديبهم على هذا العمل من الدولة إذا كانت تحكم الإسلام، ولا يعطى مثل هؤلاء، وإذا ضربوا أنفسهم لعلهم يقتلون أنفسهم فلا حرج عليك في ذلك أنت، وهذا من التشويش والتلبيس الذي يفعلونه، وهم في الحقيقة يعملون هذه الأمور الشيطانية بتزوير من الشيطان وتلبيس من الشيطان، وهو يسمى: التطبير، وهو من أنواع السحر، يفعلون هذا الشيء كأنه لا يضرهم وهم لا يفعلونه في الحقيقة ولو فعلوه حقيقة لضرهم، فإن السلاح والحديد وأشباه ذلك يضر الإنسان إذا ضرب به نفسه، ولكنهم ...... على العيون بأنواع السحر، فيستحقون بهذا التأديب البليغ من ولي الأمر حتى لا يعودوا لمثل هذا العمل القبيح المنكر، ولا ينبغي لأهل الإسلام أن يساعدوا هؤلاء؛ لأن مساعدتهم معناها مساعدة على المنكر وعلى التلبيس، وعلى الشعوذة، وعلى إيذاء المسلمين وخداعهم.\nفالواجب منع هؤلاء والقضاء على منكرهم هذا، وحسم مادتهم بالأدب البليغ أو السجن حتى يرتدعوا عن هذا العمل. نعم.\nالمقدم: يعني لا يصدقون على هذا؟\nالشيخ: لا ما يصدقون، خرافات .\nالمقدم: هذا نوع من الشعوذة.\nالشيخ: هذه خرافات، شعوذة من الشياطين، ومن أنواع السحر.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8026/تلبيسات-الصوفية-ودورنا-نحوهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19813.mp3","categories":["الفرق والمذاهب"]},{"id":9878,"question":"هذه رسالة وردت من مرسلة من السودان من منطقة أبو كوع رمزت لاسمها بـ (ص. أ. ع) تقول: لنا جماعة هم أصحاب الطريقة التيجانية يجتمعون كل يوم الجمعة ويوم إثنين، ويذكرون الله بهذا الذكر: لا إله إلا الله، ويقولون في النهاية: الله الله، بصوت عالي فما حكم عملهم هذا؟","title":"التعريف بالطريقة التيجانية","answer":"الجواب: هذه العقيدة التيجانية من العقائد المبتدعة والطرق المنكرة، وفيها منكرات كثيرة، وبدع كثيرة ومحرمات شركية يجب تركها، ولا يجوز أن يؤخذ منها إلا ما وافق الشرع المطهر، الذي جاء به نبينا محمد عليه الصلاة والسلام، والاجتماع على الذكر بصوت جماعي لا أصل له في الشرع، وهكذا الاجتماع بقول: (الله، الله) أو (هو هو!) إنما الذكر الشرعي أن يقول: لا إله إلا الله، هذا هو الذكر الشرعي، أو سبحان الله، والحمد لله، والله أكبر، لا حول ولا قوة إلا بالله، أستغفر الله، اللهم اغفر لي، أما اجتماعهم بصوت واحد: لا إله إلا الله، أو الله الله، أو هو هو، هذا لا أصل له، هذا من البدع المحدثة.\nفالواجب على المسلمين ترك البدع؛ لأن الرسول عليه السلام يقول: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: فهو مردود، ويقول عليه الصلاة والسلام: من عمل عملاً ليس عليه أمرنا فهو رد ويقول أيضاً عليه الصلاة والسلام: إياكم ومحدثات الأمور، فإن كل محدثة بدعة وكل بدعة ضلالة وكان يخطب في الجمعة يقول ﷺ: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة.\nفالواجب على المسلمين أن يحذروا البدع كلها، سواء كانت تيجانية أو غيرها، وأن يلتزموا بما شرعه الله على لسان نبيه ورسوله محمد عليه الصلاة والسلام، هذا هو الواجب على المسلمين، كما قال الله : وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] وقال : يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُوْلِي الأَمْرِ مِنْكُمْ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ .. [النساء:59] الآية، وقال : وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10] وقال: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56].\nفالواجب على أهل الإسلام من الرجال والنساء طاعة الله ورسوله، والحذر من البدع في الدين، بل الله كفانا ، وأتم لنا النعمة وأكمل لنا الدين، كما قال : الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلامَ دِينًا [المائدة:3] فالإسلام الذي رضيه الله وأكمله لنا، علينا أن نلتزم به، وأن نستقيم عليه وأن نحافظ عليه، وأن لا نحدث في الدين ما لم يأذن به الله، رزق الله الجميع الهداية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8047/التعريف-بالطريقة-التيجانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26404.mp3","categories":["الفرق والمذاهب"]},{"id":9990,"question":"أخيرًا يقول هذا السائل: عندنا من مشايخ الصوفية من يهتم بصنع القباب والأضرحة، والناس يعتقدون فيهم الصلاح والبركة، فإن كان هذا الأمر غير مشروع فما هي نصيحتكم لهم وهم قدوة في نظر السواد الأعظم من الناس، أفيدونا بارك الله فيكم؟","title":"حكم الغلو في الصالحين وبناء القباب على القبور","answer":"الجواب: النصيحة لعلماء الصوفية ولغيرهم من أهل العلم أن يأخذوا بما دل عليه كتاب الله وسنة رسوله عليه الصلاة والسلام، وأن يعلموا الناس ذلك، وأن يحذروا اتباع من قبلهم فيما يخالف ذلك، فليس الدين بتقليد المشايخ ولا غيرهم، وإنما الدين ما يؤخذ عن كتاب الله وعن سنة رسول الله محمد ﷺ وعما أجمع عليه أهل العلم، وعن الصحابة ، الدين هكذا يؤخذ لا عن تقليد زيد وعمرو، وقد دلت السنة الصحيحة عن رسول الله عليه الصلاة والسلام على أنه لا يجوز البناء على القبور ولا اتخاذ المساجد عليها، ولا اتخاذ القباب ولا أي بناء، كل ذلك محرم بنص الرسول عليه الصلاة والسلام، ففي الصحيحين عن عائشة رضي الله عنها قالت: قال رسول الله ﷺ لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد قالت رضي الله عنها: يحذر ما صنعوا، وفي الصحيحين عن أم سلمة وأم حبيبة رضي الله تعالى عنهما أنهما ذكرتا للنبي صلى الله عليه وسلم كنيسة رأتاها بأرض الحبشة وما فيها من الصور، فقال: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجداً وصوروا فيه تلك الصور، أولئك شرار الخلق عند الله فأخبر عليه الصلاة والسلام أن الذين يتخذون المساجد على القبور هم شرار الخلق، وهكذا من يتخذ عليها الصور لأنها دعاية للشرك، اتخاذ المساجد والصور على القبور والقباب دعاية إلى الشرك؛ لأن العامة إذا رأوا هذا عظموا المدفونين واستغاثوا بهم ونذروا لهم، ودعوهم من دون الله، وطلبوا منهم المدد والعون، وهذا هو الشرك الأكبر، وفي حديث جندب بن عبد الله البجلي  فيما خرجه مسلم في الصحيح عن النبي ﷺ أنه قال: إن الله قد اتخذني خليلًا كما اتخذ إبراهيم خليلاً، ولو كنت متخذًا من أمتي خليلًا لاتخذت أبا بكر خليلاً، ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك هكذا رواه مسلم في الصحيح، فدل ذلك على فضل الصديق ، وأنه أفضل الصحابة وخيرهم، وأنه لو ساغ للنبي ﷺ أن يتخذ خليلاً لاتخذه خليلاً رضي الله عنه، ولكن الله جل وعلا منعه من ذلك حتى تتمحض محبته لربه سبحانه وتعالى فإن الخلة أعلى المحبة، وفي الحديث دلالة على تحريم البناء على القبور واتخاذ المساجد عليها وعلى ذم من فعل ذلك، من جهات ثلاث:\nالأولى: ذمه من فعل ذلك.\nالثانية: قوله: (فلا تتخذوا القبور مساجد).\nالثالثة: قوله: (فإني أنهاكم عن ذلك). فحذر من البناء على القبور من هذه الجهات الثلاث، يقول ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد يعني فلا تتبعوهم بهذا، لا تقتدوا بهم، ثم قال: (ألا فلا تتخذوا القبور مساجد)، يعني لا تأسوا بهم، (فإني أنهاكم عن ذلك) هذا شيء صريح، والعلة والحكمة في ذلك كما قال أهل العلم أنه وسيلة وذريعة إلى الشرك الأكبر، إلى عبادة أهل القبور، فصرف الدعاء والاستغاثة والنذور والذبائح لهم وطلب منهم المدد والعون كما هو واقع الآن في بلدان كثيرة، عند السائل في السودان، وفي مصر، وفي الشام، وفي العراق، وفي بلدان كثيرة، يأتي الرجل العامي الجاهل فيقف على صاحب القبر المعروف عندهم فيطلبه المدد والعون والغوث كما يقع عند قبر البدوي والحسين والست نفيسة وزينب وغير ذلك في مصر، وكما يقع عندكم في السودان عند قبور كثيرة، وكما يقع في بلدان أخرى، وكما يقع من بعض الحجاج الجهال عند قبر النبي ﷺ في المدينة، وعند قبور أهل البقيع، وعند قبر خديجة في مكة وقبور أخرى، يقع هذا من الجهال وهم يحتاجون إلى تبصير وإلى بيان وإلى عناية من أهل العلم.\nفالواجب على أهل العلم جميعًا سواء كانوا منسوبين للصوفية أو غيرهم، الواجب على العلماء جميعًا على علماء الشريعة أن يتقوا الله، وأن ينصحوا عباد الله، وأن يعلموهم دينهم، وأن يحذروهم من البناء على القبور واتخاذ المساجد عليها أو القباب أو غير ذلك من أنواع البناء وأن يحذروهم من دعاء الموتى والاستغاثة بالموتى، الدعاء عبادة لله وحده، الله يقول: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، ويقول سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106]، يعني المشركين، ويقول ﷺ: الدعاء هو العباد، والنبي -أيضاً- يقول ﷺ: إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله، فالميت قد انقطع عمله مع الناس، فهو بحاجة إلى أن يدعى له إلى أن يستغفر له، إلى أن يترحم عليه لا يدعى من دون الله، يقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له فكيف يدعى من دون الله؟ وهكذا الأصنام، وهكذا الأشجار والأحجار، وهكذا القمر والشمس والكواكب كلها لا تدعى من دون الله، كلها لا تدعى ولا يستغاث بها، فهكذا أصحاب القبور وإن كانوا أنبياء، وإن كانوا صالحين، هكذا الملائكة والجن لا يدعون مع الله، والله يقول سبحانه: وَلا يَأْمُرَكُمْ أَنْ تَتَّخِذُوا الْمَلائِكَةَ وَالنَّبِيِّينَ أَرْبَابًا أَيَأْمُرُكُمْ بِالْكُفْرِ بَعْدَ إِذْ أَنْتُمْ مُسْلِمُونَ [آل عمران:80]، فجعل اتخاذ الملائكة والنبيين أربابًا بالدعاء والاستغاثة كفراً، والله لا يأمر به ، وفي حديث جابر عند مسلم يقول : نهى رسول الله ﷺ عن تجصيص القبور، وعن القعود عليها، وعنن البناء عليها، هكذا رواه مسلم في الصحيح عن جابر (أن الرسول ﷺ نهى عن تجصيص القبور، وعن القعود عليها، وعن البناء عليها) لماذا؟ لأن هذا وسيلة إلى الشرك، البناء عليها والتجصيص والكسوة والقباب كله هذا وسيلة إلى تعظيمها والغلو فيها ودعاء أهلها، أما القعود عليها هو امتهان لا يجوز، كون يقعد عليها لا هي محترمة لا تمتهن لا يقعد عليها، لا يبول عليها، لا يتغوط عليها، لا يستند إليها، لا يطؤها، هذا ممنوع احترام المسلم حياً وميت محترم لا يجوز أن يداس قبره ولا أن تكسر عظامه، ولا أن يقعد على قبره، ولا أن يبال عليه، ولا أن توضع عليه قمائم كل هذا ممنوع، فالميت لا يمتهن المسلم لا يمتهن ولا يدعى من دون الله، لا يغلى فيه ويدعى من دون الله ولا يمتهن ويداس وتوضع عليه القمائم والأبوال والقاذورات لا، لا هذا ولا هذا، الشريعة جاءت بالوسط، جاءت باحترام القبور والدعاء لأهلها بالمغفرة والرحمة وزيارتهم للدعاء لهم والاستغفار لهم، ونهت عن إيذائهم بالقمائم، بالبول، بالقعود عليهم إلى غير ذلك، ومن هذا ما جاء في الحديث الصحيح يقول ﷺ: لا تجلسوا على القبور ولا تصلوا إليها، لا تجعل قبلة ولا يقعد عليها، فجمعت الشريعة الكاملة العظيمة بين الأمرين، بين تحريم الغلو في أهل القبور ودعائهم من دون الله، والاستغاثة بهم والنذر لهم ونحو ذلك، وهذا من الشرك الأكبر، وبين النهي عن إيذائهم وامتهانهم والجلوس على قبورهم أو الوطء عليها والاستناد إليها، أو وضع القاذورات عليها كل هذا ممنوع فلا هذا ولا هذا.\nوبهذا يعلم المؤمن ويعلم طالب الحق أن الشريعة جاءت بالوسط، لا بالشرك ولا بالإيذاء، فالميت المسلم النبي أو الصالح يدعى له، يستغفر له، يسلم عليه عند زيارته، أما أنه يدعى من دون الله لا، لا يقال: يا سيدي المدد المدد، أو انصرني أو اشف مريضي، أو أعني على كذا، لا هذا يطلب من الله، ولا يمتهن يوضع ... القمامة على قبره، يوطأ عليه، يجلس عليه، يبال لا، لا هذا ولا هذا.\nأما الحي فلا بأس أن يتعاون معه لأن له عمل، الحي له عمل فلا بأس أن يتعاون معه فيما يجوز شرعاً من الأسباب الحسية، كما قال تعالى: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15] في قصة موسى ، فإن موسى حي والمستغيث حي، فاستغاثه على عدوه، وهكذا الإنسان مع إخوانه، مع أقاربه، يتعاونون في مزارعهم، في إصلاح بيوتهم، في إصلاح سياراتهم، في أشياء أخرى من حاجاتهم يتعاونون بالأسباب الحسية المقدورة لا بأس، وهكذا من طريق الهاتف التلفون، من طريق المكاتبة، من طريق الإبراق والتلكس كل هذا تعاون حسي لا بأس به في الأمور المقدورة، لكن ما يتعلق بالعبادة لا، لا يقال للحي ولو أنه حي، لا يقال للحي: اشف مريضي، ورد غائبي من طريق سر فيه أن له سراً، ولا يقال: انصرنا على عدو بسر يعني، لا، وانصرنا بالسلاح، وانصرنا بالقرض دراهم يقرضهم إياها حتى يستعينوا بها على شئون الحرب لا بأس، كذلك يأتي الطبيب يطلب منه العلاج لا بأس، أما يقول اشفني لأنه يعتقد فيه سر، لأنه من شيوخ الصوفية أو من غيرهم، هذا كفر لأن الإنسان ما يقدر، لا، ما له سر يقدر يتصرف في الكون، إنما أمور حسية، الطبيب يتصرف بالأدوية، كذلك الإنسان القادر الحي يتصرف بالأسباب الحسية، يعينك بيده، يبني معك، يعطيك مال قرض أو مساعدة تبني به، يعطيك قطع غيار لسيارتك، يساعدك في شفاعة لدى من يعينك هذه أمور حسية لا بأس بها لا تدخل في عبادة الأموات والاستغاثة بالأموات ونحو ذلك، وكثير من دعاة الشرك يشبهون بهذه الأمور، وهي أمور واضحة بينة لا تشتبه إلا على من هو من أجهل الناس، فالتعامل مع الأحياء شيء جائز بشروطه المعروفة، وسؤال الأموات والاستغاثة بالأموات والنذر لهم أمر معروف عند أهل العلم شرك أكبر بإجماع أهل العلم، ليس فيه نزاع بين الصحابة ومن بعدهم من أهل العلم والإيمان وأهل البصيرة.\nوالبناء على القبور واتخاذ المساجد عليها والقباب كذلك منكر معلوم عند أهل العلم جاءت الشريعة بالنهي عنه فلا يجوز أن يلتبس هذا على أهل العلم.\nفالواجب على أهل العلم مرة أخرى الواجب عليهم أن يتقوا الله أينما كانوا، وأن ينصحوا لعباد الله، وأن يعلموا شريعة الله، وأن لا يجاملوا في ذلك زيداً ولا عمراً، بل يعلموا الأمير والصغير والكبير، ويحذروا الجميع مما حرم الله، ويرشدوهم إلى ما شرع الله، هذا هو الواجب على أهل العلم أينما كانوا، من طريق الكلام الشفهي، ومن طريق الكتابة، ومن طريق التأليف، ومن طريق الخطابة في الجمع وغيرها، من طريق الهاتف، من طريق التلكس، من أي الطرق التي وجدت الآن، يستعان بها على تبليغ دعوة الله وعلى نصح عباد الله، رزق الله الجميع التوفيق والهداية، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/8158/حكم-الغلو-في-الصالحين-وبناء-القباب-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_275/27504.mp3","categories":["نواقض الإسلام","الفرق والمذاهب"]},{"id":10832,"question":"رسالة أخرى وصلت إلى البرنامج من المستمع حسين بن بديع بن رفاعي من محافظة بني سويف في جمهورية مصر العربية يقول: هناك طريقة استحدثت تسمى بـالبرهانية تابعة لرجل يدعى محمد عثمان البرهاني، وهذه الطريقة تؤول القرآن العظيم، وهي سريعة الانتشار، فما حكم الشرع في هذه الطريقة، وهل هي كافرة، أم كما تدعي هي أنها هي الفرقة الناجية، وما الأدلة الشرعية في تكفيرها إذا كانت كافرة؟ وجهونا جزاكم الله خيرًا.","title":"حكم الطرق الصوفية","answer":"الجواب:  جميع الطرق الصوفية البرهانية، والشاذلية، وغير ذلك من الطرق الصوفية والتيجانية وغير ... كلها خطيرة، يجب الحذر منها، والبعد منها، وعدم الثقة بها. وهم أقسام منهم الكافر، ومنهم غير الكافر. فينبغي للمؤمن أن يبتعد عن كتب الصوفية، وقراءتها؛ لأنها تضره، وفيها من الباطل والشر الشيء الكثير، فينبغي لك يا عبدالله! أن تبتعد عنها، وأن تقرأ كتب أهل السنة والجماعة، التي فيها الخير، فيها بيان ما دل عليه كتاب الله، وسنة رسوله -عليه الصلاة والسلام- وفيها الكفاية، وفي الإقبال على القرآن، والإكثار من تلاوته، وتدبر معانيه الخير العظيم، والسعادة، وفي كتب السنة الصحيحة الثابتة عن رسول الله ﷺ الخير والبركة، فإن السنة تشرح القرآن، وتفسر معناه، وتبين ما أشكل على طالب العلم من ذلك، فالله أنزل كتابه هدى للناس كما قال : إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، قال تعالى: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ [النحل:89] قال سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] وقال : وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155]. والنبي ﷺ بين لنا ما قد يشكل علينا، وأوضح للأمة ما يحتاجون إليه، فعليك يا عبدالله! أن تكتفي بما جاء به الكتاب والسنة، وأن تبتعد عن الكتب التي فيها الخرافات والضلالات والبدع، مثل كتب الصوفية وغيرها مما جمعه الكفرة، أو المتكلمون، أو أصحاب الطرق المنحرفة، فإن فيها من الشر والبلاء والمخالفة لشرع الله ما يضر العبد إذا تمسك به، أو أخذ به، أو قرأه وهو على غير بصيرة، نسأل الله السلامة. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9012/حكم-الطرق-الصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35505.mp3","categories":["الفرق والمذاهب"]},{"id":10838,"question":"رسالة أخرى وصلت إلى البرنامج من المستمع حسين بن بديع بن رفاعي من محافظة بني سويف في جمهورية مصر العربية يقول: هناك طريقة استحدثت تسمى بـالبرهانية تابعة لرجل يدعى محمد عثمان البرهاني، وهذه الطريقة تؤول القرآن العظيم، وهي سريعة الانتشار، فما حكم الشرع في هذه الطريقة، وهل هي كافرة، أم كما تدعي هي أنها هي الفرقة الناجية، وما الأدلة الشرعية في تكفيرها إذا كانت كافرة؟ وجهونا جزاكم الله خيرًا.","title":"حكم الطرق الصوفية","answer":"الجواب:  جميع الطرق الصوفية البرهانية، والشاذلية، وغير ذلك من الطرق الصوفية والتيجانية وغير ... كلها خطيرة، يجب الحذر منها، والبعد منها، وعدم الثقة بها. وهم أقسام منهم الكافر، ومنهم غير الكافر. فينبغي للمؤمن أن يبتعد عن كتب الصوفية، وقراءتها؛ لأنها تضره، وفيها من الباطل والشر الشيء الكثير، فينبغي لك يا عبدالله! أن تبتعد عنها، وأن تقرأ كتب أهل السنة والجماعة، التي فيها الخير، فيها بيان ما دل عليه كتاب الله، وسنة رسوله -عليه الصلاة والسلام- وفيها الكفاية، وفي الإقبال على القرآن، والإكثار من تلاوته، وتدبر معانيه الخير العظيم، والسعادة، وفي كتب السنة الصحيحة الثابتة عن رسول الله ﷺ الخير والبركة، فإن السنة تشرح القرآن، وتفسر معناه، وتبين ما أشكل على طالب العلم من ذلك، فالله أنزل كتابه هدى للناس كما قال : إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، قال تعالى: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ [النحل:89] قال سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] وقال : وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155]. والنبي ﷺ بين لنا ما قد يشكل علينا، وأوضح للأمة ما يحتاجون إليه، فعليك يا عبدالله! أن تكتفي بما جاء به الكتاب والسنة، وأن تبتعد عن الكتب التي فيها الخرافات والضلالات والبدع، مثل كتب الصوفية وغيرها مما جمعه الكفرة، أو المتكلمون، أو أصحاب الطرق المنحرفة، فإن فيها من الشر والبلاء والمخالفة لشرع الله ما يضر العبد إذا تمسك به، أو أخذ به، أو قرأه وهو على غير بصيرة، نسأل الله السلامة. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9012/حكم-الطرق-الصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35505.mp3","categories":["الفرق والمذاهب"]},{"id":11610,"question":"سماحة الشيخ! ألاحظ في رسالة أخينا أنه يكثر من قوله: إن هذا لم يرد في القرآن، إن هذا لم يرد في القرآن، هل من تعليق على هذا؟ جزاكم الله خيرًا.","title":"حكم من يحتج بالقرآن فقط وينكر السنة","answer":"الجواب:  نعم، هذا قول طائفة من الناس ترى أنه لا يحتج بالسنة، وإنما يحتج بالقرآن فقط، وأن السنة فيها الضعيف وفيها الصحيح، وأنها عندهم ملتبسة لا يحتج بها، وهذا معناه عصيان قوله -جل وعلا-: أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النساء:59] فمعناه: أطيعوا الله فقط، ولا يطاع الرسول،، فالسنة هي أمر الرسول ونهيه -عليه الصلاة والسلام- والله يقول: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63] ويقول -جل وعلا-: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] ويقول ﷺ: إني أوتيت القرآن ومثله معه.  فهذه الطائفة التي ترى أن السنة لا يحتج بها جميعها طائفة كافرة ضالة، فالواجب على من يعرفهم أن يهجرهم، وأن يعرفهم أنهم على باطل، وأنهم كفار بهذا العمل، بإنكارهم السنة يكفرون، ويخرجون من دائرة الإسلام، بل يجب على كل مسلم أن يقبل السنة، وأن يعمل بما صح منها، وأن يحذر إنكارها، فإنكارها بالكلية، وأنه لا يحتج إلا بالقرآن هذا من أبطل الباطل، وأعظم الكفر، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9796/حكم-من-يحتج-بالقران-فقط-وينكر-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38807.mp3","categories":["نواقض الإسلام","الفرق والمذاهب"]},{"id":12663,"question":"يسأل ويقول: إذا كان شخص ما على الطريقة التيجانية، فهل يجوز أن يصلي بالناس إمامًا؟","title":"حقيقة الطريقة التيجانية وحكم الصلاة خلف منتسبيها","answer":"الجواب:  الطريقة التيجانية طريقة خبيثة رديئة، لا يجوز اعتناقها، ولا البقاء عليها، ولا يجوز أن يتخذ أهلها أئمة في المساجد، ولا يصلى خلفهم، بل الواجب تركها، والحذر منها، وقد كتبنا في ذلك ما تيسر، وذلك المكتوب يوزع لمعرفة حقيقتها، فنصيحتي لأهلها أن يتركوها، وأن يستقيموا على طريقة الرسول ﷺ في أصل خلواتهم، وفي سائر أعمالهم، يقول الله : لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] فالأسوة هو النبي ﷺ لا أحمد التيجاني ولا غيره. فالواجب على أهل الإسلام أن يتأسوا بالنبي ﷺ في أقوالهم وأعمالهم وسيرتهم، وأن يستقيموا على دينه، وطريقه -عليه الصلاة والسلام- وأن ينفذوا ما أمر الله به ورسوله، وأن ينتهوا عما نهى الله عنه ورسوله. أما العقيدة التيجانية فهي طريقة محدثة، وبدعة منكرة، ولا يجوز أن يؤخذ منها إلا ما وافق الكتاب والسنة، ما وافق الكتاب والسنة؛ لا بأس منها ومن غيرها؛ لأن الاعتبار بموافقة الكتاب والسنة، وما خالف ذلك؛ وجب طرحه، وتركه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10873/حقيقة-الطريقة-التيجانية-وحكم-الصلاة-خلف-منتسبيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45815.mp3","categories":["الفرق والمذاهب"]},{"id":12817,"question":"يقول: إنني سالك طريق من شيخ خلوتي، وإنني على علم يقين أنه رجل طيب وتقي جدًا جدًا. ودائمًا كل إنسان سلك معه طريقًا؛ صار صالحًا وتاب، كما كان فيه من يحمل المنكر، وهذا السؤال بناءً على أنكم ذكرتم أن جميع الطرق الصوفية من البدع، أفيدوني أفادكم الله عن وضعي الذي أنا فيه، هل أستمر، أم أتخلى عنه، جزاكم الله خيرًا؟","title":"بدعية الطرق الصوفية","answer":"الجواب:  نعم جميع الطرق الصوفية من البدع، ولكن يقع فيها أشياء توافق الحق، فما وافق الحق؛ وجب أخذه؛ لأنه وافق الحق، لا لأنه من طريق خلوتي أو القادري أو الشاذلي أو فلان أو فلان لا، ما وقع في طرقهم من الخير يقبل؛ لأنه وافق الشرع، وما خالفه يترك، وإذا أردت أن نبين لك ما هو الخير والشر فاذكر لنا الطريقة التي أنت عليها اشرحها لنا في سؤال آخر ونوضح لك ما هو الخير؟ وما هو الشر؟ -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11031/بدعية-الطرق-الصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46305.mp3","categories":["الفرق والمذاهب"]},{"id":13439,"question":"المستمع بشير شداد بعث يسأل ويقول: من هم الصوفيون؟ وما موقف الإسلام منهم؟جزاكم الله خيرًا.","title":"التعريف بالصوفية","answer":"الجواب: الصوفيون جماعات اشتهروا بإحداث طرق في العبادة والتنسك ما شرعها الله في صلواتهم، وفي أذكارهم، وفي خلواتهم، يقال لهم الصوفية، قال بعضهم: معناه من التصوف؛ لأنهم يلبسون الصوف، وقال بعضهم: إنها من الصفا، وأن النسبة غير لغوية، يعني: غير مستقيمة على الطريق السوي في النسبة، وأنها من الصفا، وأنهم يعتنون بصفاء القلوب من الكدر .. من كدر الذنوب، وكدر الكسب الحرام، ونحو ذلك. فالتصوف: هو التعبد على طريقة خاصة، لم تأت بها الشريعة؛ ولهذا غلب على المتصوفة البدع، ويسمى الزاهد الذي يحرص على التفرغ للعبادة، والزهد في الدنيا، وطلبها يسمى -أيضًا-: صوفي. لكن إذا كان ما أحدث بدعة، وإنما صفته الزهد والرغبة في الآخرة، والتقلل من الدنيا، والحرص على أعمال الآخرة، هذا ما يسمى صوفيًا في الحقيقة، يسمى زاهدًا. فإذا كان زهده لا يوقعه فيما حرم الله، ولا يزيد في أعماله على ما أوجب الله، ولا يبتدع، بل يتحرى الشريعة في أعماله وأقواله؛ فهذا مشكور، ويثنى عليه كـالجنيد بن محمد، وأبي سليمان الداراني، وبشر الحافي، وجماعة اجتهدوا في العبادة والزهد في الدنيا، هؤلاء يثنى عليهم كثيرًا؛ من أجل زهدهم، ورغبتهم في الآخرة، وعدم ابتداعهم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11736/التعريف-بالصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47716.mp3","categories":["الفرق والمذاهب"]},{"id":14322,"question":"يسأل ويقول: كثيرًا ما أسمع أن أحد الأشخاص أخذ طريقة من أحد السادة أو المشايخ، وبعد ذلك يستطيع أن يضرب نفسه بالسيف ويأكل الزجاج، أريد من سماحتكم السر في هذه الطريقة وماذا يقال له، وبماذا توجهونني وأنا شاب في مقتبل العمر؟ جزاكم الله خيرًا.","title":"التحذير من الطرق الصوفية","answer":"الجواب: هذه الطريقة من طرق الصوفية الباطلة، وهذه كلها تخييل وكلها كذب، لا يطعن نفسه ولا يذبح نفسه كلها كذب، كلها باطلة، كلها تخييل على الناس من عمل الشياطين، وعمل أعداء الله الذين زينوا لهم هذا الباطل، فالشياطين توحي لهم أن يفعلوا هذه الأشياء وتعمل ما يجعل الحاضرين يظنون أن هذا واقع، وليس بواقع يقتل نفسه يطعن نفسه بالجنبية بالسكين بالرمح، يقطع رأسه ويزيله، كل هذه خرافات كلها باطلة، والذين يعملونها هم مبطلون ضالون مضلون، يجب أن يعاقبوا على ذلك، يجب على ولاة الأمور إذا كانوا مسلمين أن يعاقبوهم وأن يمنعوهم من هذه الطريقة الخبيثة، وبعضهم يسميها الطريقة الرفاعية.\nفالمقصود: أن هذه الطريقة باطلة، ... يزعمون من الطعن طعنهم أنفسهم بالسكاكين أو بالرماح أو بالخناجر كلها باطلة، وكأكلهم الزجاج كله باطل، يكذبون، فلو طعن نفسه لهلك، ولو أكل الزجاج لهلك، لكن هذه من خدع الشيطان ومن مكايد الشيطان التي يلعب بها على الناس، نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12810/التحذير-من-الطرق-الصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_487/48702.mp3","categories":["الفرق والمذاهب"]},{"id":14674,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول حسن محمود حمدان، سوداني يعمل بمنطقة المدينة المنورة، أخونا حسن له سؤال طويل بعض الشيء، يقول فيه: قرأت كتابًا عنوانه: (كتاب الطبقات) للشيخ: محمد بن ضيف الله، ويشتمل هذا الكتاب على قصص أصحاب الطرق الصوفية ومشائخها، وقرأت بهذا الكتاب قصة غريبة، وهي أن أحد المشايخ قد توفي عند وقت العصر، وحينما أراد الحاضرون أن يذهبوا به إلى المقبرة، وكان بينهم وبينها البحر، وعندما وصلوا إلى شاطئ البحر كادت الشمس أن تغرب، وفكروا في أن يرجعوا بالجنازة ويصبرونها حتى الصبح، وحين تشاورهم في ذلك الأمر، فإذا بالشمس ترجع إلى المشرق حتى ذهبوا بالجنازة، وقطعوا بها البحر، ودفنوها، أسأل عن مثل هذا القصص، هل يقع لأولياء الله؟أفتونا، عظم الله مثوبتكم.","title":"حقيقة كرامات الصوفية التي يدعونها","answer":"الجواب: باسم الله.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فهذه قصة من موضوعات الصوفية وكذبهم الكثير، فلا ينبغي أن يغتر بهم، ولا نعلم هذا وقع لأحد من الأولياء، وإنما وقع ليوشع بن نون فتى موسى، وهو نبي من الأنبياء لما حاصر الجبارين.  فالمقصود: أن هذا لم يقع لأحد من الأولياء فيما نعلم، والصوفية يكذبون كثيرًا، ولا ينبغي أن يغتر بما يقولون، ولا يعتمد على ما ينقلون من الوقائع، وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ [البقرة:284] لكن لا نعلم لهذا أصلًا، وهو  القادر على كل شيء، ولم يقع هذا لأحد فيما نعلم فيما صحت به السنة، سوى ما علم من قصة يوشع بن نون، نعم، فتى موسى، نعم. المقدم: نعم.","link":"https://binbaz.org.sa/fatwas/13164/حقيقة-كرامات-الصوفية-التي-يدعونها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_628/nour_62801.mp3","categories":["الفرق والمذاهب"]},{"id":14933,"question":"نبدأ بسؤال أبو هشيم الحسن البحاري الحسين، السودان، معهد التربية الذي بقي علينا في لقائنا الماضي، يقول أبو هشيم في سؤاله هذا:إن هنا بالسودان كثيرًا من الطرق الدينية مثل الطرق الصوفية، والإخوان المسلمين، وأنصار السنة، والإخوة الجمهوريون، وعدد أسماء كثيرة جدًا، والزعيم محمود محمد طه، والذي يدعي بأن الصلاة رفعت عنه، وأن اللحم محرمة، وإلى آخره، ذكر طرق عديدة، يقول: فما رأيكم في ذلك؟ وما هو موقفنا نحن؟ هل نقف مع إحدى هذه الطرق، أم نقف منحازين ومنفردين؟وفقكم الله.","title":"ما الواجب على الجماعات تجاه بعضها؟","answer":"الجواب: الطريق السوي هو طريق محمد ﷺ، ليس هناك طريق سديد، ولا صالح إلا طريق محمد ﷺ، هو الطريق السوي، وهو الصراط المستقيم.  أما الطرق التي أحدثها الصوفية، أو أحدثها غيرهم مما يخالف شريعة الله، فهذا لا يعول عليه، ولا يلتفت إليه، بل الطرق كلها مسدودة إلا الطريق الذي بعث الله به نبيه محمدًا ﷺ هو الطريق الصحيح، وهو الطريق الموصل إلى الله وإلى جنته وكرامته. أما الألقاب كونه يلقب: أنصار السنة، أو تنظيم الإخوان المسلمين، أو جماعة المسلمين، أو جمعية كذا، لا بأس بهذه الألقاب، الألقاب ما تضر، المهم العمل إذا كانت الأعمال تخالف شريعة الله تمنع، وهكذا طرق الصوفية كل الطرق التي أحدثها الصوفية مما يخالف شرع الله كله منكر لا يجوز، وليس للصوفية ولا لغيرهم أن يحدثوا طريقًا يسلكونه غير طريق محمد ﷺ، لا في الأذكار، ولا في العبادات الأخرى، بل لا بد أن يسلكوا طريق محمد ﷺ طريق نبينا -عليه الصلاة والسلام-، ليس للناس طريق آخر، بل الواجب على جميع أهل الأرض أن يسلكوا طريق نبينا وإمامنا وسيدنا محمد بن عبدالله عليه من ربه أفضل الصلاة والتسليم؛ في أقوالهم وأعمالهم، وهو الطريق الذي قال الله فيه: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6] وهو الذي قال فيه -جل وعلا-: وإنك، يعني: يخاطب النبي ﷺ وَإِنَّكَ لَتَهْدِي إِلَى صِرَاطٍ مُسْتَقِيمٍ ۝ صِرَاطِ اللَّهِ [الشورى:52-53] هكذا قال -جل وعلا- في سورة الشورى، فهذا طريق الله، وهو صراط الله الذي بعث الله به نبيه وخليله نبينا محمد ﷺ. فالواجب على جميع أهل الأرض أن يأخذوا بهذا الطريق، وأن يستقيموا عليه، وليس للصوفية ولا لغير الصوفية أبدًا أن يحدثوا طريقًا آخر، لا في أذكارهم الصباحية ولا المسائية، ولا في غير ذلك، ولا في استحضارهم شيوخهم عند صلاتهم، لا كل هذا منكر، ولكن إذا قام في الصلاة أو في الأذكار يستحضر ربه، يكون في قلبه ربه -جل وعلا- يستحضر عظمته وكبريائه، وأنه واقف بين يديه، فيعظمه -جل وعلا- ويخشاه ويراقبه، ويكمل صلاته ويكمل عبادته على خير وجه، حسب ما جاء عن رسول الله -عليه الصلاة والسلام-، هذا هو الواجب. أما كون بعض الجماعات تلقب نفسها بشيء علامة لها مثل: أنصار السنة في السودان، أو في مصر، لا حرج في ذلك، إذا استقام الطريق إذا سلكوا طريق نبينا ﷺ واستقاموا عليه، أو مثل الإخوان المسلمين لقبوا أنفسهم بهذا اصطلاحًا بينهم، لا يضر، لكن بشرط أن يستقيموا على طريق محمد ﷺ، وأن يسلكوه، وأن يعظموه، وأن يعتقدوا أن جميع المسلمين إخوانهم من أنصار السنة من جماعة المسلمين من أي مكان، لا يتحزبون لأصحابهم فيعادوا غيرهم من المسلمين، لا بل يجب أن تكون هذه ألقاب غير مؤثرة في الإخوة الإسلامية.  أما إذا أثرت فصار يرضى لحزبه، ويغضب لحزبه، ويقرب حزبه، ويباعد غير حزبه، ولو كانوا أفضل من حزبه، ولو كانوا أهل إيمان وتقوى، هذا منكر، هذا لا يجوز، هذا تفرق في الدين، والله يقول سبحانه: وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلا تَفَرَّقُوا [آل عمران:103]. فإذا كان التلقب بـأنصار السنة، أو بـالإخوان المسلمين، أو بكذا أو بكذا يؤثر في الإخوة الإيمانية، يؤثر في التعاون على البر والتقوى؛ هذا لا يجوز، فهم إخوة في الله يتعاونون على البر والتقوى ويتناصحون، مهما تنوعت ألقابهم، أما إذا أوجدوا لقبًا يوالون عليه، ويعادون عليه، ويعتبرون من دخل فيه هو وليهم، ومن لا فلا، هذا لا يجوز، نعم.","link":"https://binbaz.org.sa/fatwas/13430/ما-الواجب-على-الجماعات-تجاه-بعضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_647/nour_64701.mp3","categories":["الفرق والمذاهب"]},{"id":15098,"question":"المستمع عبدالله أبو الحسن، بعث لنا بهذه الرسالة، يقول: بعض الناس عندنا يدعون الشيخية الطريقة كطريقة النقشبندية والقادرية وغيرها، يجتمعون بالناس في المساجد، ويدعونهم إلى التوبة والتوجد، ويقول أحدهم: أنا مأذون لذلك، فيغمغمون بعض منهم، ويتكلمون بألفاظ مهملة مثل: ها هي هو، ويتكلمون بالغيب، فهل لهذا حقيقة وكرامة، أم أن هذه من باب البدع والضلالة؟نرجو التوفيق في الإجابة، وفقكم الله.","title":"حقيقة الطريقة الشيخية وحكم حضور اجتماعاتها","answer":"الجواب: هذه الطرق وأشباهها كلها من الطرق البدعية، ولا يجوز الموافقة عليها، ولا المشاركة فيها؛ لأنها بدع، وقد قال النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد وقال -عليه الصلاة والسلام-: من عمل عملًا ليس عليه أمرنا فهو رد وليس هذا من سنة النبي ﷺ الاجتماع على هو هو هو، أو على كلام ليس بظاهر، وليس بمعلوم، وإذا كان فيه دعوى علم الغيب صار هذا أعظم نكارة، وأخبث عملًا، بل هذا هو الشرك؛ لأن دعوى علم الغيب منكر وكفر، علم الغيب لا يعلمه إلا الله . والحاصل: أن هذه الطرق الصوفية النقشبندية والقادرية والشيخية هذه وأشباهها كلها طرق مبتدعة، لا يجوز منها إلا ما وافق الشرع المطهر، فالواجب تجنبها، وعدم الاشتراك فيها، وألا تفعل إلا الشيء المعروف الذي جاء به النبي ﷺ كذكر الله وحدك، أو مع إخوانك، كل يذكر الله فيما بينه وبين نفسه، أما ذكر الله الجماعي على طريقة الصوفية، أو هو هو هو، أو الله الله الله الله، أو ما أشبه ذلك، أو الإتيان بدعوات منكرة، ليس لها أصل، بل فيها ما يدل على دعوى علم الغيب، أو فيها ما يدعو إلى منكر، أو فيها ما يدل على تعظيم المخلوق تعظيمًا لا يليق به، بل لا يليق إلا بالله، كل هذا لا يجوز، فهذه الطرق يجب الحذر منها، ويجب تمييزها، وأن لا يقر منها إلا ما وافق الشرع المطهر، وما خالف ذلك ينهى عنه وينكر، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13595/حقيقة-الطريقة-الشيخية-وحكم-حضور-اجتماعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_664/nour_66404.mp3","categories":["الفرق والمذاهب"]},{"id":15695,"question":"السائل: إبراهيم من الرياض، يقول: من هي الفرقة الناجية؟ وما خصائصها؟","title":"خصائص الفرقة الناجية","answer":"الجواب: الفرقة الناجية هي: المتمسكة بما جاء به النبي ﷺ، هم أهل السنة والجماعة، الفرقة الناجية: هم الذين آمنوا بالله ورسوله، واستقاموا على دين الله، وآمنوا بكل ما أخبر الله به ورسوله، وساروا على نهج رسول الله ﷺ، بأداء فرائض الله، وترك محارم الله، والإيمان بأن الله سبحانه فوق العرش، قد استوى عليه، استواءً يليق بجلاله وعظمته، وأنه سبحانه مسمى بالأسماء الحسنى، موصوف بالصفات العلى، لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ[الشورى:11] هم أهل السنة والجماعة، وهم الفرقة الناجية. فالأمة افترقت على ثلاث وسبعين فرقة، كلها في النار إلا واحدة، وهذه الواحدة هي الفرقة الناجية، هي التي آمنت بالله ورسوله، وآمنت بأسماء الله وصفاته، وآمنت بأنه سبحانه مستحق العبادة، وأنه الإله الحق، وأنه فوق العرش، قد استوى عليه، استواء يليق بجلاله، وأنه مسمى بالأسماء الحسنى، والصفات العلى، الواردة في الكتاب العزيز، وفي السنة الصحيحة المطهرة، هم أهل السنة والجماعة، وهم الفرقة الناجية، وهم الطائفة المنصورة، إلى قيام الساعة، وإن قلوا، وإن قلوا في أي مكان. أما الثنتان والسبعون فرقة، فهم متوعدون بالنار، فيهم الكافر، وفيهم المبتدع، الذي ليس بكافر، هم الذين حادوا عن طريقة السلف، لكن تارةً يكون الذي حاد عنها كافرًا، وتارة يكون دون ذلك، اثنتان وسبعون فرقة كلها متوعدة بالنار، فيهم الكافر والمبتدع، نعم، وفيهم من بدعته تلحقه بالكفرة، ومنهم من بدعته دون ذلك، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14251/خصاىص-الفرقة-الناجية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57304.mp3","categories":["الفرق والمذاهب"]},{"id":16450,"question":"يقول في سؤال طويل بعض الشيء سماحة الشيخ: هل يجب على الإنسان أن يكون بينه وبين الله  واسطة، فمثلًا أنا لا أصلي لمرضاة الله إلا عن طريق الشيخ، ويستشهدون بذلك بالحديث كما يقولون: (من لا شيخ له فشيخه الشيطان) كما أنهم يقولون: هذا الشيخ يمشي على طريقة الشيخ الرفاعي، وهذا الشيخ يمشي على طريقة الشيخ الشاذلي ، هل هؤلاء الأولياء لهم كرامات عند الله بعد أن ماتوا، ولهم طرق يجب علينا اتباعها؛ ليرضوا عنا في قبورهم، فنبقى على طرقهم كما يقولون، ويستمر في السؤال عن هذه القضية، جزاكم الله خيرًا سماحة الشيخ؟","title":"حكم عبادة الله تعالى بالطرق الصوفية","answer":"الجواب: هذه الطرق كلها مبتدعة: الشاذلية، والرفاعية، والنقشبندية، والخلوتية، والقادرية... وغير ذلك، كلها طرق صوفية مبتدعة، يجب تركها، والطريق الذي يجب سلوكه هو طريق النبي ﷺ طريق أهل السنة والجماعة، طريق الصحابة -رضي الله عنهم وأرضاهم- الذي تلقوه عن نبيهم، عليه الصلاة والسلام. فأنت تتبع ما في كتاب الله، وسنة رسوله ﷺ وتسأل علماء السنة عما أشكل عليك، هذا هو الواجب عليك، أما قولهم: (من لا شيخ له فشيخه الشيطان) هذا باطل، ما له أصل، وليس بحديث، وليس لك أن تتبع طرق الشيخ إذا كان مخالفًا للشرع، بل عليك أن تتبع الرسول ﷺ وأصحابه -رضي الله عنهم وأرضاهم، ومن تبعهم بإحسان- في صلاتك، وفي دعائك، وفي سائر أحوالك، يقول الله -جل وعلا-: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] ويقول سبحانه وتعالى: وَالسَّابِقُونَ الأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالأَنصَارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسَانٍ رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ [التوبة:100] الآية. فأنت عليك أن تتبعهم بإحسان، باتباع الشرع الذي جاء به النبي ﷺ والتأسي به في ذلك، وعدم البدعة التي أحدثها الصوفية، وغير الصوفية ؟ نعم، الله المستعان. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15160/حكم-عبادة-الله-تعالى-بالطرق-الصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_715/nour_71510.mp3","categories":["الفرق والمذاهب"]},{"id":16755,"question":"بعد هذا رسالة وصلت إلى البرنامج من الجمهورية العربية السورية باعثها المستمع (ع. ب. د) يسأل سماحتكم سؤالًا يقول فيه: أسألكم عن الصوفيين، وعن حقيقتهم، وخرافاتهم، إذ أننا نسمع كثيرًا عنهم، ولاسيما فيما يكتب في كتب محيي الدين بن العربي الصوفي؟ وجهونا جزاكم الله خيرًا.","title":"بعض مخالفات الصوفية وبيان حال ابن عربي","answer":"الجواب: الصوفية أقسام، وهم في الأغلب مبتدعة، عندهم أوراد، وعبادات يأتون بها، ليس عليها دليل شرعي، ومنهم ابن عربي فإنه صوفي مبتدع ملحد، وهو المعروف محيي الدين ابن عربي، وهو صاحب وحدة الوجود، وله كتب فيها شر كثير، فنحذركم من أصحابه، وأتباعه؛ لأنهم منحرفون عن الهدى، وليسوا بمسلمين. وهكذا جميع الصوفية الذين يتظاهرون بعبادات ما شرعها الله، أو أذكار ما شرعها الله، مثل: الله.. الله.. الله، هو.. هو.. هو، هذه أذكار ما شرعها الله، المشروع لا إله إلا الله، سبحان الله، والحمد لله، أما هو هو، الله الله الله الله هذا ما هو مشروع.  وهكذا ما يفعلون من الأغاني التي يرقصون عندها، مثلما يفعل بعضهم أغاني مع الرقص، وضرب آلات اللهو، أو ضرب سنته، أو صحن، أو غير ذلك، أو جعد، أو غير ذلك، كل هذه لا أصل لها كلها من البدع. والضابط: أن كل إنسان يتعبد بغير ما شرعه الله، يسمى مبتدعًا، فاحذروه، وعليكم بأتباع الرسول ﷺ من أهل السنة والجماعة الذين يسيرون على نهج النبي ﷺ وعلى ما كان عليه في أعماله -عليه الصلاة والسلام- يصلون كما يصلي، ويصومون كما يصوم، يحجون كما يحج من دون إحداث بدعة، فأنتم تحروا أهل السنة، واسألوا عنهم، وتعلموا منهم، وعلامتهم أنهم يتحرون ما قاله الله ورسوله، ويتحرون سيرة الصحابة، وما درجوا عليه، ويحذرون البدع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15505/بعض-مخالفات-الصوفية-وبيان-حال-ابن-عربي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_718/nour_71815.mp3","categories":["الفرق والمذاهب"]},{"id":17310,"question":"هل المبتدع خارج عن الفرقة الناجية، و الطائفة المنصورة؟","title":"هل أهل البدع يخرجون من الفرقة الناجية؟","answer":"الجواب: المبتدعون ليسوا من الطائفة المنصورة، كـالرافضة، والجهمية، والمعتزلة، والكرامية، وأشباههم، الطائفة المنصورة هم أهل السنة، والجماعة، هم أتباع الكتاب والسنة الذين لم يبتدعوا في دين الله ما لم يأذن به الله، لما سئل الرسول ﷺ عنهم قال: هم من كان على ما أنا عليه وأصحابي قال: هم الجماعة. فـالطائفة المنصورة، والفرقة الناجية هم أتباع النبي ﷺ الذين لم يحرفوا، ولم يغيروا، ولم يبتدعوا، بل تمسكوا بالكتاب والسنة، وساروا على منهج سلف الأمة من الصحابة، ومن تبعهم بإحسان في القول، والعمل، والعقيدة، هؤلاء هم أهل السنة، والجماعة الذين وحدوا الله، عبدوه وحده واستقاموا على شريعته، وآمنوا بأسمائه، وصفاته، وأمروها كما جاءت على الوجه اللائق بالله من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، واعتمدوا في أعمالهم ما جاء في الكتاب والسنة في الأقوال، والأعمال. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16153/هل-اهل-البدع-يخرجون-من-الفرقة-الناجية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_724/nour_72406.mp3","categories":["الفرق والمذاهب"]},{"id":17324,"question":"هل المبتدع خارج عن الفرقة الناجية، و الطائفة المنصورة؟","title":"هل أهل البدع يخرجون من الفرقة الناجية؟","answer":"الجواب: المبتدعون ليسوا من الطائفة المنصورة، كـالرافضة، والجهمية، والمعتزلة، والكرامية، وأشباههم، الطائفة المنصورة هم أهل السنة، والجماعة، هم أتباع الكتاب والسنة الذين لم يبتدعوا في دين الله ما لم يأذن به الله، لما سئل الرسول ﷺ عنهم قال: هم من كان على ما أنا عليه وأصحابي قال: هم الجماعة. فـالطائفة المنصورة، والفرقة الناجية هم أتباع النبي ﷺ الذين لم يحرفوا، ولم يغيروا، ولم يبتدعوا، بل تمسكوا بالكتاب والسنة، وساروا على منهج سلف الأمة من الصحابة، ومن تبعهم بإحسان في القول، والعمل، والعقيدة، هؤلاء هم أهل السنة، والجماعة الذين وحدوا الله، عبدوه وحده واستقاموا على شريعته، وآمنوا بأسمائه، وصفاته، وأمروها كما جاءت على الوجه اللائق بالله من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، واعتمدوا في أعمالهم ما جاء في الكتاب والسنة في الأقوال، والأعمال. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16153/هل-اهل-البدع-يخرجون-من-الفرقة-الناجية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_724/nour_72406.mp3","categories":["الفرق والمذاهب"]},{"id":17491,"question":"يقول: يوجد لدينا في كل ليلة من يوم الخميس، ويوم الإثنين يذكر الله أهل الطرق الصوفية بالطبول إلى ساعات متأخرة من الليل، هل الذكر بالطبل جائز وهل الطرق الصوفية هذه جائزة أم لا؟ جزاكم الله خيرًا.","title":"حكم ذكر الله بالطبل، وحكم الطرق الصوفية","answer":"الجواب: هذه الطرق الصوفية بدعة ومنكرة سواء كان على الطبول أو الدفوف أو العود أو الموسيقى أو التصفيق بالأيدي أو الضرب بالأرجل أو الرقص، التقرب بهذا الأمر هذا من البدع، سواء في ليلة الخميس أو ليلة الإثنين أو في غيرهما في أي وقت، فالواجب على أهل الإسلام التقرب بالقرب التي شرعها الله، التسبيح والتهليل والتحميد والذكر والاستغفار على غير هذا الصنف بغير الطبول وبغير ضرب الأرجل وبغير الصياح والصفير، وبغير الموسيقى والعود وغيره.\nوقد بسط العلامة ابن القيم رحمه الله هذا البحث في كتابه إغاثة اللهفان بسطًا جيدًا، فأنا أنصح بمراجعة إغاثة اللهفان الذي بسط فيها الكلام، على الطرق الصوفية والتحذير منها وهذا منها.\nفالسنة للمؤمن أن يفعل ما فعله النبي ﷺ، إذا فرغ من الصلاة يذكر الله كما فعل النبي ﷺ إذا سلم يستغفر الله ثلاثًا، ويقول: اللهم أنت السلام ومنك السلام، تباركت يا ذا الجلال والإكرام، ثم ينصرف إلى الناس إذا كان إمامًا، ثم يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه، له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، كان يفعل هذا بعد كل صلاة عليه الصلاة والسلام، كما روى هذا ابن الزبير في صحيح مسلم، وروى بعضه المغيرة بن شعبة في الصحيحين بعد كل صلاة. والاستغفار ثلاثًا مع قوله: اللهم أنت السلام.. رواه مسلم في صحيحه عن ثوبان ، وروى بعضه مسلم عن عائشة في: اللهم أنت السلام .. ثم ينصرف الإمام إلى الناس هذه السنة.\nثم بعد هذا يقول: سبحان الله والحمد لله والله أكبر ثلاثًا وثلاثين، ويختم المائة بقوله:  لا إله إلا الله، وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، صح هذا عن النبي ﷺ أنه قال: من فعل هذا غفرت له خطاياه وإن كانت مثل زبد البحر، وهذا فضل عظيم، فيستحب للمؤمن بعد الصلوات الخمس أن يأتي بهذا. بعد الأذكار السابقة، تقول: سبحان الله، والحمد لله، والله أكبر ثلاثة وثلاثين مرة، الجميع تسعة وتسعون، ثم يقول تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، وإن شاء قال: يحيي ويميت بيده الخير وهو على كل شيء قدير، كله جاء. ثم يقرآ آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ إلى آخرها ..إلى قوله: ..وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255]، هذه الآية أعظم آية يستحب أن تقرأ بعد كل صلاة فريضة ثم يقرأ قل هو الله أحد والمعوذتين بعد كل فريضة، بعد الظهر والعصر والمغرب والعشاء والفجر أفضل، لكن يكررها ثلاثًا، هذه السور الثلاث يقرأها ثلاث مرات بعد المغرب، وبعد الفجر وعند النوم، جاءت بذلك السنة عن النبي عليه الصلاة والسلام .... وفق الله الجميع.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16398/حكم-ذكر-الله-بالطبل-وحكم-الطرق-الصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72513.mp3","categories":["البدع والمحدثات","الفرق والمذاهب","المساجد ومواضع السجود"]},{"id":18153,"question":"جاء في حديث أن رسول الله ﷺ قال: \"من كفر مسلمًا فقد كفر\" فهل إذا كفر شخص ما مسلمًا يكون هذا الشخص كافرًا مرتدًا؟ أم أن هذا الحديث فقط يحدد فحش تكفير المسلم؟","title":"شرح حديث: \"من قال لأخيه يا كافر ...\"","answer":"الجواب: هذا اللفظ لا أعرف صحته الآن، ولكن معناه صحيح فقد قال ﷺ: من قال لأخيه يا عدو الله أو قال: يا كافر فقد باء بها أحدهما يعني: إذا لم يكن من قيل له ذلك صالحًا لها رجعت إلى من قالها، فلا يجوز للمسلم أن يكفر أخاه، ولا أن يقول: يا عدو الله ولا يا فاجر إلا بدليل، فإذا رمى أخاه بالكفر وليس كذلك رجع إليه كلامه. والمعنى التحذير، ليس معناه أنه كفر أكبر، بل معناه التحذير من هذا الكلام السيئ، وأن صاحبه على خطر عظيم إذا قاله لأخيه، فينبغي حفظ اللسان وأن لا يتكلم إلا عن بصيرة. المقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17189/شرح-حديث-من-قال-لاخيه-يا-كافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_905/nour_90507.mp3","categories":["مسائل متفرقة في العقيدة","شروح الحديث","الفرق والمذاهب"]},{"id":18388,"question":"هذا الأخ المستمع: (ع. م.ع) من اليمن يقول: سماحة الشيخ! من هي الفرقة الناجية؟","title":"من هي الفرقة الناجية؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالفرقة الناجية: هم الذين ساروا على منهج النبي ﷺ واستقاموا على دينه، يقول ﷺ: ستفترق أمتي على ثلاث وسبعين فرقة كلها في النار إلا واحدة قيل: من هي يا رسول الله؟! قال: الجماعة وفي لفظ قال: ما أنا عليه وأصحابي. فالفرقة الناجية: هم الذين استقاموا على دين الله وساروا على نهج النبي ﷺ ونهج أصحابه في توحيد الله والإخلاص له وطاعة أوامره وترك نواهيه والإيمان بأسمائه وصفاته على الوجه اللائق بالله، بغير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، هؤلاء هم أهل السنة والجماعة، وهم الفرقة الناجية. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/17457/من-هي-الفرقة-الناجية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91329.mp3","categories":["الفرق والمذاهب"]},{"id":18880,"question":"رسالة وصلت إلى البرنامج من المستمع: حسين نور أحمد الصومالي من إبقيق، أخونا في الواقع رسالته مطولة، ونحن في نهاية الحلقة، يسأل فيها سماحة الشيخ عن الصوفية، وعن بعض مشائخهم مثل: السيد البدوي، والشيخ عبد القادر الجيلاني، والشيخ يوسف الكونين فيما يبدو، يرجو توجيهه، ويذيل رسالته في نهايتها فيقول: هل تصدقون أنني طفت حول خشبة مصنوعة بشكل تابوت، ولم أكن وحدي، وكان احتفالًا نظمته إحدى الجهات، وجهونا تجاه هذه الجماعات.جزاكم الله خيرًا.","title":"التحذير من الصوفية ومن بدعهم وطقوسهم","answer":"الجواب: الجماعات المعروفة بـالصوفية جماعة محدثة، وجماعة مبتدعة، وهم متفاوتون في البدع، فيهم من بدعته تصل إلى الشرك الأكبر، وفيهم من بدعته دون ذلك، فوصيتي لك -أيها السائل- ألا تنتسب إليهم، وألا تغتر بهم، وألا تكون معهم، بل عليك باتباع السنة، والالتزام بما شرع الله، وما دل عليه كتاب الله، وسنة الرسول -عليه الصلاة والسلام- وسؤال أهل العلم المعروفين بالعقيدة الطيبة، والاستقامة على طريق أهل السنة والجماعة، مثل: أنصار السنة في مصر، أنصار السنة في السودان، ومن عرف بالعلم والفضل من سائر العلماء تسألهم، وتستفيد منهم، هذا هو الذي ينبغي لك. أما الصوفية فلا؛ لأن الغالب عليهم البدع والخرافات، وأشياء أحدثوها لأنفسهم، وجعلوها نظامًا لهم، ليس له أساس في الشرع المطهر، وبعض بدعهم تصل إلى الشرك كعبادة الأموات، والاستغاثة بالأموات من أصحاب القبور وغيرهم، وكدعاء البدوي، والاستغاثة بـالبدوي، أو بـالحسين، أو ما أشبه هذا، كل هذا من الشرك الأكبر، وهكذا الطواف بالقبور أو بخشبة تصنع يطاف حولها، كل هذا من المنكرات العظيمة. والطواف عبادة لله حول الكعبة، ومن طاف على قبر أو خشبة أو غير ذلك يطوف تعبدًا لغير الله لصاحب القبر، أو لمن وضع الخشبة، أو للخشبة نفسها يدعوها ويعتقد فيها، صار كفرًا أكبر، نسأل الله العافية. فالواجب عليك أن تتبصر في دينك، وأن تجتهد في تدبر القرآن الكريم، والإكثار من تلاوته، مع السنة المطهرة والعناية بها، تحفظ بلوغ المرام، عمدة الحديث حتى تستفيد، مع سؤال أهل العلم المعروفين بالعقيدة الطيبة، والسيرة الحميدة.  وقد ذكرت لك من جملتهم: أنصار السنة في مصر، وأنصار السنة في السودان، وهكذا من يعرف بالعلم في بلادك علم السنة، والبعد عن الصوفية، والغلو في القبور، هذه علامات أهل السنة، علامات أهل السنة البعد عن الصوفية، والبعد عن الغلو في القبور، هذه من الدلائل على أن العالم من أهل السنة، إذا دعا إلى القرآن العظيم، والسنة المطهرة، وحذر من عبادة القبور، والاستغاثة بأهلها، ونحو ذلك، وابتعد عن بدع الصوفية، فهذه علامات العالم الملتزم صاحب السنة، نسأل الله للجميع التوفيق والهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18019/التحذير-من-الصوفية-ومن-بدعهم-وطقوسهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92213.mp3","categories":["الفرق والمذاهب"]},{"id":18893,"question":"هل كل الطرق الصوفية على خطأ أرجو ردًا قاطعًا؟أفادكم الله.","title":"هل الطرق الصوفية كلها خاطئة؟","answer":"الجواب: الطرق الصوفية محدثة، وهي من البدع، وهي متفاوتة: بعضها شر من بعض، والرسول -عليه الصلاة والسلام- قال: من عمل عملًا ليس عليه أمرنا فهو رد وقال -عليه الصلاة والسلام-: من أحدث في أمرنا هذا ما ليس منه فهو رد فالطرق لا نحصيها، وإحصاؤها يحتاج إلى تعب كثير، ومراجعة كتب كثيرة، لكنها في الجملة محدثة التيجانية والبرهانية والخلوتية والقادرية والنقشبندية، وطرق أخرى لكنها متفاوتة بعضها شر من بعض. فينبغي لك يا أخي، اجتنابها كلها، وأن تلزم طريقة نبيك محمد -عليه الصلاة والسلام- التي درج عليها أصحابه -رضي الله عنهم وأرضاهم- والتابعون لهم بإحسان من الأئمة الأربعة وغيرهم، الزم طريق محمد -عليه الصلاة والسلام- وهي فعل ما أمر الله به ورسوله، وترك ما نهى الله عنه ورسوله، هذه الطريقة المحمدية التي جاء بها نبينا -عليه الصلاة والسلام-. وعليك بسؤال أهل العلم المعروفين بالاستقامة على دين الله، والبعد عن طرق الصوفية، عليك بسؤالهم عما أشكل عليك، والجماع لهذا هو أن تلزم ما أمر الله به ورسوله، وأن تنتهي عما نهى الله عنه ورسوله، مما بينه أهل العلم، كما في الصحيحين صحيح البخاري و مسلم والسنن الأربع وفي كتاب المنتقى لابن تيمية، وبلوغ المرام للحافظ ابن حجر وعمدة الحديث للشيخ: عبد الغني بن عبد الواحد المقدسي وغيرها من كتب الحديث، وهكذا مثل زاد المعاد في هدي خير العباد للعلامة ابن القيم -رحمه الله- كل هؤلاء أوضحوا طريقه -عليه الصلاة والسلام- وبينوا سبيله -عليه الصلاة والسلام-، نعم.","link":"https://binbaz.org.sa/fatwas/18035/هل-الطرق-الصوفية-كلها-خاطىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92304.mp3","categories":["الفرق والمذاهب"]},{"id":19366,"question":"يسأل أخونا سؤاله الأخير فيقول: قرأت كتابًا بعنوان: \"الفيوضات الربانية في المآثر والأوراد القادرية\" جمع وترتيب: إسماعيل بن السيد محمد سعيد القادري، والكتاب مطبوع في مصر، ويضم الكتاب مجموعة كبيرة من أشعار وأوراد منسوبة إلى الشيخ عبد القادر الجيلاني، ما رأيكم في هذا الكتاب؟","title":"بيان حال كتب المتصوفة","answer":"الجواب: هذا الكتاب لم أطلع عليه، ولا أعلم حقيقة حاله، ولكن كثير من المنتسبين للتصوف يكتبون كتابات لا وجه لها، ولا صحة لها، ولا ينبغي أن تعتمد كتاباتهم إلا من عرف بالاستقامة، وصلاح العقيدة، وعرف بالعلم والبصيرة بأحاديث الرسول ﷺ حتى يعلم أنه أتى بأدلة شرعية يعتمد عليها، والشيخ عبد القادر الجيلاني وآخرون من أهل العلم الذين يعرفون بالزهد، والورع؛ يكذب عليهم كثيرًا، وينسب إليهم أشياء من الباطل، بالنسبة إلى المنتسبين إلى التصوف؛ لا ينبغي أن يعترف بها، ولا ينبغي أن يتعلق عليها. وهو رجل صالح معروف، وفقيه معروف حنبلي، ولكن المنتسبين إليه ينسبون إليه أشياء لا حقيقة لها، ولا توافق الشرع. فينبغي التحرز من ذلك، والحذر من ذلك، وأن لا يعتمد على شيء من ذلك إلا ما وافق الكتاب والسنة، سواء كان ذلك ينسب إليه أو إلى غيره، فالاعتماد في هذه الأمور على ما دل عليه كتاب الله، وسنة رسوله محمد عليه الصلاة والسلام، مما ثبت في الأحاديث الصحيحة، ولا يجوز للمسلم أن يعتمد على قول فلان، أو رأي فلان مما ينسبه الناس إلى فلان أو فلان من الأئمة المعروفين أو غيرهم، بل يعرض ذلك كله على الكتاب، والسنة، فما وافقهما أو أحدهما قبل، وما لا فلا، كما قال الله : يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُوْلِي الأَمْرِ مِنْكُمْ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا[النساء:59]. فالواجب رد ما يتنازع به الناس، ورد ما يرويه الناس عن الأئمة الأربعة أو غيرهم، أو عن الأوزاعي، أو عن إسحاق بن راهويه أو عن من دونهم، أو عن الشيخ عبد القادر الجيلاني، أو الجنيد، أو أبي سليمان الداراني، أو فلان أو فلان، كل ذلك يجب أن يرد إلى الكتاب، والسنة، وأن لا يقبل على علاته لمجرد النسبة، بل يجب أن تعرض أقوال الناس وآراء الناس على الميزان العادل، على كلام الله  وما صح عن رسوله محمد عليه الصلاة والسلام، هذا هو الميزان عند أهل العلم والإيمان، فما وافقهما أو أحدهما فهو الحق، وما خالفهما فهو الباطل، والله المستعان.  المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18585/بيان-حال-كتب-المتصوفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_942/nour_94207.mp3","categories":["الفرق والمذاهب"]},{"id":19395,"question":"من هم مجوس هذه الأمة شيخ عبد العزيز؟","title":"مجوس هذه الأمة","answer":"الجواب: هم القدرية النفاة، الذين نفوا القدر وقالوا: الأمر أُنُف، فإن المجوس يقولون: إن للعباد إلهين: النور والظلمة، ويقولون: النور خلق الخير والظلمة خلقت الشر، فشابههم نفاة القدر حيث جعلوا لله شريكًا في أفعالهم وأنهم يخلقون أفعالهم، نسأل الله العافية. المقدم: جزاكم الله خيرًا. إذًا القول الفصل في هذا ألا يخوض المسلمون في باب القضاء والقدر؟ الشيخ: نعم، يؤمنوا بالقدر، ولا يخوضوا في ذلك خوض المبتدعة، بل يؤمنوا بذلك ويسلموا لذلك، ويعلموا أن الله قدر الأشياء وعلمها وأحصاها، وأن العبد له مشيئة وله إرادة وله اختيار، لكنه لا يخرج بذلك عما قدره الله . المقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/18619/مجوس-هذه-الامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_935/nour_93503.mp3","categories":["الفرق والمذاهب"]}]
